pub fn ore_vein_type_for_toggle(vein_toggle: f64) -> OreVeinType {
    if vein_toggle > 0.0 {
        ORE_VEIN_TYPES[0]
    } else {
        ORE_VEIN_TYPES[1]
    }
}

pub fn ore_vein_richness(veininess_ridged: f64) -> f64 {
    clamped_map(
        veininess_ridged,
        ORE_VEINIFIER_CONSTANTS.veininess_threshold,
        ORE_VEINIFIER_CONSTANTS.max_richness_threshold,
        ORE_VEINIFIER_CONSTANTS.min_richness,
        ORE_VEINIFIER_CONSTANTS.max_richness,
    )
}

pub fn ore_vein_decision(input: OreVeinDecisionInput) -> Option<&'static str> {
    let default_state = input.debug_ore_veins.then_some("minecraft:air");
    let vein_type = ore_vein_type_for_toggle(input.vein_toggle);
    let veininess_ridged = input.vein_toggle.abs();
    let distance_from_top = vein_type.max_y - input.y;
    let distance_from_bottom = input.y - vein_type.min_y;
    if distance_from_bottom < 0 || distance_from_top < 0 {
        return default_state;
    }

    let distance_from_edge = distance_from_top.min(distance_from_bottom);
    let edge_roundoff = clamped_map(
        f64::from(distance_from_edge),
        0.0,
        f64::from(ORE_VEINIFIER_CONSTANTS.edge_roundoff_begin),
        -ORE_VEINIFIER_CONSTANTS.max_edge_roundoff,
        0.0,
    );
    if veininess_ridged + edge_roundoff < ORE_VEINIFIER_CONSTANTS.veininess_threshold {
        return default_state;
    }
    if input.solidness_random > ORE_VEINIFIER_CONSTANTS.vein_solidness {
        return default_state;
    }
    if input.vein_ridged >= 0.0 {
        return default_state;
    }

    let richness = ore_vein_richness(veininess_ridged);
    if input.richness_random < richness
        && input.vein_gap > ORE_VEINIFIER_CONSTANTS.skip_ore_if_gap_noise_is_below
    {
        if input.raw_ore_random < ORE_VEINIFIER_CONSTANTS.chance_of_raw_ore_block {
            Some(vein_type.raw_ore_block)
        } else {
            Some(vein_type.ore)
        }
    } else if input.debug_ore_veins {
        Some("minecraft:oak_button")
    } else {
        Some(vein_type.filler)
    }
}

pub fn ore_vein_decision_at(
    ore_factory: PositionalRandomFactory,
    x: i32,
    y: i32,
    z: i32,
    vein_toggle: f64,
    vein_ridged: f64,
    vein_gap: f64,
    debug_ore_veins: bool,
) -> Option<&'static str> {
    ore_vein_decision_after_toggle(
        ore_factory,
        x,
        y,
        z,
        vein_toggle,
        || vein_ridged,
        || vein_gap,
        debug_ore_veins,
    )
}

struct OreVeinMaterialRule {
    ore_factory: PositionalRandomFactory,
    debug_ore_veins: bool,
}

impl OreVeinMaterialRule {
    fn try_apply(
        &self,
        noise_chunk: &NoiseChunk,
        x: i32,
        y: i32,
        z: i32,
        timings: &mut LiveTerrainTimings,
        detailed_timing: bool,
    ) -> Option<&'static str> {
        if !(ORE_VEIN_TYPES[0].min_y..=ORE_VEIN_TYPES[0].max_y).contains(&y)
            && !(ORE_VEIN_TYPES[1].min_y..=ORE_VEIN_TYPES[1].max_y).contains(&y)
        {
            return None;
        }
        timings.ore_vein_samples += 1;
        let vein_toggle = if detailed_timing {
            let ore_lookup_started = Instant::now();
            let vein_toggle = noise_chunk.cached_vein_toggle(x, y, z);
            timings.fill_ore_vein_lookup_us += ore_lookup_started.elapsed().as_micros();
            vein_toggle
        } else {
            noise_chunk.cached_vein_toggle(x, y, z)
        };

        if detailed_timing {
            let ore_decision_started = Instant::now();
            let result = ore_vein_decision_after_toggle(
                self.ore_factory,
                x,
                y,
                z,
                vein_toggle,
                || noise_chunk.vein_ridged_at(x, y, z),
                || noise_chunk.vein_gap_at(x, y, z),
                self.debug_ore_veins,
            );
            timings.fill_ore_decision_us += ore_decision_started.elapsed().as_micros();
            result
        } else {
            ore_vein_decision_after_toggle(
                self.ore_factory,
                x,
                y,
                z,
                vein_toggle,
                || noise_chunk.vein_ridged_at(x, y, z),
                || noise_chunk.vein_gap_at(x, y, z),
                self.debug_ore_veins,
            )
        }
    }
}

struct NoiseMaterialRuleList {
    default_block: &'static str,
    ore_vein_rule: Option<OreVeinMaterialRule>,
}

impl NoiseMaterialRuleList {
    fn new(settings: &NoiseGeneratorSettings, ore_factory: PositionalRandomFactory) -> Self {
        Self {
            default_block: settings.default_block,
            ore_vein_rule: settings.ore_veins_enabled.then_some(OreVeinMaterialRule {
                ore_factory,
                debug_ore_veins: false,
            }),
        }
    }

    fn calculate(
        &self,
        aquifer: Option<&mut NoiseBasedAquifer>,
        noise_chunk: &NoiseChunk,
        settings: &NoiseGeneratorSettings,
        x: i32,
        y: i32,
        z: i32,
        density: f64,
        timings: &mut LiveTerrainTimings,
        detailed_timing: bool,
    ) -> &'static str {
        // Mirrors Java's `MaterialRuleList`: the aquifer filler runs first and
        // may return a fluid/air block. Returning `None` means the slot remains
        // solid, so the next filler (OreVeinifier) gets a chance before the
        // generator falls back to the default block.
        let aquifer_substance = if density > 0.0 {
            None
        } else if let Some(aquifer) = aquifer {
            timings.aquifer_calls += 1;
            if detailed_timing {
                let aquifer_started = Instant::now();
                let substance = aquifer.compute_substance(noise_chunk, x, y, z, density);
                timings.fill_aquifer_compute_us += aquifer_started.elapsed().as_micros();
                substance
            } else {
                aquifer.compute_substance(noise_chunk, x, y, z, density)
            }
        } else {
            Some(global_fluid_status(y, settings.sea_level, settings.default_fluid).at(y))
        };

        if let Some(block) = aquifer_substance {
            return block;
        }

        if let Some(rule) = &self.ore_vein_rule {
            if let Some(block) = rule.try_apply(noise_chunk, x, y, z, timings, detailed_timing) {
                return block;
            }
        }

        self.default_block
    }
}

fn ore_vein_decision_after_toggle<R, G>(
    ore_factory: PositionalRandomFactory,
    x: i32,
    y: i32,
    z: i32,
    vein_toggle: f64,
    vein_ridged: R,
    vein_gap: G,
    debug_ore_veins: bool,
) -> Option<&'static str>
where
    R: FnOnce() -> f64,
    G: FnOnce() -> f64,
{
    let default_state = debug_ore_veins.then_some("minecraft:air");
    let vein_type = ore_vein_type_for_toggle(vein_toggle);
    let veininess_ridged = vein_toggle.abs();
    let distance_from_top = vein_type.max_y - y;
    let distance_from_bottom = y - vein_type.min_y;
    if distance_from_bottom < 0 || distance_from_top < 0 {
        return default_state;
    }

    let distance_from_edge = distance_from_top.min(distance_from_bottom);
    let edge_roundoff = clamped_map(
        f64::from(distance_from_edge),
        0.0,
        f64::from(ORE_VEINIFIER_CONSTANTS.edge_roundoff_begin),
        -ORE_VEINIFIER_CONSTANTS.max_edge_roundoff,
        0.0,
    );
    if veininess_ridged + edge_roundoff < ORE_VEINIFIER_CONSTANTS.veininess_threshold {
        return default_state;
    }

    // Java OreVeinifier only creates/samples the positional random after the
    // range and veininess checks pass.
    let mut positional_random = ore_factory.at(x, y, z);
    let solidness_random = f64::from(positional_random.next_f32());
    if solidness_random > ORE_VEINIFIER_CONSTANTS.vein_solidness {
        return default_state;
    }
    if vein_ridged() >= 0.0 {
        return default_state;
    }

    let richness = ore_vein_richness(veininess_ridged);
    let richness_random = f64::from(positional_random.next_f32());
    if richness_random < richness
        && vein_gap() > ORE_VEINIFIER_CONSTANTS.skip_ore_if_gap_noise_is_below
    {
        let raw_ore_random = f64::from(positional_random.next_f32());
        if raw_ore_random < ORE_VEINIFIER_CONSTANTS.chance_of_raw_ore_block {
            Some(vein_type.raw_ore_block)
        } else {
            Some(vein_type.ore)
        }
    } else if debug_ore_veins {
        Some("minecraft:oak_button")
    } else {
        Some(vein_type.filler)
    }
}

fn clamped_map(value: f64, from_min: f64, from_max: f64, to_min: f64, to_max: f64) -> f64 {
    let clamped = value.clamp(from_min, from_max);
    let progress = (clamped - from_min) / (from_max - from_min);
    to_min + progress * (to_max - to_min)
}

fn apply_underground_ore_decoration_to_chunk(
    chunk: &mut LevelChunk,
    biome_source_model: &BiomeSourceModel,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    decoration_region_biome_steps: Option<&[&'static [&'static [&'static str]]]>,
) -> usize {
    apply_underground_ore_decoration_to_chunk_with_context(
        chunk,
        biome_source_model,
        settings,
        seed,
        decoration_region_biome_steps,
        None,
        None,
    )
}

fn apply_underground_ore_decoration_to_chunk_with_context(
    chunk: &mut LevelChunk,
    biome_source_model: &BiomeSourceModel,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    decoration_region_biome_steps: Option<&[&'static [&'static [&'static str]]]>,
    decoration_context_chunks: Option<&HashMap<ChunkPos, LightweightTreeContextChunk>>,
    precomputed_source_steps: Option<&DecorationBiomeStepsByChunk>,
) -> usize {
    let total_started = Instant::now();
    if settings.id != "minecraft:overworld" && settings.id != "minecraft:large_biomes" {
        return 0;
    }

    let Some(router) =
        builtin_noise_router(noise_router_id_for_settings(*settings)).map(|entry| entry.router)
    else {
        return 0;
    };
    let climate_sampler = ClimateSampler::from_noise_router(&router, seed, *settings);
    let owned_source_steps_cache;
    let source_steps_cache = if let Some(source_steps) = precomputed_source_steps {
        source_steps
    } else if decoration_region_biome_steps.is_some() {
        owned_source_steps_cache = DecorationBiomeStepsByChunk::new();
        &owned_source_steps_cache
    } else {
        owned_source_steps_cache = source_decoration_biome_steps_cache(
            chunk.pos,
            1,
            biome_source_model,
            settings,
            &climate_sampler,
        );
        &owned_source_steps_cache
    };
    let started = Instant::now();
    let global_biome_steps = possible_biome_feature_steps_for_source(biome_source_model);
    let target_possible_steps = decoration_region_biome_steps
        .map(|steps| steps.to_vec())
        .unwrap_or_default();
    let feature_source_steps = if !global_biome_steps.is_empty() {
        &global_biome_steps
    } else {
        &target_possible_steps
    };
    let features_per_step = match build_features_per_step(feature_source_steps, true) {
        Ok(features) => features,
        Err(_) => return 0,
    };
    let feature_sort_ms = started.elapsed().as_millis();

    let mut placed = 0;
    let mut calls = 0;
    let owned_context_chunks;
    let context_chunks = if let Some(context_chunks) = decoration_context_chunks {
        context_chunks
    } else {
        owned_context_chunks =
            build_underground_ore_decoration_context_chunks(chunk.pos, settings, seed);
        &owned_context_chunks
    };
    let mut block_cache = OreBlockCache::from_chunk_with_read_context(chunk, context_chunks);
    let mut biome_steps_ms = 0_u128;
    let mut plan_ms = 0_u128;
    let mut possible_step_sets = 0_usize;
    let mut ore_candidate_us = 0_u128;
    let mut ore_block_us = 0_u128;
    let mut ore_origin_us = 0_u128;
    let mut ore_total_us = 0_u128;
    let mut ore_configured_calls = 0_usize;
    let mut ore_candidate_count = 0_usize;
    let mut ore_in_chunk_candidates = 0_usize;
    let mut ore_model_cache: HashMap<&'static str, (PlacedOreFeatureModel, OreConfigurationModel)> =
        HashMap::new();
    let mut disk_model_cache: HashMap<
        &'static str,
        (PlacedDiskFeatureModel, DiskConfigurationModel),
    > = HashMap::new();
    let placement_started = Instant::now();
    for source_z in chunk.pos.z - 1..=chunk.pos.z + 1 {
        for source_x in chunk.pos.x - 1..=chunk.pos.x + 1 {
            let source_pos = ChunkPos {
                x: source_x,
                z: source_z,
            };
            let started = Instant::now();
            let possible_steps = decoration_region_biome_steps
                .map(|steps| steps.to_vec())
                .or_else(|| source_steps_cache.get(&source_pos).cloned())
                .unwrap_or_else(|| {
                    possible_biome_feature_steps_for_decoration_region(
                        source_pos,
                        biome_source_model,
                        settings,
                        &climate_sampler,
                    )
                });
            if decoration_region_biome_steps.is_none() {
                biome_steps_ms += started.elapsed().as_millis();
            }
            if possible_steps.is_empty() {
                continue;
            }
            possible_step_sets += possible_steps.len();

            let skip_biome_filter = biome_steps_share_decoration_step_features(
                &possible_steps,
                GenerationDecorationStep::UndergroundOres,
            );
            let started = Instant::now();
            let plan = biome_decoration_feature_plan(
                seed,
                source_pos.x,
                source_pos.z,
                settings.noise.min_y.div_euclid(16),
                &features_per_step,
                &possible_steps,
            );
            plan_ms += started.elapsed().as_millis();

            for call in plan.feature_calls.iter().filter(|call| {
                call.step_index == GenerationDecorationStep::UndergroundOres as usize
            }) {
                calls += 1;
                if let Some(report) = {
                    if !ore_model_cache.contains_key(call.feature) {
                        if let Some(feature) = placed_ore_feature(call.feature) {
                            if let Some(config) =
                                configured_ore_configuration(feature.configured_feature)
                            {
                                ore_model_cache.insert(call.feature, (feature, config));
                            }
                        }
                    }
                    ore_model_cache.get(call.feature).map(|(feature, config)| {
                        place_ore_feature_in_chunk(
                            &*chunk,
                            &mut block_cache,
                            source_pos,
                            biome_source_model,
                            settings,
                            seed,
                            &climate_sampler,
                            call.feature,
                            feature,
                            config,
                            call.seed,
                            skip_biome_filter,
                        )
                    })
                } {
                    placed += report.placed;
                    ore_candidate_us += report.candidate_us;
                    ore_block_us += report.block_us;
                    ore_origin_us += report.origin_us;
                    ore_total_us += report.total_us;
                    ore_configured_calls += report.configured_calls;
                    ore_candidate_count += report.candidate_count;
                    ore_in_chunk_candidates += report.in_chunk_candidates;
                    continue;
                }

                if !disk_model_cache.contains_key(call.feature) {
                    if let Some(feature) = placed_disk_feature(call.feature) {
                        if let Some(config) =
                            configured_disk_configuration(feature.configured_feature)
                        {
                            disk_model_cache.insert(call.feature, (feature, config));
                        }
                    }
                }
                if let Some((feature, config)) = disk_model_cache.get(call.feature) {
                    let disk_placed = place_disk_feature_in_chunk(
                        &mut block_cache,
                        source_pos,
                        biome_source_model,
                        settings,
                        &climate_sampler,
                        call.feature,
                        feature,
                        config,
                        call.seed,
                        skip_biome_filter,
                    );
                    placed += disk_placed;
                }
            }
        }
    }
    let flush_started = Instant::now();
    block_cache.flush_to_chunk(chunk);
    let flush_ms = flush_started.elapsed().as_millis();
    let placement_ms = placement_started.elapsed().as_millis();
    if std::env::var_os("RUSTCRAFT_WORLDGEN_ORE_DEBUG").is_some() {
        eprintln!(
            "[ore-debug] total={}ms biome_steps={}ms possible_steps={} global_steps={} feature_sort={}ms plan={}ms placement={}ms flush={}ms calls={} configured_calls={} candidates={} in_chunk={} configured_time={}us origin_time={}us candidate_time={}us block_time={}us placed={}",
            total_started.elapsed().as_millis(),
            biome_steps_ms,
            possible_step_sets,
            global_biome_steps.len(),
            feature_sort_ms,
            plan_ms,
            placement_ms,
            flush_ms,
            calls,
            ore_configured_calls,
            ore_candidate_count,
            ore_in_chunk_candidates,
            ore_total_us,
            ore_origin_us,
            ore_candidate_us,
            ore_block_us,
            placed
        );
    }

    placed
}

fn apply_underground_ore_decoration_from_source_into_region(
    chunks: &mut BTreeMap<ChunkPos, LevelChunk>,
    source_pos: ChunkPos,
    biome_source_model: &BiomeSourceModel,
    settings: &NoiseGeneratorSettings,
    seed: i64,
    decoration_region_biome_steps: Option<&[&'static [&'static [&'static str]]]>,
) -> usize {
    if settings.id != "minecraft:overworld" && settings.id != "minecraft:large_biomes" {
        return 0;
    }
    let Some(source_chunk) = chunks.get(&source_pos).cloned() else {
        return 0;
    };
    let Some(router) =
        builtin_noise_router(noise_router_id_for_settings(*settings)).map(|entry| entry.router)
    else {
        return 0;
    };
    let climate_sampler = ClimateSampler::from_noise_router(&router, seed, *settings);
    let possible_steps = decoration_region_biome_steps
        .map(|steps| steps.to_vec())
        .unwrap_or_else(|| {
            possible_biome_feature_steps_for_decoration_region(
                source_pos,
                biome_source_model,
                settings,
                &climate_sampler,
            )
        });
    if possible_steps.is_empty() {
        return 0;
    }

    let global_biome_steps = possible_biome_feature_steps_for_source(biome_source_model);
    let feature_source_steps = if !global_biome_steps.is_empty() {
        &global_biome_steps
    } else {
        &possible_steps
    };
    let features_per_step = match build_features_per_step(feature_source_steps, true) {
        Ok(features) => features,
        Err(_) => return 0,
    };
    let plan = biome_decoration_feature_plan(
        seed,
        source_pos.x,
        source_pos.z,
        settings.noise.min_y.div_euclid(16),
        &features_per_step,
        &possible_steps,
    );
    let skip_biome_filter = biome_steps_share_decoration_step_features(
        &possible_steps,
        GenerationDecorationStep::UndergroundOres,
    );
    let Some(mut block_cache) = OreBlockCache::from_region_chunks(source_pos, chunks) else {
        return 0;
    };
    let mut placed = 0;
    let mut ore_model_cache: HashMap<&'static str, (PlacedOreFeatureModel, OreConfigurationModel)> =
        HashMap::new();
    let mut disk_model_cache: HashMap<
        &'static str,
        (PlacedDiskFeatureModel, DiskConfigurationModel),
    > = HashMap::new();

    for call in plan
        .feature_calls
        .iter()
        .filter(|call| call.step_index == GenerationDecorationStep::UndergroundOres as usize)
    {
        if !ore_model_cache.contains_key(call.feature) {
            if let Some(feature) = placed_ore_feature(call.feature) {
                if let Some(config) = configured_ore_configuration(feature.configured_feature) {
                    ore_model_cache.insert(call.feature, (feature, config));
                }
            }
        }
        if let Some((feature, config)) = ore_model_cache.get(call.feature) {
            placed += place_ore_feature_in_chunk(
                &source_chunk,
                &mut block_cache,
                source_pos,
                biome_source_model,
                settings,
                seed,
                &climate_sampler,
                call.feature,
                feature,
                config,
                call.seed,
                skip_biome_filter,
            )
            .placed;
            continue;
        }

        if !disk_model_cache.contains_key(call.feature) {
            if let Some(feature) = placed_disk_feature(call.feature) {
                if let Some(config) = configured_disk_configuration(feature.configured_feature) {
                    disk_model_cache.insert(call.feature, (feature, config));
                }
            }
        }
        if let Some((feature, config)) = disk_model_cache.get(call.feature) {
            placed += place_disk_feature_in_chunk(
                &mut block_cache,
                source_pos,
                biome_source_model,
                settings,
                &climate_sampler,
                call.feature,
                feature,
                config,
                call.seed,
                skip_biome_filter,
            );
        }
    }

    block_cache.flush_to_chunks(chunks);
    placed
}



#[derive(Debug, Clone)]
struct TreeDecorationHeights {
    ocean_floor: [i32; 16 * 16],
    world_surface: [i32; 16 * 16],
    motion_blocking: [i32; 16 * 16],
    motion_blocking_no_leaves: [i32; 16 * 16],
}

#[derive(Clone, Copy)]
enum SourceTerrainHeights<'a> {
    Full(&'a TreeDecorationHeights),
    Lazy(&'a LightweightTreeContextChunk),
}

impl SourceTerrainHeights<'_> {
    fn local_height(self, heightmap: HeightmapKind, local_x: usize, local_z: usize) -> i32 {
        match self {
            SourceTerrainHeights::Full(heights) => {
                heights.local_height(heightmap, local_x, local_z)
            }
            SourceTerrainHeights::Lazy(chunk) => chunk
                .terrain_heights
                .local_height(heightmap, local_x, local_z),
        }
    }

    fn world_height(
        self,
        source_pos: ChunkPos,
        heightmap: HeightmapKind,
        world_x: i32,
        world_z: i32,
        fallback_y: i32,
    ) -> i32 {
        if world_x.div_euclid(16) != source_pos.x || world_z.div_euclid(16) != source_pos.z {
            return fallback_y;
        }
        self.local_height(
            heightmap,
            world_x.rem_euclid(16) as usize,
            world_z.rem_euclid(16) as usize,
        )
    }
}

impl TreeDecorationHeights {
    fn local_height(&self, heightmap: HeightmapKind, local_x: usize, local_z: usize) -> i32 {
        let index = local_z * 16 + local_x;
        match heightmap {
            HeightmapKind::WorldSurface | HeightmapKind::WorldSurfaceWg => {
                self.world_surface[index]
            }
            HeightmapKind::OceanFloor | HeightmapKind::OceanFloorWg => self.ocean_floor[index],
            HeightmapKind::MotionBlocking => self.motion_blocking[index],
            HeightmapKind::MotionBlockingNoLeaves => self.motion_blocking_no_leaves[index],
        }
    }
}

fn tree_decoration_terrain_heights_from_wg(
    chunk: &LevelChunk,
    settings: &NoiseGeneratorSettings,
) -> TreeDecorationHeights {
    let mut ocean_floor = [settings.sea_level + 1; 16 * 16];
    let mut world_surface = [settings.sea_level + 1; 16 * 16];
    let mut motion_blocking = [settings.sea_level + 1; 16 * 16];
    let mut motion_blocking_no_leaves = [settings.sea_level + 1; 16 * 16];
    for z in 0..16 {
        for x in 0..16 {
            let index = z * 16 + x;
            ocean_floor[index] = chunk
                .heightmap_value(HeightmapKind::OceanFloorWg, x, z)
                .or_else(|| chunk.heightmap_value(HeightmapKind::OceanFloor, x, z))
                .or_else(|| chunk.heightmap_value(HeightmapKind::WorldSurfaceWg, x, z))
                .unwrap_or(settings.sea_level + 1);
            world_surface[index] = chunk
                .heightmap_value(HeightmapKind::WorldSurfaceWg, x, z)
                .or_else(|| chunk.heightmap_value(HeightmapKind::WorldSurface, x, z))
                .unwrap_or(ocean_floor[index]);
            motion_blocking[index] = chunk
                .heightmap_value(HeightmapKind::MotionBlocking, x, z)
                .unwrap_or(world_surface[index]);
            motion_blocking_no_leaves[index] = chunk
                .heightmap_value(HeightmapKind::MotionBlockingNoLeaves, x, z)
                .unwrap_or(motion_blocking[index]);
        }
    }
    TreeDecorationHeights {
        ocean_floor,
        world_surface,
        motion_blocking,
        motion_blocking_no_leaves,
    }
}

fn tree_decoration_terrain_heights(
    chunk: &LevelChunk,
    settings: &NoiseGeneratorSettings,
) -> TreeDecorationHeights {
    let computed_ocean_floor = chunk.compute_heightmap_values(HeightmapKind::OceanFloor);
    let computed_world_surface = chunk.compute_heightmap_values(HeightmapKind::WorldSurface);
    let computed_motion_blocking = chunk.compute_heightmap_values(HeightmapKind::MotionBlocking);
    let computed_motion_blocking_no_leaves =
        chunk.compute_heightmap_values(HeightmapKind::MotionBlockingNoLeaves);
    let mut ocean_floor = computed_ocean_floor;
    let mut world_surface = computed_world_surface;
    let mut motion_blocking = computed_motion_blocking;
    let mut motion_blocking_no_leaves = computed_motion_blocking_no_leaves;
    for z in 0..16 {
        for x in 0..16 {
            let index = z * 16 + x;
            if ocean_floor[index] == 0 {
                ocean_floor[index] = chunk
                    .heightmap_value(HeightmapKind::OceanFloorWg, x, z)
                    .or_else(|| chunk.heightmap_value(HeightmapKind::WorldSurfaceWg, x, z))
                    .unwrap_or(settings.sea_level + 1);
            }
            if world_surface[index] == 0 {
                world_surface[index] = chunk
                    .heightmap_value(HeightmapKind::WorldSurfaceWg, x, z)
                    .unwrap_or(ocean_floor[index]);
            }
            if motion_blocking[index] == 0 {
                motion_blocking[index] = world_surface[index];
            }
            if motion_blocking_no_leaves[index] == 0 {
                motion_blocking_no_leaves[index] = motion_blocking[index];
            }
        }
    }
    TreeDecorationHeights {
        ocean_floor,
        world_surface,
        motion_blocking,
        motion_blocking_no_leaves,
    }
}


pub fn biome_generation_settings(id: &str) -> Option<&'static BiomeGenerationSettingsModel> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    BUILTIN_BIOME_GENERATION_SETTINGS.iter().find(|entry| {
        entry
            .biome
            .strip_prefix("minecraft:")
            .is_some_and(|entry_name| entry_name == name)
    })
}

pub fn biome_has_placed_feature(biome: &BiomeGenerationSettingsModel, feature: &str) -> bool {
    let name = feature.strip_prefix("minecraft:").unwrap_or(feature);
    biome.feature_steps.iter().any(|step| {
        step.iter().any(|entry| {
            entry
                .strip_prefix("minecraft:")
                .is_some_and(|entry_name| entry_name == name)
        })
    })
}

pub fn biome_spawns_for_category(
    biome: &BiomeGenerationSettingsModel,
    category: &str,
) -> &'static [MobSpawnerDataModel] {
    biome
        .spawners
        .iter()
        .find(|group| group.category == category)
        .map(|group| group.entries)
        .unwrap_or(&[])
}


pub fn simple_block_placement_plan(
    config: &SimpleBlockConfigurationModel,
    context: SimpleBlockPlacementContext,
    random: &mut RandomSourceKind,
) -> Option<SimpleBlockPlacementPlan> {
    let state = block_state_provider_sample_in_context_with_random(
        &config.to_place,
        random,
        BlockPredicateContext {
            min_y: 0,
            height: 0,
            block: context.origin_block,
            fluid: if matches!(context.origin_block, "minecraft:water" | "minecraft:lava") {
                context.origin_block
            } else {
                "minecraft:empty"
            },
            solid: !matches!(
                context.origin_block,
                "minecraft:air"
                    | "minecraft:cave_air"
                    | "minecraft:void_air"
                    | "minecraft:water"
                    | "minecraft:lava"
            ),
            replaceable: matches!(
                context.origin_block,
                "minecraft:air"
                    | "minecraft:cave_air"
                    | "minecraft:void_air"
                    | "minecraft:short_grass"
                    | "minecraft:tall_grass"
                    | "minecraft:fern"
                    | "minecraft:large_fern"
                    | "minecraft:bush"
                    | "minecraft:leaf_litter"
            ),
            unobstructed: true,
        },
        0,
        context.origin_block,
    )?;
    if !simple_block_can_survive(state, context) {
        return None;
    }
    if simple_block_is_double_plant(state) {
        if context.above_block != "minecraft:air" {
            return None;
        }
        return Some(SimpleBlockPlacementPlan {
            state,
            upper_state: Some(state),
            schedule_tick: config.schedule_tick,
        });
    }
    Some(SimpleBlockPlacementPlan {
        state,
        upper_state: None,
        schedule_tick: config.schedule_tick,
    })
}

pub fn simple_block_can_survive(state: &str, context: SimpleBlockPlacementContext) -> bool {
    if simple_block_is_plant(state) {
        return matches!(
            context.below_block,
            "minecraft:grass_block"
                | "minecraft:dirt"
                | "minecraft:coarse_dirt"
                | "minecraft:podzol"
                | "minecraft:farmland"
                | "minecraft:moss_block"
        );
    }
    true
}

fn simple_block_is_plant(state: &str) -> bool {
    matches!(
        state,
        "minecraft:short_grass"
            | "minecraft:fern"
            | "minecraft:large_fern"
            | "minecraft:tall_grass"
            | "minecraft:bush"
            | "minecraft:dandelion"
            | "minecraft:poppy"
            | "minecraft:azure_bluet"
            | "minecraft:oxeye_daisy"
            | "minecraft:cornflower"
            | "minecraft:orange_tulip"
            | "minecraft:red_tulip"
            | "minecraft:pink_tulip"
            | "minecraft:white_tulip"
            | "minecraft:lily_of_the_valley"
            | "minecraft:sunflower"
            | "minecraft:rose_bush"
            | "minecraft:peony"
            | "minecraft:lilac"
    )
}

fn simple_block_is_double_plant(state: &str) -> bool {
    matches!(
        state,
        "minecraft:sunflower"
            | "minecraft:rose_bush"
            | "minecraft:peony"
            | "minecraft:lilac"
            | "minecraft:tall_grass"
            | "minecraft:large_fern"
    )
}

pub fn validate_replace_sphere_config(
    config: ReplaceSphereConfigurationModel,
) -> Result<ReplaceSphereConfigurationModel, &'static str> {
    if config.target_state.is_empty() || config.replace_state.is_empty() {
        Err("replace sphere target and replacement states must not be empty")
    } else if !(0..=12).contains(&config.radius_min)
        || !(0..=12).contains(&config.radius_max)
        || config.radius_min > config.radius_max
    {
        Err("replace sphere radius bounds must be ordered in 0..=12")
    } else {
        Ok(config)
    }
}

pub fn replace_sphere_radius(config: ReplaceSphereConfigurationModel, roll: i32) -> i32 {
    let span = (config.radius_max - config.radius_min + 1).max(1);
    config.radius_min + roll.rem_euclid(span)
}

pub fn replace_sphere_find_target(
    origin: BlockPos,
    min_y: i32,
    max_y: i32,
    column_states: &[&str],
    target_state: &str,
) -> Option<BlockPos> {
    let mut y = origin.y.clamp(min_y + 1, max_y);
    while y > min_y + 1 {
        let offset = origin.y.clamp(min_y + 1, max_y) - y;
        if column_states.get(offset as usize).copied() == Some(target_state) {
            return Some(BlockPos {
                x: origin.x,
                y,
                z: origin.z,
            });
        }
        y -= 1;
    }
    None
}

pub fn replace_sphere_positions(
    center: BlockPos,
    radius_x: i32,
    radius_y: i32,
    radius_z: i32,
) -> Vec<BlockPos> {
    let maximum_radius = radius_x.max(radius_y).max(radius_z);
    let mut positions = Vec::new();
    for dy in -radius_y..=radius_y {
        for dz in -radius_z..=radius_z {
            for dx in -radius_x..=radius_x {
                if dx.abs() + dy.abs() + dz.abs() <= maximum_radius {
                    positions.push(BlockPos {
                        x: center.x + dx,
                        y: center.y + dy,
                        z: center.z + dz,
                    });
                }
            }
        }
    }
    positions
}

pub fn basalt_pillar_can_start(origin_empty: bool, above_empty: bool) -> bool {
    origin_empty && !above_empty
}

pub fn basalt_pillar_hangoff_places(roll: i32) -> bool {
    roll.rem_euclid(10) != 0
}

pub fn basalt_pillar_base_places(dx: i32, dz: i32, roll: i32) -> bool {
    let probability = dx.abs() * dz.abs();
    roll.rem_euclid(10) < 10 - probability
}

pub fn basalt_pillar_placement_plan(
    origin: BlockPos,
    empty_down: &[bool],
    outside_build_height: &[bool],
    hangoff_rolls: &[(i32, i32, i32, i32)],
    base_rolls: &[i32],
    base_drop_empty_below: &[&[bool]],
    base_supported_below: &[bool],
) -> Vec<BasaltPillarPlacementBlock> {
    let mut blocks = Vec::new();
    let mut y_steps = 0usize;
    let mut north_active = true;
    let mut south_active = true;
    let mut west_active = true;
    let mut east_active = true;
    while empty_down.get(y_steps).copied().unwrap_or(false) {
        if outside_build_height.get(y_steps).copied().unwrap_or(false) {
            return blocks;
        }
        let pos = BlockPos {
            x: origin.x,
            y: origin.y - y_steps as i32,
            z: origin.z,
        };
        blocks.push(BasaltPillarPlacementBlock {
            pos,
            kind: BasaltPillarBlockKind::Core,
        });
        let rolls = hangoff_rolls.get(y_steps).copied().unwrap_or((0, 0, 0, 0));
        if north_active && basalt_pillar_hangoff_places(rolls.0) {
            blocks.push(BasaltPillarPlacementBlock {
                pos: offset_horizontal(pos, HorizontalDirection::North, 1),
                kind: BasaltPillarBlockKind::HangOff,
            });
        } else {
            north_active = false;
        }
        if south_active && basalt_pillar_hangoff_places(rolls.1) {
            blocks.push(BasaltPillarPlacementBlock {
                pos: offset_horizontal(pos, HorizontalDirection::South, 1),
                kind: BasaltPillarBlockKind::HangOff,
            });
        } else {
            south_active = false;
        }
        if west_active && basalt_pillar_hangoff_places(rolls.2) {
            blocks.push(BasaltPillarPlacementBlock {
                pos: offset_horizontal(pos, HorizontalDirection::West, 1),
                kind: BasaltPillarBlockKind::HangOff,
            });
        } else {
            west_active = false;
        }
        if east_active && basalt_pillar_hangoff_places(rolls.3) {
            blocks.push(BasaltPillarPlacementBlock {
                pos: offset_horizontal(pos, HorizontalDirection::East, 1),
                kind: BasaltPillarBlockKind::HangOff,
            });
        } else {
            east_active = false;
        }
        y_steps += 1;
    }

    if y_steps == 0 {
        return blocks;
    }
    let base_y = origin.y - y_steps as i32;
    let mut base_index = 0usize;
    for dx in -3..=3 {
        for dz in -3..=3 {
            let roll = base_rolls.get(base_index).copied().unwrap_or(10);
            let drop_empty = base_drop_empty_below
                .get(base_index)
                .copied()
                .unwrap_or(&[]);
            let supported = base_supported_below
                .get(base_index)
                .copied()
                .unwrap_or(false);
            base_index += 1;
            if !basalt_pillar_base_places(dx, dz, roll) {
                continue;
            }
            let drop = drop_empty
                .iter()
                .take(3)
                .take_while(|empty| **empty)
                .count() as i32;
            if supported {
                blocks.push(BasaltPillarPlacementBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: base_y - drop,
                        z: origin.z + dz,
                    },
                    kind: BasaltPillarBlockKind::Base,
                });
            }
        }
    }
    blocks
}

pub fn basalt_columns_cannot_place_on(state: &str) -> bool {
    matches!(
        state,
        "minecraft:lava"
            | "minecraft:bedrock"
            | "minecraft:magma_block"
            | "minecraft:soul_sand"
            | "minecraft:nether_bricks"
            | "minecraft:nether_brick_fence"
            | "minecraft:nether_brick_stairs"
            | "minecraft:nether_wart"
            | "minecraft:chest"
            | "minecraft:spawner"
    )
}

pub fn basalt_columns_is_air_or_lava_ocean(state: &str, y: i32, lava_sea_level: i32) -> bool {
    state == "minecraft:air" || (state == "minecraft:lava" && y <= lava_sea_level)
}

pub fn basalt_columns_can_place_at(
    state: &str,
    below_state: &str,
    y: i32,
    lava_sea_level: i32,
) -> bool {
    basalt_columns_is_air_or_lava_ocean(state, y, lava_sea_level)
        && below_state != "minecraft:air"
        && !basalt_columns_cannot_place_on(below_state)
}

pub fn validate_column_feature_config(
    config: ColumnFeatureConfigurationModel,
) -> Result<ColumnFeatureConfigurationModel, &'static str> {
    if !(0..=3).contains(&config.reach_min)
        || !(0..=3).contains(&config.reach_max)
        || config.reach_min > config.reach_max
    {
        Err("column reach bounds must be ordered in 0..=3")
    } else if !(1..=10).contains(&config.height_min)
        || !(1..=10).contains(&config.height_max)
        || config.height_min > config.height_max
    {
        Err("column height bounds must be ordered in 1..=10")
    } else {
        Ok(config)
    }
}

pub fn basalt_columns_cluster_parameters(
    column_height: i32,
    clustered_roll: f32,
) -> (bool, i32, i32) {
    let clustered = clustered_roll < 0.9;
    let reach = column_height.min(if clustered { 5 } else { 8 });
    let count = if clustered { 50 } else { 15 };
    (clustered, reach, count)
}

pub fn basalt_column_blocks_from_surface(
    surface_pos: BlockPos,
    origin: BlockPos,
    column_height: i32,
    reach: i32,
    air_or_lava_ocean_above: &[bool],
    already_basalt_above: &[bool],
) -> Vec<BasaltColumnPlacementBlock> {
    let mut blocks = Vec::new();
    let step_limit = (surface_pos.x - origin.x).abs()
        + (surface_pos.y - origin.y).abs()
        + (surface_pos.z - origin.z).abs();
    if step_limit > reach {
        return blocks;
    }
    let mut blocks_y = column_height - step_limit / 2;
    let mut step = 0usize;
    while blocks_y >= 0 {
        if air_or_lava_ocean_above.get(step).copied().unwrap_or(false) {
            blocks.push(BasaltColumnPlacementBlock {
                pos: BlockPos {
                    x: surface_pos.x,
                    y: surface_pos.y + step as i32,
                    z: surface_pos.z,
                },
            });
        } else if !already_basalt_above.get(step).copied().unwrap_or(false) {
            break;
        }
        blocks_y -= 1;
        step += 1;
    }
    blocks
}

pub fn validate_delta_config(
    config: DeltaFeatureConfigurationModel,
) -> Result<DeltaFeatureConfigurationModel, &'static str> {
    let valid_size = (0..=16).contains(&config.size_min)
        && (0..=16).contains(&config.size_max)
        && config.size_min <= config.size_max;
    let valid_rim = (0..=16).contains(&config.rim_size_min)
        && (0..=16).contains(&config.rim_size_max)
        && config.rim_size_min <= config.rim_size_max;
    if config.contents.is_empty() || config.rim.is_empty() {
        Err("delta contents and rim states must not be empty")
    } else if !valid_size {
        Err("delta size bounds must be ordered in 0..=16")
    } else if !valid_rim {
        Err("delta rim size bounds must be ordered in 0..=16")
    } else {
        Ok(config)
    }
}

pub fn delta_cannot_replace(state: &str) -> bool {
    matches!(
        state,
        "minecraft:bedrock"
            | "minecraft:nether_bricks"
            | "minecraft:nether_brick_fence"
            | "minecraft:nether_brick_stairs"
            | "minecraft:nether_wart"
            | "minecraft:chest"
            | "minecraft:spawner"
    )
}

pub fn delta_is_clear(
    state: &str,
    contents: &str,
    up_air: bool,
    down_air: bool,
    north_air: bool,
    south_air: bool,
    west_air: bool,
    east_air: bool,
) -> bool {
    state != contents
        && !delta_cannot_replace(state)
        && !up_air
        && !down_air
        && !north_air
        && !south_air
        && !west_air
        && !east_air
}

pub fn delta_has_rim(spawn_roll: f64, rim_x: i32, rim_z: i32) -> bool {
    spawn_roll < 0.9 && rim_x != 0 && rim_z != 0
}

pub fn delta_candidate_offsets(radius_x: i32, radius_z: i32) -> Vec<(i32, i32)> {
    let radius_limit = radius_x.max(radius_z);
    let mut offsets = Vec::new();
    for dz in -radius_z..=radius_z {
        for dx in -radius_x..=radius_x {
            if dx.abs() + dz.abs() <= radius_limit {
                offsets.push((dx, dz));
            }
        }
    }
    offsets
}

pub fn glowstone_can_start(origin_empty: bool, above_state: &str) -> bool {
    origin_empty
        && matches!(
            above_state,
            "minecraft:netherrack" | "minecraft:basalt" | "minecraft:blackstone"
        )
}

pub fn glowstone_candidate_offset(
    x_roll_a: i32,
    x_roll_b: i32,
    y_roll: i32,
    z_roll_a: i32,
    z_roll_b: i32,
) -> BlockPos {
    BlockPos {
        x: x_roll_a.rem_euclid(8) - x_roll_b.rem_euclid(8),
        y: -y_roll.rem_euclid(12),
        z: z_roll_a.rem_euclid(8) - z_roll_b.rem_euclid(8),
    }
}

pub fn glowstone_can_grow(candidate_empty: bool, glowstone_neighbors: i32) -> bool {
    candidate_empty && glowstone_neighbors == 1
}

pub fn nether_forest_vegetation_can_start(
    below_state: &str,
    y: i32,
    min_y: i32,
    max_y: i32,
) -> bool {
    matches!(
        below_state,
        "minecraft:crimson_nylium" | "minecraft:warped_nylium"
    ) && y >= min_y + 1
        && y + 1 <= max_y
}

pub fn validate_nether_forest_vegetation_config(
    config: &NetherForestVegetationConfigModel,
) -> Result<(), &'static str> {
    if config.spread_width <= 0 || config.spread_height <= 0 {
        Err("nether forest vegetation spread values must be positive")
    } else {
        Ok(())
    }
}

pub fn nether_forest_vegetation_offset(
    spread_width: i32,
    spread_height: i32,
    x_a: i32,
    x_b: i32,
    y_a: i32,
    y_b: i32,
    z_a: i32,
    z_b: i32,
) -> BlockPos {
    BlockPos {
        x: x_a.rem_euclid(spread_width) - x_b.rem_euclid(spread_width),
        y: y_a.rem_euclid(spread_height) - y_b.rem_euclid(spread_height),
        z: z_a.rem_euclid(spread_width) - z_b.rem_euclid(spread_width),
    }
}

pub fn nether_forest_vegetation_attempts(spread_width: i32) -> i32 {
    spread_width * spread_width
}

pub fn twisting_vines_valid_ground(state: &str) -> bool {
    matches!(
        state,
        "minecraft:netherrack" | "minecraft:warped_nylium" | "minecraft:warped_wart_block"
    )
}

pub fn weeping_vines_valid_ceiling(state: &str) -> bool {
    matches!(
        state,
        "minecraft:netherrack" | "minecraft:nether_wart_block"
    )
}

pub fn vine_height(base_roll: i32, max_height: i32, double_roll: i32, single_roll: i32) -> i32 {
    let mut height = 1 + base_roll.rem_euclid(max_height.max(1));
    if double_roll.rem_euclid(6) == 0 {
        height *= 2;
    }
    if single_roll.rem_euclid(5) == 0 {
        height = 1;
    }
    height
}

pub fn vine_age(min_age: i32, max_age: i32, roll: i32) -> i32 {
    let span = (max_age - min_age + 1).max(1);
    min_age + roll.rem_euclid(span)
}

pub fn twisting_vines_column(
    origin: BlockPos,
    total_height: i32,
    empty_up: &[bool],
    blocked_above: &[bool],
    age_roll: i32,
) -> Vec<VineColumnBlock> {
    let mut blocks = Vec::new();
    for height in 1..=total_height {
        let step = (height - 1) as usize;
        if !empty_up.get(step).copied().unwrap_or(false) {
            continue;
        }
        let pos = BlockPos {
            x: origin.x,
            y: origin.y + step as i32,
            z: origin.z,
        };
        if height == total_height || blocked_above.get(step).copied().unwrap_or(false) {
            blocks.push(VineColumnBlock {
                pos,
                state: "minecraft:twisting_vines",
                kind: VineColumnBlockKind::Head,
                age: Some(vine_age(17, 25, age_roll)),
            });
            break;
        }
        blocks.push(VineColumnBlock {
            pos,
            state: "minecraft:twisting_vines_plant",
            kind: VineColumnBlockKind::Plant,
            age: None,
        });
    }
    blocks
}

pub fn weeping_vines_column(
    origin: BlockPos,
    total_height: i32,
    empty_down: &[bool],
    blocked_below: &[bool],
    age_roll: i32,
) -> Vec<VineColumnBlock> {
    let mut blocks = Vec::new();
    for height in 0..=total_height {
        let step = height as usize;
        if !empty_down.get(step).copied().unwrap_or(false) {
            continue;
        }
        let pos = BlockPos {
            x: origin.x,
            y: origin.y - height,
            z: origin.z,
        };
        if height == total_height || blocked_below.get(step).copied().unwrap_or(false) {
            blocks.push(VineColumnBlock {
                pos,
                state: "minecraft:weeping_vines",
                kind: VineColumnBlockKind::Head,
                age: Some(vine_age(17, 25, age_roll)),
            });
            break;
        }
        blocks.push(VineColumnBlock {
            pos,
            state: "minecraft:weeping_vines_plant",
            kind: VineColumnBlockKind::Plant,
            age: None,
        });
    }
    blocks
}

pub fn weeping_vines_wart_can_grow(
    candidate_empty: bool,
    wart_or_netherrack_neighbors: i32,
) -> bool {
    candidate_empty && wart_or_netherrack_neighbors == 1
}

pub fn end_platform_blocks(origin: BlockPos) -> Vec<FeaturePlacementBlock> {
    let mut blocks = Vec::new();
    for dz in -2..=2 {
        for dx in -2..=2 {
            for dy in -1..3 {
                blocks.push(FeaturePlacementBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + dy,
                        z: origin.z + dz,
                    },
                    state: if dy == -1 {
                        "minecraft:obsidian"
                    } else {
                        "minecraft:air"
                    },
                });
            }
        }
    }
    blocks
}

pub fn void_start_platform_origin(feature_origin_y: i32) -> BlockPos {
    BlockPos {
        x: 8,
        y: feature_origin_y + 3,
        z: 8,
    }
}

pub fn checkerboard_distance(xa: i32, za: i32, xb: i32, zb: i32) -> i32 {
    (xa - xb).abs().max((za - zb).abs())
}

pub fn chunk_pos_containing_block(x: i32, z: i32) -> ChunkPos {
    ChunkPos {
        x: x.div_euclid(16),
        z: z.div_euclid(16),
    }
}

pub fn void_start_platform_applies_to_chunk(chunk_pos: ChunkPos) -> bool {
    let platform_chunk = chunk_pos_containing_block(8, 8);
    checkerboard_distance(chunk_pos.x, chunk_pos.z, platform_chunk.x, platform_chunk.z) <= 1
}

pub fn void_start_platform_blocks(
    chunk_pos: ChunkPos,
    feature_origin_y: i32,
) -> Vec<FeaturePlacementBlock> {
    if !void_start_platform_applies_to_chunk(chunk_pos) {
        return Vec::new();
    }
    let origin = void_start_platform_origin(feature_origin_y);
    let mut blocks = Vec::new();
    for z in (chunk_pos.z * 16)..=(chunk_pos.z * 16 + 15) {
        for x in (chunk_pos.x * 16)..=(chunk_pos.x * 16 + 15) {
            if checkerboard_distance(origin.x, origin.z, x, z) <= 16 {
                blocks.push(FeaturePlacementBlock {
                    pos: BlockPos { x, y: origin.y, z },
                    state: if x == origin.x && z == origin.z {
                        "minecraft:cobblestone"
                    } else {
                        "minecraft:stone"
                    },
                });
            }
        }
    }
    blocks
}

pub fn end_gateway_known_exit(exit: BlockPos, exact: bool) -> EndGatewayConfigurationModel {
    EndGatewayConfigurationModel {
        exit: Some(exit),
        exact,
    }
}

pub fn end_gateway_delayed_exit_search() -> EndGatewayConfigurationModel {
    EndGatewayConfigurationModel {
        exit: None,
        exact: false,
    }
}

pub fn end_gateway_blocks(origin: BlockPos) -> Vec<FeaturePlacementBlock> {
    let mut blocks = Vec::new();
    for dy in -2i32..=2 {
        for dz in -1i32..=1 {
            for dx in -1i32..=1 {
                let same_x = dx == 0;
                let same_y = dy == 0;
                let same_z = dz == 0;
                let end = dy.abs() == 2;
                let state = if same_x && same_y && same_z {
                    "minecraft:end_gateway"
                } else if same_y {
                    "minecraft:air"
                } else if (end && same_x && same_z) || ((same_x || same_z) && !end) {
                    "minecraft:bedrock"
                } else {
                    "minecraft:air"
                };
                blocks.push(FeaturePlacementBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + dy,
                        z: origin.z + dz,
                    },
                    state,
                });
            }
        }
    }
    blocks
}

pub fn supports_chorus_plant(state: &str) -> bool {
    matches!(state, "minecraft:end_stone")
}

pub fn chorus_plant_can_start(origin_empty: bool, below_state: &str) -> bool {
    origin_empty && supports_chorus_plant(below_state)
}

pub fn chorus_all_horizontal_neighbors_empty(neighbors: [bool; 4], ignored: Option<usize>) -> bool {
    neighbors
        .into_iter()
        .enumerate()
        .all(|(index, empty)| ignored == Some(index) || empty)
}

pub fn chorus_branch_target_within_spread(
    target: BlockPos,
    start: BlockPos,
    max_horizontal_spread: i32,
) -> bool {
    (target.x - start.x).abs() < max_horizontal_spread
        && (target.z - start.z).abs() < max_horizontal_spread
}

pub fn chorus_trunk_height(depth: i32, height_roll: i32) -> i32 {
    let mut height = height_roll.rem_euclid(4) + 1;
    if depth == 0 {
        height += 1;
    }
    height
}

pub fn chorus_stem_attempts(depth: i32, stem_roll: i32) -> i32 {
    let mut stems = stem_roll.rem_euclid(4);
    if depth == 0 {
        stems += 1;
    }
    stems
}

pub fn chorus_trunk_and_terminal_flower(
    current: BlockPos,
    depth: i32,
    height_roll: i32,
    placed_stem: bool,
) -> Vec<ChorusPlantPlacementBlock> {
    let height = chorus_trunk_height(depth, height_roll);
    let mut blocks = Vec::new();
    blocks.push(ChorusPlantPlacementBlock {
        pos: current,
        kind: ChorusPlantPlacementKind::Plant,
        age: None,
    });
    for i in 0..height {
        blocks.push(ChorusPlantPlacementBlock {
            pos: BlockPos {
                x: current.x,
                y: current.y + i + 1,
                z: current.z,
            },
            kind: ChorusPlantPlacementKind::Plant,
            age: None,
        });
    }
    if !placed_stem {
        blocks.push(ChorusPlantPlacementBlock {
            pos: BlockPos {
                x: current.x,
                y: current.y + height,
                z: current.z,
            },
            kind: ChorusPlantPlacementKind::Flower,
            age: Some(5),
        });
    }
    blocks
}

pub fn end_podium_location(offset: BlockPos) -> BlockPos {
    offset
}

pub fn end_podium_inside_rim(pos: BlockPos, origin: BlockPos) -> bool {
    let dx = pos.x - origin.x;
    let dy = pos.y - origin.y;
    let dz = pos.z - origin.z;
    ((dx * dx + dy * dy + dz * dz) as f64) < 2.5_f64.powi(2)
}

pub fn end_podium_inside_body(pos: BlockPos, origin: BlockPos) -> bool {
    let dx = pos.x - origin.x;
    let dy = pos.y - origin.y;
    let dz = pos.z - origin.z;
    ((dx * dx + dy * dy + dz * dz) as f64) < 3.5_f64.powi(2)
}

pub fn end_podium_blocks(origin: BlockPos, active: bool) -> Vec<EndPodiumPlacementBlock> {
    let mut blocks = Vec::new();
    for y in (origin.y - 1)..=(origin.y + 32) {
        for z in (origin.z - 4)..=(origin.z + 4) {
            for x in (origin.x - 4)..=(origin.x + 4) {
                let pos = BlockPos { x, y, z };
                let inside_rim = end_podium_inside_rim(pos, origin);
                if !inside_rim && !end_podium_inside_body(pos, origin) {
                    continue;
                }
                let kind = if y < origin.y {
                    if inside_rim {
                        EndPodiumBlockKind::Bedrock
                    } else {
                        EndPodiumBlockKind::EndStone
                    }
                } else if y > origin.y {
                    EndPodiumBlockKind::Air
                } else if !inside_rim {
                    EndPodiumBlockKind::Bedrock
                } else if active {
                    EndPodiumBlockKind::EndPortal
                } else {
                    EndPodiumBlockKind::Air
                };
                blocks.push(EndPodiumPlacementBlock { pos, kind });
            }
        }
    }
    for y in 0..4 {
        blocks.push(EndPodiumPlacementBlock {
            pos: BlockPos {
                x: origin.x,
                y: origin.y + y,
                z: origin.z,
            },
            kind: EndPodiumBlockKind::Bedrock,
        });
    }
    let torch_y = origin.y + 2;
    for direction in [
        HorizontalDirection::North,
        HorizontalDirection::South,
        HorizontalDirection::West,
        HorizontalDirection::East,
    ] {
        let pos = offset_horizontal(
            BlockPos {
                x: origin.x,
                y: torch_y,
                z: origin.z,
            },
            direction,
            1,
        );
        blocks.push(EndPodiumPlacementBlock {
            pos,
            kind: EndPodiumBlockKind::WallTorch(direction),
        });
    }
    blocks
}

pub fn end_spike_from_size(index: i32, size: i32) -> EndSpikeModel {
    let angle = 2.0 * (-std::f64::consts::PI + (std::f64::consts::PI / 10.0) * index as f64);
    EndSpikeModel {
        center_x: (42.0 * angle.cos()).floor() as i32,
        center_z: (42.0 * angle.sin()).floor() as i32,
        radius: 2 + size / 3,
        height: 76 + size * 3,
        guarded: size == 1 || size == 2,
    }
}

pub fn end_spike_is_center_within_chunk(spike: EndSpikeModel, chunk_origin: BlockPos) -> bool {
    chunk_origin.x.div_euclid(16) == spike.center_x.div_euclid(16)
        && chunk_origin.z.div_euclid(16) == spike.center_z.div_euclid(16)
}

pub fn end_spike_top_bounding_box(
    spike: EndSpikeModel,
    min_y: i32,
    max_y: i32,
) -> (BlockPos, BlockPos) {
    (
        BlockPos {
            x: spike.center_x - spike.radius,
            y: min_y,
            z: spike.center_z - spike.radius,
        },
        BlockPos {
            x: spike.center_x + spike.radius,
            y: max_y,
            z: spike.center_z + spike.radius,
        },
    )
}

pub fn end_spike_cylinder_and_air_blocks(
    spike: EndSpikeModel,
    min_y: i32,
) -> Vec<EndSpikePlacementBlock> {
    let mut blocks = Vec::new();
    for y in min_y..=(spike.height + 10) {
        for z in (spike.center_z - spike.radius)..=(spike.center_z + spike.radius) {
            for x in (spike.center_x - spike.radius)..=(spike.center_x + spike.radius) {
                let dx = x - spike.center_x;
                let dz = z - spike.center_z;
                if dx * dx + dz * dz <= spike.radius * spike.radius + 1 && y < spike.height {
                    blocks.push(EndSpikePlacementBlock {
                        pos: BlockPos { x, y, z },
                        kind: EndSpikeBlockKind::Obsidian,
                    });
                } else if y > 65 {
                    blocks.push(EndSpikePlacementBlock {
                        pos: BlockPos { x, y, z },
                        kind: EndSpikeBlockKind::Air,
                    });
                }
            }
        }
    }
    blocks
}

pub fn end_spike_guard_cage_blocks(spike: EndSpikeModel) -> Vec<EndSpikePlacementBlock> {
    if !spike.guarded {
        return Vec::new();
    }
    let mut blocks = Vec::new();
    for dx in -2i32..=2 {
        for dz in -2i32..=2 {
            for dy in 0i32..=3 {
                let x_side = dx.abs() == 2;
                let z_side = dz.abs() == 2;
                let top = dy == 3;
                if !x_side && !z_side && !top {
                    continue;
                }
                let x_edge = dx == -2 || dx == 2 || top;
                let z_edge = dz == -2 || dz == 2 || top;
                blocks.push(EndSpikePlacementBlock {
                    pos: BlockPos {
                        x: spike.center_x + dx,
                        y: spike.height + dy,
                        z: spike.center_z + dz,
                    },
                    kind: EndSpikeBlockKind::IronBars {
                        north: x_edge && dz != -2,
                        south: x_edge && dz != 2,
                        west: z_edge && dx != -2,
                        east: z_edge && dx != 2,
                    },
                });
            }
        }
    }
    blocks
}

pub fn end_crystal_for_spike(
    spike: EndSpikeModel,
    config: &EndSpikeConfigurationModel,
    yaw_roll: f32,
) -> EndCrystalPlacement {
    EndCrystalPlacement {
        x: spike.center_x as f64 + 0.5,
        y: spike.height as f64 + 1.0,
        z: spike.center_z as f64 + 0.5,
        yaw: yaw_roll * 360.0,
        beam_target: config.crystal_beam_target,
        invulnerable: config.crystal_invulnerable,
    }
}

pub fn end_spike_crystal_support_blocks(spike: EndSpikeModel) -> Vec<EndSpikePlacementBlock> {
    let crystal_block_pos = BlockPos {
        x: spike.center_x,
        y: spike.height + 1,
        z: spike.center_z,
    };
    vec![
        EndSpikePlacementBlock {
            pos: BlockPos {
                x: crystal_block_pos.x,
                y: crystal_block_pos.y - 1,
                z: crystal_block_pos.z,
            },
            kind: EndSpikeBlockKind::Bedrock,
        },
        EndSpikePlacementBlock {
            pos: crystal_block_pos,
            kind: EndSpikeBlockKind::Fire,
        },
    ]
}

pub fn huge_fungus_can_start(config: &HugeFungusConfigurationModel, below_state: &str) -> bool {
    below_state == config.valid_base_state
}

pub fn huge_fungus_total_height(height_roll: i32, double_roll: i32) -> i32 {
    let mut total_height = 4 + height_roll.rem_euclid(10);
    if double_roll.rem_euclid(12) == 0 {
        total_height *= 2;
    }
    total_height
}

pub fn huge_fungus_fits_height(
    origin_y: i32,
    total_height: i32,
    gen_depth: i32,
    planted: bool,
) -> bool {
    planted || origin_y + total_height + 1 < gen_depth
}

pub fn huge_fungus_is_huge(planted: bool, roll: f32) -> bool {
    !planted && roll < 0.06
}

pub fn huge_fungus_stem_blocks(
    origin: BlockPos,
    total_height: i32,
    is_huge: bool,
    corner_rolls: &[f32],
) -> Vec<HugeFungusStemBlock> {
    let stem_radius: i32 = if is_huge { 1 } else { 0 };
    let mut blocks = Vec::new();
    let mut corner_index = 0usize;
    for dx in -stem_radius..=stem_radius {
        for dz in -stem_radius..=stem_radius {
            let corner = is_huge && dx.abs() == stem_radius && dz.abs() == stem_radius;
            let place_corner =
                !corner || corner_rolls.get(corner_index).copied().unwrap_or(1.0) < 0.1;
            if corner {
                corner_index += 1;
            }
            if !place_corner {
                continue;
            }
            for dy in 0..total_height {
                blocks.push(HugeFungusStemBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + dy,
                        z: origin.z + dz,
                    },
                    kind: if corner {
                        HugeFungusStemKind::CornerStem
                    } else {
                        HugeFungusStemKind::Stem
                    },
                });
            }
        }
    }
    blocks
}

pub fn huge_fungus_hat_height(total_height: i32, roll: i32) -> i32 {
    (roll.rem_euclid(1 + total_height / 3) + 5).min(total_height)
}

pub fn huge_fungus_hat_radius(
    dy: i32,
    total_height: i32,
    hat_height: i32,
    is_huge: bool,
    top_roll: i32,
) -> i32 {
    let hat_start_y = total_height - hat_height;
    let mut radius = if dy < total_height - top_roll.rem_euclid(3) {
        2
    } else {
        1
    };
    if hat_height > 8 && dy < hat_start_y + 4 {
        radius = 3;
    }
    if is_huge {
        radius += 1;
    }
    radius
}

pub fn huge_fungus_hat_cells(
    origin: BlockPos,
    total_height: i32,
    hat_height_roll: i32,
    top_rolls: &[i32],
    is_huge: bool,
) -> Vec<HugeFungusHatCell> {
    let hat_height = huge_fungus_hat_height(total_height, hat_height_roll);
    let hat_start_y = total_height - hat_height;
    let mut cells = Vec::new();
    for dy in hat_start_y..=total_height {
        let radius = huge_fungus_hat_radius(
            dy,
            total_height,
            hat_height,
            is_huge,
            top_rolls
                .get((dy - hat_start_y) as usize)
                .copied()
                .unwrap_or(0),
        );
        for dx in -radius..=radius {
            for dz in -radius..=radius {
                let edge_x = dx == -radius || dx == radius;
                let edge_z = dz == -radius || dz == radius;
                let inside = !edge_x && !edge_z && dy != total_height;
                let corner = edge_x && edge_z;
                let bottom = dy < hat_start_y + 3;
                let role = if bottom {
                    HugeFungusHatRole::Bottom
                } else if inside {
                    HugeFungusHatRole::Inside
                } else if corner {
                    HugeFungusHatRole::Corner
                } else {
                    HugeFungusHatRole::Edge
                };
                cells.push(HugeFungusHatCell {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + dy,
                        z: origin.z + dz,
                    },
                    role,
                    radius,
                });
            }
        }
    }
    cells
}

pub fn huge_fungus_hat_drop_outcome(
    below_same_hat: bool,
    hat_roll: f32,
    vine_roll: i32,
    place_vines: bool,
) -> HugeFungusHatPlacement {
    if below_same_hat {
        HugeFungusHatPlacement::Hat
    } else if hat_roll < 0.15 {
        if place_vines && vine_roll.rem_euclid(11) == 0 {
            HugeFungusHatPlacement::HatWithWeepingVines
        } else {
            HugeFungusHatPlacement::Hat
        }
    } else {
        HugeFungusHatPlacement::None
    }
}

pub fn huge_fungus_hat_block_outcome(
    decor_roll: f32,
    hat_roll: f32,
    vine_roll: f32,
    decor_probability: f32,
    hat_probability: f32,
    vines_probability: f32,
) -> HugeFungusHatPlacement {
    if decor_roll < decor_probability {
        HugeFungusHatPlacement::Decor
    } else if hat_roll < hat_probability {
        if vine_roll < vines_probability {
            HugeFungusHatPlacement::HatWithWeepingVines
        } else {
            HugeFungusHatPlacement::Hat
        }
    } else {
        HugeFungusHatPlacement::None
    }
}

pub fn huge_fungus_hat_probabilities(
    role: HugeFungusHatRole,
    place_vines: bool,
) -> Option<(f32, f32, f32)> {
    match role {
        HugeFungusHatRole::Bottom => None,
        HugeFungusHatRole::Inside => Some((0.1, 0.2, if place_vines { 0.1 } else { 0.0 })),
        HugeFungusHatRole::Corner => Some((0.01, 0.7, if place_vines { 0.083 } else { 0.0 })),
        HugeFungusHatRole::Edge => Some((0.0005, 0.98, if place_vines { 0.07 } else { 0.0 })),
    }
}

pub fn huge_fungus_weeping_vine_height(base_roll: i32, double_roll: i32) -> i32 {
    let mut height = 1 + base_roll.rem_euclid(5);
    if double_roll.rem_euclid(7) == 0 {
        height *= 2;
    }
    height
}

fn block_is_coral(block: &str) -> bool {
    block.contains("_coral")
}

fn offset_horizontal(pos: BlockPos, direction: HorizontalDirection, distance: i32) -> BlockPos {
    match direction {
        HorizontalDirection::North => BlockPos {
            x: pos.x,
            y: pos.y,
            z: pos.z - distance,
        },
        HorizontalDirection::South => BlockPos {
            x: pos.x,
            y: pos.y,
            z: pos.z + distance,
        },
        HorizontalDirection::West => BlockPos {
            x: pos.x - distance,
            y: pos.y,
            z: pos.z,
        },
        HorizontalDirection::East => BlockPos {
            x: pos.x + distance,
            y: pos.y,
            z: pos.z,
        },
    }
}

impl HorizontalDirection {
    const fn opposite(self) -> Self {
        match self {
            Self::North => Self::South,
            Self::South => Self::North,
            Self::West => Self::East,
            Self::East => Self::West,
        }
    }

    const fn clockwise(self) -> Self {
        match self {
            Self::North => Self::East,
            Self::East => Self::South,
            Self::South => Self::West,
            Self::West => Self::North,
        }
    }
}

impl CaveSurface {
    const fn y_step(self) -> i32 {
        match self {
            Self::Floor => -1,
            Self::Ceiling => 1,
        }
    }

    const fn opposite(self) -> Self {
        match self {
            Self::Floor => Self::Ceiling,
            Self::Ceiling => Self::Floor,
        }
    }
}

fn offset_vertical(pos: BlockPos, surface: CaveSurface, distance: i32) -> BlockPos {
    BlockPos {
        x: pos.x,
        y: pos.y + surface.y_step() * distance,
        z: pos.z,
    }
}

const fn coral_wall_fan_state(direction: HorizontalDirection) -> &'static str {
    match direction {
        HorizontalDirection::North => "minecraft:tube_coral_wall_fan[facing=north]",
        HorizontalDirection::South => "minecraft:tube_coral_wall_fan[facing=south]",
        HorizontalDirection::West => "minecraft:tube_coral_wall_fan[facing=west]",
        HorizontalDirection::East => "minecraft:tube_coral_wall_fan[facing=east]",
    }
}

pub fn block_pile_placement_candidates(
    origin: BlockPos,
    min_y: i32,
    x_radius_roll: i32,
    z_radius_roll: i32,
    shape_rolls: &[(f32, f32, f32)],
) -> Vec<BlockPos> {
    if origin.y < min_y + 5 {
        return Vec::new();
    }
    let x_radius = 2 + x_radius_roll.rem_euclid(2);
    let z_radius = 2 + z_radius_roll.rem_euclid(2);
    let mut positions = Vec::new();
    let mut roll_index = 0;
    for y_offset in 0..=1 {
        for z in origin.z - z_radius..=origin.z + z_radius {
            for x in origin.x - x_radius..=origin.x + x_radius {
                let (first, second, sparse) = shape_rolls
                    .get(roll_index)
                    .copied()
                    .unwrap_or((0.0, 0.0, 1.0));
                roll_index += 1;
                let dx = origin.x - x;
                let dz = origin.z - z;
                let in_blob = (dx * dx + dz * dz) as f32 <= first * 10.0 - second * 6.0;
                if in_blob || sparse < 0.031 {
                    positions.push(BlockPos {
                        x,
                        y: origin.y + y_offset,
                        z,
                    });
                }
            }
        }
    }
    positions
}

pub fn block_pile_try_place(
    config: &BlockPileConfigurationModel,
    candidate_empty: bool,
    below_block: &'static str,
    below_sturdy: bool,
    dirt_path_random: bool,
    provider_roll: i32,
) -> Option<&'static str> {
    if !candidate_empty {
        return None;
    }
    let may_place = if below_block == "minecraft:dirt_path" {
        dirt_path_random
    } else {
        below_sturdy
    };
    if may_place {
        block_state_provider_sample(&config.state_provider, provider_roll)
    } else {
        None
    }
}

pub fn disk_placement_plan(
    origin: BlockPos,
    config: &DiskConfigurationModel,
    column_contexts: &[(BlockPos, BlockPredicateContext)],
    provider_rolls: &[i32],
) -> Vec<DiskPlacementBlock> {
    let radius = sample_int_provider_from_roll(config.radius, 0).clamp(0, 8);
    let half_height = config.half_height.clamp(0, 4);
    let top = origin.y + half_height;
    let bottom_exclusive = origin.y - half_height - 1;
    let mut placed = Vec::new();
    let mut provider_index = 0;
    for z in origin.z - radius..=origin.z + radius {
        for x in origin.x - radius..=origin.x + radius {
            let dx = x - origin.x;
            let dz = z - origin.z;
            if dx * dx + dz * dz > radius * radius {
                continue;
            }
            let mut placed_above = false;
            for y in (bottom_exclusive + 1..=top).rev() {
                let pos = BlockPos { x, y, z };
                let Some((_, context)) = column_contexts
                    .iter()
                    .find(|(context_pos, _)| *context_pos == pos)
                else {
                    placed_above = false;
                    continue;
                };
                if block_predicate_test(config.target, *context, y) {
                    let provider_roll = provider_rolls.get(provider_index).copied().unwrap_or(0);
                    provider_index += 1;
                    if let Some(state) =
                        block_state_provider_sample(&config.state_provider, provider_roll)
                    {
                        placed.push(DiskPlacementBlock {
                            pos,
                            state,
                            mark_above_for_post_processing: !placed_above,
                        });
                        placed_above = true;
                    }
                } else {
                    placed_above = false;
                }
            }
        }
    }
    placed
}

pub fn snow_and_freeze_placement_plan(
    origin: BlockPos,
    columns: &[SnowAndFreezeColumn],
) -> Vec<SnowAndFreezePlacement> {
    let mut placements = Vec::new();
    for dx in 0..16 {
        for dz in 0..16 {
            let x = origin.x + dx;
            let z = origin.z + dz;
            let Some(column) = columns.iter().find(|column| column.x == x && column.z == z) else {
                continue;
            };
            let top = BlockPos {
                x,
                y: column.motion_blocking_height,
                z,
            };
            let below = BlockPos {
                x,
                y: column.motion_blocking_height - 1,
                z,
            };
            if column.should_freeze {
                placements.push(SnowAndFreezePlacement {
                    pos: below,
                    state: "minecraft:ice",
                });
            }
            if column.should_snow {
                placements.push(SnowAndFreezePlacement {
                    pos: top,
                    state: "minecraft:snow",
                });
                if column.below_has_snowy_property {
                    placements.push(SnowAndFreezePlacement {
                        pos: below,
                        state: "minecraft:snowy=true",
                    });
                }
            }
        }
    }
    placements
}

pub fn underwater_magma_placement_plan(
    origin: BlockPos,
    floor_y: Option<i32>,
    config: UnderwaterMagmaConfigurationModel,
    candidates: &[UnderwaterMagmaCandidate],
    probability_rolls: &[f32],
) -> Vec<BlockPos> {
    let Some(floor_y) = floor_y else {
        return Vec::new();
    };
    let radius = config.placement_radius_around_floor.clamp(0, 64);
    let probability = config
        .placement_probability_per_valid_position
        .clamp(0.0, 1.0);
    let floor_pos = BlockPos {
        x: origin.x,
        y: floor_y,
        z: origin.z,
    };
    let mut placements = Vec::new();
    let mut roll_index = 0;
    for y in floor_pos.y - radius..=floor_pos.y + radius {
        for z in floor_pos.z - radius..=floor_pos.z + radius {
            for x in floor_pos.x - radius..=floor_pos.x + radius {
                let roll = probability_rolls.get(roll_index).copied().unwrap_or(0.0);
                roll_index += 1;
                if roll >= probability {
                    continue;
                }
                let pos = BlockPos { x, y, z };
                if candidates
                    .iter()
                    .find(|candidate| candidate.pos == pos)
                    .is_some_and(underwater_magma_is_valid_placement)
                {
                    placements.push(pos);
                }
            }
        }
    }
    placements
}

pub fn underwater_magma_is_valid_placement(candidate: &UnderwaterMagmaCandidate) -> bool {
    !matches!(candidate.block, "minecraft:water" | "minecraft:air")
        && !candidate.below_visible_from_above
        && !candidate.horizontal_visible_from_outside
}

pub fn validate_dripstone_cluster_sampled_config(
    config: DripstoneClusterSampledConfig,
) -> Result<DripstoneClusterSampledConfig, String> {
    if !(1..=512).contains(&config.floor_to_ceiling_search_range)
        || !(1..=128).contains(&config.height)
        || !(1..=128).contains(&config.x_radius)
        || !(1..=128).contains(&config.z_radius)
        || !(0..=64).contains(&config.max_stalagmite_stalactite_height_diff)
        || !(1..=64).contains(&config.height_deviation)
        || !(0..=128).contains(&config.dripstone_block_layer_thickness)
        || !(0.0..=2.0).contains(&config.density)
        || !(0.0..=2.0).contains(&config.wetness)
        || !(0.0..=1.0).contains(&config.chance_of_dripstone_column_at_max_distance_from_center)
        || !(1..=64).contains(&config.max_distance_from_edge_affecting_chance_of_dripstone_column)
        || !(1..=64).contains(&config.max_distance_from_center_affecting_height_bias)
    {
        Err("dripstone cluster sampled fields are outside vanilla codec ranges".to_string())
    } else {
        Ok(config)
    }
}

pub fn dripstone_cluster_chance_of_column(
    x_radius: i32,
    z_radius: i32,
    dx: i32,
    dz: i32,
    config: DripstoneClusterSampledConfig,
) -> f64 {
    let x_distance_from_edge = x_radius - dx.abs();
    let z_distance_from_edge = z_radius - dz.abs();
    let distance_from_edge = x_distance_from_edge.min(z_distance_from_edge);
    clamped_map_f64(
        distance_from_edge as f64,
        0.0,
        config.max_distance_from_edge_affecting_chance_of_dripstone_column as f64,
        config.chance_of_dripstone_column_at_max_distance_from_center as f64,
        1.0,
    )
}

pub fn dripstone_cluster_height_for_column(
    dx: i32,
    dz: i32,
    density: f32,
    max_height: i32,
    config: DripstoneClusterSampledConfig,
    density_roll: f32,
    biased_height_sample: f32,
) -> i32 {
    if density_roll > density {
        return 0;
    }
    let distance_from_center = dx.abs() + dz.abs();
    let _height_mean = clamped_map_f64(
        distance_from_center as f64,
        0.0,
        config.max_distance_from_center_affecting_height_bias as f64,
        max_height as f64 / 2.0,
        0.0,
    );
    biased_height_sample.clamp(0.0, max_height as f32) as i32
}

pub fn dripstone_cluster_column_plan(
    origin: BlockPos,
    config: DripstoneClusterSampledConfig,
    input: DripstoneClusterColumnInput,
    rolls: DripstoneClusterColumnRolls,
) -> DripstoneClusterColumnPlan {
    let chance = dripstone_cluster_chance_of_column(
        config.x_radius,
        config.z_radius,
        input.dx,
        input.dz,
        config,
    );
    let mut floor_y = input.floor_y;
    let water_pos = if rolls.water_roll < config.wetness
        && input.floor_y.is_some()
        && input.floor_pool_supported
    {
        let base_floor_y = input.floor_y.unwrap();
        floor_y = Some(base_floor_y - 1);
        Some(BlockPos {
            x: origin.x + input.dx,
            y: base_floor_y,
            z: origin.z + input.dz,
        })
    } else {
        None
    };

    let want_stalactite = rolls.stalactite_roll < chance;
    let mut stalactite_height = if let Some(ceiling_y) = input.ceiling_y {
        if want_stalactite && !input.ceiling_is_lava {
            let max_height = floor_y
                .map(|floor| config.height.min(ceiling_y - floor))
                .unwrap_or(config.height);
            dripstone_cluster_height_for_column(
                input.dx,
                input.dz,
                config.density,
                max_height,
                config,
                rolls.stalactite_density_roll,
                rolls.stalactite_biased_height,
            )
        } else {
            0
        }
    } else {
        0
    };

    let want_stalagmite = rolls.stalagmite_roll < chance;
    let mut stalagmite_height = if floor_y.is_some() && want_stalagmite && !input.floor_is_lava {
        if input.ceiling_y.is_some() {
            (stalactite_height
                + inclusive_roll(
                    rolls.stalagmite_height_diff_roll,
                    -config.max_stalagmite_stalactite_height_diff,
                    config.max_stalagmite_stalactite_height_diff,
                ))
            .max(0)
        } else {
            dripstone_cluster_height_for_column(
                input.dx,
                input.dz,
                config.density,
                config.height,
                config,
                rolls.stalagmite_density_roll,
                rolls.stalagmite_biased_height,
            )
        }
    } else {
        0
    };

    if let (Some(ceiling_y), Some(floor_y_value)) = (input.ceiling_y, floor_y) {
        if ceiling_y - stalactite_height <= floor_y_value + stalagmite_height {
            let lowest_stalactite_bottom = (ceiling_y - stalactite_height).max(floor_y_value + 1);
            let highest_stalagmite_top = (floor_y_value + stalagmite_height).min(ceiling_y - 1);
            let actual_stalactite_bottom = inclusive_roll(
                rolls.overlap_split_roll,
                lowest_stalactite_bottom,
                highest_stalagmite_top + 1,
            );
            let actual_stalagmite_top = actual_stalactite_bottom - 1;
            stalactite_height = ceiling_y - actual_stalactite_bottom;
            stalagmite_height = actual_stalagmite_top - floor_y_value;
        }
    }

    let column_height = input
        .ceiling_y
        .zip(floor_y)
        .map(|(ceiling, floor)| ceiling - floor);
    let merge_tips = rolls.merge_tips_roll
        && stalactite_height > 0
        && stalagmite_height > 0
        && column_height.is_some_and(|height| stalactite_height + stalagmite_height == height);
    let column_xz = BlockPos {
        x: origin.x + input.dx,
        y: origin.y,
        z: origin.z + input.dz,
    };

    DripstoneClusterColumnPlan {
        water_pos,
        ceiling_dripstone_blocks: input
            .ceiling_y
            .filter(|_| want_stalactite && !input.ceiling_is_lava)
            .map(|ceiling_y| {
                dripstone_block_layer_positions(
                    column_xz,
                    ceiling_y,
                    config.dripstone_block_layer_thickness,
                    1,
                )
            })
            .unwrap_or_default(),
        floor_dripstone_blocks: floor_y
            .filter(|_| want_stalagmite && !input.floor_is_lava)
            .map(|floor_y| {
                dripstone_block_layer_positions(
                    column_xz,
                    floor_y,
                    config.dripstone_block_layer_thickness,
                    -1,
                )
            })
            .unwrap_or_default(),
        stalactite: input
            .ceiling_y
            .map(|ceiling_y| {
                pointed_dripstone_column(
                    BlockPos {
                        x: column_xz.x,
                        y: ceiling_y - 1,
                        z: column_xz.z,
                    },
                    PointedDripstoneDirection::Down,
                    stalactite_height,
                    merge_tips,
                )
            })
            .unwrap_or_default(),
        stalagmite: floor_y
            .map(|floor_y| {
                pointed_dripstone_column(
                    BlockPos {
                        x: column_xz.x,
                        y: floor_y + 1,
                        z: column_xz.z,
                    },
                    PointedDripstoneDirection::Up,
                    stalagmite_height,
                    merge_tips,
                )
            })
            .unwrap_or_default(),
        merge_tips,
    }
}

pub fn pointed_dripstone_column(
    start_pos: BlockPos,
    direction: PointedDripstoneDirection,
    total_length: i32,
    merged_tip: bool,
) -> Vec<PointedDripstoneBlockModel> {
    let mut thicknesses = Vec::new();
    if total_length >= 3 {
        thicknesses.push(PointedDripstoneThickness::Base);
        for _ in 0..total_length - 3 {
            thicknesses.push(PointedDripstoneThickness::Middle);
        }
    }
    if total_length >= 2 {
        thicknesses.push(PointedDripstoneThickness::Frustum);
    }
    if total_length >= 1 {
        thicknesses.push(if merged_tip {
            PointedDripstoneThickness::TipMerge
        } else {
            PointedDripstoneThickness::Tip
        });
    }

    thicknesses
        .into_iter()
        .enumerate()
        .map(|(index, thickness)| PointedDripstoneBlockModel {
            pos: BlockPos {
                x: start_pos.x,
                y: match direction {
                    PointedDripstoneDirection::Up => start_pos.y + index as i32,
                    PointedDripstoneDirection::Down => start_pos.y - index as i32,
                },
                z: start_pos.z,
            },
            direction,
            thickness,
        })
        .collect()
}

pub fn validate_pointed_dripstone_configuration(
    config: PointedDripstoneConfigurationModel,
) -> Result<PointedDripstoneConfigurationModel, String> {
    if [
        config.chance_of_taller_dripstone,
        config.chance_of_directional_spread,
        config.chance_of_spread_radius2,
        config.chance_of_spread_radius3,
    ]
    .into_iter()
    .all(|chance| (0.0..=1.0).contains(&chance))
    {
        Ok(config)
    } else {
        Err("pointed dripstone chances must be in 0.0..=1.0".to_string())
    }
}

pub fn pointed_dripstone_tip_direction(
    can_place_above: bool,
    can_place_below: bool,
    choose_down_when_both: bool,
) -> Option<PointedDripstoneDirection> {
    match (can_place_above, can_place_below) {
        (true, true) => Some(if choose_down_when_both {
            PointedDripstoneDirection::Down
        } else {
            PointedDripstoneDirection::Up
        }),
        (true, false) => Some(PointedDripstoneDirection::Down),
        (false, true) => Some(PointedDripstoneDirection::Up),
        (false, false) => None,
    }
}

pub fn pointed_dripstone_feature_plan(
    origin: BlockPos,
    config: PointedDripstoneConfigurationModel,
    can_place_above: bool,
    can_place_below: bool,
    choose_down_when_both: bool,
    taller_roll: f32,
    next_position_empty_or_water: bool,
    spread_rolls: &[PointedDripstoneSpreadRoll],
) -> Result<PointedDripstoneFeaturePlan, String> {
    validate_pointed_dripstone_configuration(config)?;
    let Some(tip_direction) =
        pointed_dripstone_tip_direction(can_place_above, can_place_below, choose_down_when_both)
    else {
        return Ok(PointedDripstoneFeaturePlan {
            tip_direction: None,
            dripstone_blocks: Vec::new(),
            pointed_blocks: Vec::new(),
        });
    };
    let root_pos = match tip_direction {
        PointedDripstoneDirection::Down => BlockPos {
            x: origin.x,
            y: origin.y + 1,
            z: origin.z,
        },
        PointedDripstoneDirection::Up => BlockPos {
            x: origin.x,
            y: origin.y - 1,
            z: origin.z,
        },
    };
    let height = if taller_roll < config.chance_of_taller_dripstone && next_position_empty_or_water
    {
        2
    } else {
        1
    };

    Ok(PointedDripstoneFeaturePlan {
        tip_direction: Some(tip_direction),
        dripstone_blocks: pointed_dripstone_patch_positions(root_pos, config, spread_rolls),
        pointed_blocks: pointed_dripstone_column(origin, tip_direction, height, false),
    })
}

pub fn pointed_dripstone_patch_positions(
    root_pos: BlockPos,
    config: PointedDripstoneConfigurationModel,
    rolls: &[PointedDripstoneSpreadRoll],
) -> Vec<BlockPos> {
    let mut positions = vec![root_pos];
    for roll in rolls {
        if roll.direction_roll > config.chance_of_directional_spread {
            continue;
        }
        let pos1 = offset_horizontal(root_pos, roll.direction, 1);
        positions.push(pos1);
        if roll.radius2_roll > config.chance_of_spread_radius2 {
            continue;
        }
        let pos2 = offset_horizontal(pos1, roll.radius2_direction, 1);
        positions.push(pos2);
        if roll.radius3_roll > config.chance_of_spread_radius3 {
            continue;
        }
        positions.push(offset_horizontal(pos2, roll.radius3_direction, 1));
    }
    positions
}

pub fn validate_large_dripstone_sampled_config(
    config: LargeDripstoneSampledConfig,
) -> Result<LargeDripstoneSampledConfig, String> {
    if !(1..=512).contains(&config.floor_to_ceiling_search_range)
        || !(1..=60).contains(&config.column_radius_min)
        || !(1..=60).contains(&config.column_radius_max)
        || config.column_radius_min > config.column_radius_max
        || !(0.0..=20.0).contains(&config.height_scale)
        || !(0.1..=1.0).contains(&config.max_column_radius_to_cave_height_ratio)
        || !(0.1..=10.0).contains(&config.stalactite_bluntness)
        || !(0.1..=10.0).contains(&config.stalagmite_bluntness)
        || !(0.0..=2.0).contains(&config.wind_speed)
        || !(0.0..=std::f64::consts::PI).contains(&config.wind_direction_radians)
        || !(0..=100).contains(&config.min_radius_for_wind)
        || !(0.0..=5.0).contains(&config.min_bluntness_for_wind)
    {
        Err("large dripstone sampled fields are outside vanilla codec ranges".to_string())
    } else {
        Ok(config)
    }
}

pub fn large_dripstone_selected_radius(
    cave_height: i32,
    config: LargeDripstoneSampledConfig,
    radius_roll: i32,
) -> Option<i32> {
    if cave_height < 4 {
        return None;
    }
    let max_based_on_height =
        (cave_height as f32 * config.max_column_radius_to_cave_height_ratio) as i32;
    let max_radius = max_based_on_height.clamp(config.column_radius_min, config.column_radius_max);
    Some(inclusive_roll(
        radius_roll,
        config.column_radius_min,
        max_radius,
    ))
}

pub fn large_dripstone_height_at_radius(
    xz_distance_from_center: f64,
    dripstone_radius: i32,
    scale: f64,
    bluntness: f64,
) -> i32 {
    let xz_distance = xz_distance_from_center.max(bluntness);
    let cutoff = 0.384;
    let r = xz_distance / dripstone_radius as f64 * cutoff;
    let part1 = 0.75 * r.powf(4.0 / 3.0);
    let part2 = r.powf(2.0 / 3.0);
    let part3 = (1.0 / 3.0) * r.ln();
    let height_relative = (scale * (part1 - part2 - part3)).max(0.0);
    (height_relative / cutoff * dripstone_radius as f64) as i32
}

pub fn large_dripstone_wind_enabled(
    radius: i32,
    bluntness: f64,
    config: LargeDripstoneSampledConfig,
) -> bool {
    radius >= config.min_radius_for_wind && bluntness >= config.min_bluntness_for_wind
}

pub fn large_dripstone_wind_offset(
    pos: BlockPos,
    origin_y: i32,
    config: LargeDripstoneSampledConfig,
) -> BlockPos {
    let dy = origin_y - pos.y;
    BlockPos {
        x: pos.x
            + (config.wind_direction_radians.cos() * config.wind_speed * dy as f64).floor() as i32,
        y: pos.y,
        z: pos.z
            + (config.wind_direction_radians.sin() * config.wind_speed * dy as f64).floor() as i32,
    }
}

pub fn large_dripstone_placement_plan(
    origin: BlockPos,
    floor_y: i32,
    ceiling_y: i32,
    config: LargeDripstoneSampledConfig,
    radius_roll: i32,
    shrink_rolls: &[f32],
    shrink_factor_rolls: &[f32],
) -> Option<LargeDripstonePlacementPlan> {
    validate_large_dripstone_sampled_config(config).ok()?;
    let cave_height = ceiling_y - floor_y - 1;
    let radius = large_dripstone_selected_radius(cave_height, config, radius_roll)?;
    let stalactite = LargeDripstoneModel {
        root: BlockPos {
            x: origin.x,
            y: ceiling_y - 1,
            z: origin.z,
        },
        pointing_up: false,
        radius,
    };
    let stalagmite = LargeDripstoneModel {
        root: BlockPos {
            x: origin.x,
            y: floor_y + 1,
            z: origin.z,
        },
        pointing_up: true,
        radius,
    };
    let wind_enabled = large_dripstone_wind_enabled(radius, config.stalactite_bluntness, config)
        && large_dripstone_wind_enabled(radius, config.stalagmite_bluntness, config);

    Some(LargeDripstonePlacementPlan {
        stalactite,
        stalagmite,
        wind_enabled,
        stalactite_blocks: large_dripstone_blocks(
            stalactite,
            config.height_scale,
            config.stalactite_bluntness,
            origin.y,
            if wind_enabled { Some(config) } else { None },
            shrink_rolls,
            shrink_factor_rolls,
        ),
        stalagmite_blocks: large_dripstone_blocks(
            stalagmite,
            config.height_scale,
            config.stalagmite_bluntness,
            origin.y,
            if wind_enabled { Some(config) } else { None },
            shrink_rolls,
            shrink_factor_rolls,
        ),
    })
}

pub fn large_dripstone_blocks(
    dripstone: LargeDripstoneModel,
    scale: f64,
    bluntness: f64,
    origin_y: i32,
    wind: Option<LargeDripstoneSampledConfig>,
    shrink_rolls: &[f32],
    shrink_factor_rolls: &[f32],
) -> Vec<LargeDripstoneBlockModel> {
    let mut blocks = Vec::new();
    let mut roll_index = 0;
    let mut factor_roll_index = 0;
    for dx in -dripstone.radius..=dripstone.radius {
        for dz in -dripstone.radius..=dripstone.radius {
            let current_radius = ((dx * dx + dz * dz) as f64).sqrt();
            if current_radius > dripstone.radius as f64 {
                continue;
            }
            let mut height = large_dripstone_height_at_radius(
                current_radius,
                dripstone.radius,
                scale,
                bluntness,
            );
            if height <= 0 {
                continue;
            }
            let shrink_roll = shrink_rolls.get(roll_index).copied().unwrap_or(1.0);
            roll_index += 1;
            if shrink_roll < 0.2 {
                let factor_roll = shrink_factor_rolls
                    .get(factor_roll_index)
                    .copied()
                    .unwrap_or(1.0)
                    .clamp(0.0, 1.0);
                factor_roll_index += 1;
                height = (height as f32 * (0.8 + 0.2 * factor_roll)) as i32;
            }
            for i in 0..height {
                let raw = BlockPos {
                    x: dripstone.root.x + dx,
                    y: if dripstone.pointing_up {
                        dripstone.root.y + i
                    } else {
                        dripstone.root.y - i
                    },
                    z: dripstone.root.z + dz,
                };
                blocks.push(LargeDripstoneBlockModel {
                    pos: wind
                        .map(|config| large_dripstone_wind_offset(raw, origin_y, config))
                        .unwrap_or(raw),
                    pointing_up: dripstone.pointing_up,
                });
            }
        }
    }
    blocks
}

fn dripstone_block_layer_positions(
    column_xz: BlockPos,
    start_y: i32,
    max_count: i32,
    y_step: i32,
) -> Vec<BlockPos> {
    (0..max_count)
        .map(|i| BlockPos {
            x: column_xz.x,
            y: start_y + i * y_step,
            z: column_xz.z,
        })
        .collect()
}

fn clamped_map_f64(value: f64, from_min: f64, from_max: f64, to_min: f64, to_max: f64) -> f64 {
    if value <= from_min {
        to_min
    } else if value >= from_max {
        to_max
    } else {
        let progress = (value - from_min) / (from_max - from_min);
        to_min + progress * (to_max - to_min)
    }
}

fn inclusive_roll(roll: i32, min: i32, max: i32) -> i32 {
    min + roll.rem_euclid(max - min + 1)
}

pub fn feature_size_type(id: &str) -> Option<&'static str> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    WORLDGEN_TYPE_REGISTRIES
        .iter()
        .find(|registry| registry.id == "minecraft:feature_size_type")?
        .entries
        .iter()
        .copied()
        .find(|entry| entry.strip_prefix("minecraft:") == Some(name))
}

pub fn trunk_placer_type(id: &str) -> Option<&'static str> {
    worldgen_type_registry_entry("minecraft:trunk_placer_type", id)
}

pub fn foliage_placer_type(id: &str) -> Option<&'static str> {
    worldgen_type_registry_entry("minecraft:foliage_placer_type", id)
}

pub fn root_placer_type(id: &str) -> Option<&'static str> {
    worldgen_type_registry_entry("minecraft:root_placer_type", id)
}

fn worldgen_type_registry_entry(registry_id: &str, id: &str) -> Option<&'static str> {
    let name = id.strip_prefix("minecraft:").unwrap_or(id);
    WORLDGEN_TYPE_REGISTRIES
        .iter()
        .find(|registry| registry.id == registry_id)?
        .entries
        .iter()
        .copied()
        .find(|entry| entry.strip_prefix("minecraft:") == Some(name))
}

pub fn validate_trunk_placer(placer: TrunkPlacerModel) -> Result<TrunkPlacerModel, String> {
    if !(0..=32).contains(&placer.base_height)
        || !(0..=24).contains(&placer.height_rand_a)
        || !(0..=24).contains(&placer.height_rand_b)
    {
        return Err("trunk placer base fields are outside vanilla codec ranges".to_string());
    }

    let valid = match placer.kind {
        TrunkPlacerKind::Straight
        | TrunkPlacerKind::Forking
        | TrunkPlacerKind::Giant
        | TrunkPlacerKind::MegaJungle
        | TrunkPlacerKind::DarkOak
        | TrunkPlacerKind::Fancy => true,
        TrunkPlacerKind::Bending {
            min_height_for_leaves,
            bend_length_min,
            bend_length_max,
        } => {
            min_height_for_leaves > 0
                && (1..=64).contains(&bend_length_min)
                && (1..=64).contains(&bend_length_max)
                && bend_length_min <= bend_length_max
        }
        TrunkPlacerKind::UpwardsBranching {
            place_branch_per_log_probability,
            extra_branch_steps_min,
            extra_branch_length_min,
        } => {
            (0.0..=1.0).contains(&place_branch_per_log_probability)
                && extra_branch_steps_min > 0
                && extra_branch_length_min >= 0
        }
        TrunkPlacerKind::Cherry {
            branch_count_min,
            branch_count_max,
            branch_horizontal_length_min,
            branch_horizontal_length_max,
            branch_start_offset_from_top_min,
            branch_start_offset_from_top_max,
            branch_end_offset_from_top_min,
            branch_end_offset_from_top_max,
        } => {
            (1..=3).contains(&branch_count_min)
                && (1..=3).contains(&branch_count_max)
                && branch_count_min <= branch_count_max
                && (2..=16).contains(&branch_horizontal_length_min)
                && (2..=16).contains(&branch_horizontal_length_max)
                && branch_horizontal_length_min <= branch_horizontal_length_max
                && (-16..=0).contains(&branch_start_offset_from_top_min)
                && (-16..=0).contains(&branch_start_offset_from_top_max)
                && branch_start_offset_from_top_min <= branch_start_offset_from_top_max
                && branch_start_offset_from_top_max - branch_start_offset_from_top_min >= 1
                && (-16..=16).contains(&branch_end_offset_from_top_min)
                && (-16..=16).contains(&branch_end_offset_from_top_max)
                && branch_end_offset_from_top_min <= branch_end_offset_from_top_max
        }
    };
    if valid {
        Ok(placer)
    } else {
        Err("trunk placer variant fields are outside vanilla codec ranges".to_string())
    }
}

pub fn trunk_placer_height(placer: TrunkPlacerModel, rand_a: i32, rand_b: i32) -> i32 {
    placer.base_height
        + rand_a.rem_euclid(placer.height_rand_a + 1)
        + rand_b.rem_euclid(placer.height_rand_b + 1)
}

pub fn tree_valid_pos(state: &str) -> bool {
    let state = block_state_id(state);
    block_matches_tag(state, "minecraft:air")
        || block_matches_tag(state, "minecraft:replaceable_by_trees")
}

pub fn tree_trunk_free_pos(state: &str) -> bool {
    let state = block_state_id(state);
    tree_valid_pos(state) || block_matches_tag(state, "minecraft:logs")
}

pub fn tree_max_free_height(
    tree_height: i32,
    min_size: FeatureSizeModel,
    rows: &[&[&str]],
    ignore_vines: bool,
) -> i32 {
    for y in 0..=tree_height + 1 {
        let radius = feature_size_at_height(min_size, tree_height, y);
        let radius_width = radius * 2 + 1;
        let expected_width = (radius_width * radius_width).max(0) as usize;
        let row = rows.get(y as usize).copied().unwrap_or(&[]);
        if row.len() < expected_width
            || row.iter().take(expected_width).any(|state| {
                !tree_trunk_free_pos(state) || (!ignore_vines && *state == "minecraft:vine")
            })
        {
            return y - 2;
        }
    }
    tree_height
}

pub fn tree_can_place(
    origin: BlockPos,
    trunk_origin: BlockPos,
    tree_height: i32,
    min_size: FeatureSizeModel,
    min_clipped_height: Option<i32>,
    build_min_y: i32,
    build_max_y: i32,
    rows: &[&[&str]],
    ignore_vines: bool,
) -> bool {
    let min_y = origin.y.min(trunk_origin.y);
    let max_y = origin.y.max(trunk_origin.y) + tree_height + 1;
    if min_y < build_min_y + 1 || max_y > build_max_y + 1 {
        return false;
    }
    let clipped_tree_height = tree_max_free_height(tree_height, min_size, rows, ignore_vines);
    clipped_tree_height >= tree_height
        || min_clipped_height.is_some_and(|min| clipped_tree_height >= min)
}

fn feature_size_min_clipped_height(size: FeatureSizeModel) -> Option<i32> {
    match size {
        FeatureSizeModel::TwoLayers {
            min_clipped_height, ..
        }
        | FeatureSizeModel::ThreeLayers {
            min_clipped_height, ..
        } => min_clipped_height,
    }
}

pub fn validate_tree_configuration(config: &TreeConfigurationModel) -> Result<(), String> {
    validate_trunk_placer(config.trunk_placer)?;
    validate_foliage_placer(config.foliage_placer)?;
    validate_feature_size(config.minimum_size)?;
    if let Some(root_placer) = config.root_placer {
        validate_root_placer(root_placer)?;
    }
    for decorator in config.decorators.iter().copied() {
        validate_tree_decorator(decorator)?;
    }
    if block_state_provider_sample(&config.trunk_provider, 0).is_none()
        || block_state_provider_sample(&config.foliage_provider, 0).is_none()
        || block_state_provider_sample(&config.dirt_provider, 0).is_none()
    {
        return Err("tree configuration providers must sample block states".to_string());
    }
    Ok(())
}

pub fn configured_tree_placement_plan(
    origin: BlockPos,
    config: &TreeConfigurationModel,
    build_min_y: i32,
    build_max_y: i32,
    replaceable_rows: &[&[&str]],
    rand_a: i32,
    rand_b: i32,
) -> Result<Option<TreePlacementPlan>, String> {
    validate_tree_configuration(config)?;
    let tree_height = trunk_placer_height(config.trunk_placer, rand_a, rand_b);
    if !tree_can_place(
        origin,
        origin,
        tree_height,
        config.minimum_size,
        feature_size_min_clipped_height(config.minimum_size),
        build_min_y,
        build_max_y,
        replaceable_rows,
        config.ignore_vines,
    ) {
        return Ok(None);
    }

    Ok(Some(simple_tree_placement_plan(
        origin,
        config.trunk_placer,
        config.foliage_placer,
        block_state_provider_sample(&config.trunk_provider, rand_a)
            .expect("tree configuration was validated"),
        block_state_provider_sample(&config.foliage_provider, rand_b)
            .expect("tree configuration was validated"),
        block_state_provider_sample(&config.dirt_provider, rand_a.wrapping_add(rand_b))
            .expect("tree configuration was validated"),
        rand_a,
        rand_b,
    )?))
}

pub fn validate_foliage_placer(placer: FoliagePlacerModel) -> Result<FoliagePlacerModel, String> {
    if !(0..=16).contains(&placer.radius_min)
        || !(0..=16).contains(&placer.radius_max)
        || placer.radius_min > placer.radius_max
        || !(0..=16).contains(&placer.offset_min)
        || !(0..=16).contains(&placer.offset_max)
        || placer.offset_min > placer.offset_max
    {
        return Err("foliage placer base providers are outside vanilla codec ranges".to_string());
    }

    let valid = match placer.kind {
        FoliagePlacerKind::Blob { height }
        | FoliagePlacerKind::Bush { height }
        | FoliagePlacerKind::Fancy { height }
        | FoliagePlacerKind::Jungle { height } => (0..=16).contains(&height),
        FoliagePlacerKind::Cherry { height, .. } => (4..=16).contains(&height),
        FoliagePlacerKind::Spruce {
            height_min,
            height_max,
        }
        | FoliagePlacerKind::Pine {
            height_min,
            height_max,
        }
        | FoliagePlacerKind::MegaPine {
            height_min,
            height_max,
        } => {
            (0..=24).contains(&height_min)
                && (0..=24).contains(&height_max)
                && height_min <= height_max
        }
        FoliagePlacerKind::Acacia | FoliagePlacerKind::DarkOak => true,
        FoliagePlacerKind::RandomSpread {
            foliage_height_min,
            foliage_height_max,
            leaf_placement_attempts,
        } => {
            (1..=512).contains(&foliage_height_min)
                && (1..=512).contains(&foliage_height_max)
                && foliage_height_min <= foliage_height_max
                && (0..=256).contains(&leaf_placement_attempts)
        }
    };

    let chance_valid = match placer.kind {
        FoliagePlacerKind::Cherry {
            wide_bottom_layer_hole_chance,
            corner_hole_chance,
            hanging_leaves_chance,
            hanging_leaves_extension_chance,
            ..
        } => [
            wide_bottom_layer_hole_chance,
            corner_hole_chance,
            hanging_leaves_chance,
            hanging_leaves_extension_chance,
        ]
        .into_iter()
        .all(|chance| (0.0..=1.0).contains(&chance)),
        _ => true,
    };

    if valid && chance_valid {
        Ok(placer)
    } else {
        Err("foliage placer variant fields are outside vanilla codec ranges".to_string())
    }
}

pub fn validate_root_placer(placer: RootPlacerModel) -> Result<RootPlacerModel, String> {
    if placer
        .above_root_placement_chance
        .is_some_and(|chance| !(0.0..=1.0).contains(&chance))
        || !(1..=12).contains(&placer.mangrove_root_placement.max_root_width)
        || !(1..=64).contains(&placer.mangrove_root_placement.max_root_length)
        || !(0.0..=1.0).contains(&placer.mangrove_root_placement.random_skew_chance)
    {
        Err("root placer fields are outside vanilla codec ranges".to_string())
    } else {
        Ok(placer)
    }
}

pub fn validate_root_system_configuration(
    config: &RootSystemConfigurationModel,
) -> Result<(), String> {
    if !(1..=64).contains(&config.required_vertical_space_for_tree)
        || !(1..=64).contains(&config.root_radius)
        || !(1..=256).contains(&config.root_placement_attempts)
        || !(1..=4096).contains(&config.root_column_max_height)
        || !(1..=64).contains(&config.hanging_root_radius)
        || !(1..=16).contains(&config.hanging_roots_vertical_span)
        || !(1..=256).contains(&config.hanging_root_placement_attempts)
        || !(1..=64).contains(&config.allowed_vertical_water_for_tree)
    {
        Err("root system configuration fields are outside vanilla codec ranges".to_string())
    } else {
        Ok(())
    }
}

pub fn mangrove_potential_root_positions(
    pos: BlockPos,
    prev_dir: HorizontalDirection,
    root_origin: BlockPos,
    max_root_width: i32,
    random_skew_chance: f32,
    skew_roll: f32,
    choose_next_to: bool,
) -> Vec<BlockPos> {
    let below = BlockPos {
        x: pos.x,
        y: pos.y - 1,
        z: pos.z,
    };
    let next_to = offset_horizontal(pos, prev_dir, 1);
    let next_to_below = BlockPos {
        x: next_to.x,
        y: next_to.y - 1,
        z: next_to.z,
    };
    let width = (pos.x - root_origin.x).abs()
        + (pos.y - root_origin.y).abs()
        + (pos.z - root_origin.z).abs();
    if width > max_root_width - 3 && width <= max_root_width {
        if skew_roll < random_skew_chance {
            vec![below, next_to_below]
        } else {
            vec![below]
        }
    } else if width > max_root_width || skew_roll < random_skew_chance {
        vec![below]
    } else if choose_next_to {
        vec![next_to]
    } else {
        vec![below]
    }
}

pub fn root_system_placement_plan(
    origin: BlockPos,
    origin_is_air: bool,
    config: &RootSystemConfigurationModel,
    tree_candidates: &[RootSystemTreeCandidateModel],
    root_rolls: &[RootSystemOffsetRoll],
    hanging_root_rolls: &[RootSystemOffsetRoll],
    root_replaceable_positions: &[BlockPos],
    hanging_root_candidates: &[BlockPos],
) -> Result<RootSystemPlacementPlan, String> {
    validate_root_system_configuration(config)?;
    if !origin_is_air {
        return Ok(RootSystemPlacementPlan {
            tree_origin: None,
            blocks: Vec::new(),
            attempted_roots: false,
        });
    }

    for y in 0..config.root_column_max_height {
        let working_pos = BlockPos {
            x: origin.x,
            y: origin.y + y + 1,
            z: origin.z,
        };
        let Some(candidate) = tree_candidates
            .iter()
            .find(|candidate| candidate.pos == working_pos)
        else {
            continue;
        };
        if !candidate.allowed_tree_position
            || !root_system_space_for_tree(
                &candidate.vertical_space_states,
                config.required_vertical_space_for_tree,
                config.allowed_vertical_water_for_tree,
            )
        {
            continue;
        }
        if root_system_below_rejects_tree(candidate.below_state) {
            return Ok(RootSystemPlacementPlan {
                tree_origin: None,
                blocks: Vec::new(),
                attempted_roots: false,
            });
        }
        if !candidate.tree_feature_places {
            continue;
        }

        let mut blocks = root_system_dirt_placements(
            origin,
            origin.y + y,
            config,
            root_rolls,
            root_replaceable_positions,
        );
        blocks.extend(root_system_hanging_root_placements(
            origin,
            config,
            hanging_root_rolls,
            hanging_root_candidates,
        ));
        return Ok(RootSystemPlacementPlan {
            tree_origin: Some(candidate.pos),
            blocks,
            attempted_roots: true,
        });
    }

    Ok(RootSystemPlacementPlan {
        tree_origin: None,
        blocks: Vec::new(),
        attempted_roots: false,
    })
}

pub fn root_system_space_for_tree(
    vertical_space_states: &[&str],
    required_vertical_space_for_tree: i32,
    allowed_vertical_water_for_tree: i32,
) -> bool {
    (1..=required_vertical_space_for_tree).all(|blocks_above_origin| {
        let state = vertical_space_states
            .get((blocks_above_origin - 1) as usize)
            .copied()
            .unwrap_or("minecraft:air");
        root_system_is_allowed_tree_space(
            state,
            blocks_above_origin,
            allowed_vertical_water_for_tree,
        )
    })
}

pub fn root_system_is_allowed_tree_space(
    state: &str,
    blocks_above_origin: i32,
    allowed_vertical_water_for_tree: i32,
) -> bool {
    if matches!(
        state,
        "minecraft:air" | "minecraft:cave_air" | "minecraft:void_air"
    ) {
        return true;
    }
    let blocks_above_ground = blocks_above_origin + 1;
    blocks_above_ground <= allowed_vertical_water_for_tree && state == "minecraft:water"
}

fn root_system_below_rejects_tree(below_state: &str) -> bool {
    below_state == "minecraft:lava" || !root_system_solid_state(below_state)
}

fn root_system_solid_state(state: &str) -> bool {
    !matches!(
        state,
        "minecraft:air"
            | "minecraft:cave_air"
            | "minecraft:void_air"
            | "minecraft:water"
            | "minecraft:lava"
    )
}

fn root_system_dirt_placements(
    origin: BlockPos,
    target_height: i32,
    config: &RootSystemConfigurationModel,
    rolls: &[RootSystemOffsetRoll],
    replaceable_positions: &[BlockPos],
) -> Vec<RootSystemPlacementBlock> {
    let mut placements = Vec::new();
    let mut roll_index = 0;
    for y in origin.y..target_height {
        let working_base = BlockPos {
            x: origin.x,
            y,
            z: origin.z,
        };
        for _ in 0..config.root_placement_attempts {
            let roll = rolls.get(roll_index).copied().unwrap_or_default();
            roll_index += 1;
            let pos = BlockPos {
                x: working_base.x + roll.positive_x.rem_euclid(config.root_radius)
                    - roll.negative_x.rem_euclid(config.root_radius),
                y: working_base.y,
                z: working_base.z + roll.positive_z.rem_euclid(config.root_radius)
                    - roll.negative_z.rem_euclid(config.root_radius),
            };
            if replaceable_positions.contains(&pos) {
                placements.push(RootSystemPlacementBlock {
                    pos,
                    state: block_state_provider_sample(
                        &config.root_state_provider,
                        roll_index as i32,
                    )
                    .unwrap_or("minecraft:air"),
                    kind: RootSystemPlacementKind::RootedDirt,
                });
            }
        }
    }
    placements
}

fn root_system_hanging_root_placements(
    origin: BlockPos,
    config: &RootSystemConfigurationModel,
    rolls: &[RootSystemOffsetRoll],
    candidates: &[BlockPos],
) -> Vec<RootSystemPlacementBlock> {
    let mut placements = Vec::new();
    for attempt in 0..config.hanging_root_placement_attempts {
        let roll = rolls.get(attempt as usize).copied().unwrap_or_default();
        let pos = BlockPos {
            x: origin.x + roll.positive_x.rem_euclid(config.hanging_root_radius)
                - roll.negative_x.rem_euclid(config.hanging_root_radius),
            y: origin.y
                + roll
                    .positive_y
                    .rem_euclid(config.hanging_roots_vertical_span)
                - roll
                    .negative_y
                    .rem_euclid(config.hanging_roots_vertical_span),
            z: origin.z + roll.positive_z.rem_euclid(config.hanging_root_radius)
                - roll.negative_z.rem_euclid(config.hanging_root_radius),
        };
        if candidates.contains(&pos) {
            placements.push(RootSystemPlacementBlock {
                pos,
                state: block_state_provider_sample(&config.hanging_root_state_provider, attempt)
                    .unwrap_or("minecraft:air"),
                kind: RootSystemPlacementKind::HangingRoot,
            });
        }
    }
    placements
}

pub fn simple_tree_placement_plan(
    origin: BlockPos,
    trunk: TrunkPlacerModel,
    foliage: FoliagePlacerModel,
    trunk_state: &'static str,
    foliage_state: &'static str,
    below_trunk_state: &'static str,
    rand_a: i32,
    rand_b: i32,
) -> Result<TreePlacementPlan, String> {
    validate_trunk_placer(trunk)?;
    validate_foliage_placer(foliage)?;
    if trunk.kind != TrunkPlacerKind::Straight {
        return Err(
            "only straight trunk placement is modeled by simple_tree_placement_plan".to_string(),
        );
    }

    let tree_height = trunk_placer_height(trunk, rand_a, rand_b);
    let (foliage_height, bush_shape) = match foliage.kind {
        FoliagePlacerKind::Blob { height }
        | FoliagePlacerKind::Fancy { height }
        | FoliagePlacerKind::Jungle { height } => (height, false),
        FoliagePlacerKind::Bush { height } => (height, true),
        FoliagePlacerKind::Acacia | FoliagePlacerKind::DarkOak => (0, false),
        FoliagePlacerKind::Pine {
            height_min,
            height_max,
        } => (sample_inclusive_i32(height_min, height_max, rand_a), false),
        FoliagePlacerKind::Spruce {
            height_min,
            height_max,
        } => (
            (tree_height - sample_inclusive_i32(height_min, height_max, rand_a)).max(4),
            false,
        ),
        FoliagePlacerKind::MegaPine {
            height_min,
            height_max,
        } => (sample_inclusive_i32(height_min, height_max, rand_a), false),
        FoliagePlacerKind::RandomSpread {
            foliage_height_min,
            foliage_height_max,
            ..
        } => (
            sample_inclusive_i32(foliage_height_min, foliage_height_max, rand_a),
            false,
        ),
        FoliagePlacerKind::Cherry { height, .. } => (height, false),
    };

    let leaf_radius = sample_inclusive_i32(foliage.radius_min, foliage.radius_max, rand_a);
    let foliage_offset = sample_inclusive_i32(foliage.offset_min, foliage.offset_max, rand_b);
    let mut blocks = Vec::new();
    push_tree_block(
        &mut blocks,
        TreePlacementBlock {
            pos: BlockPos {
                x: origin.x,
                y: origin.y - 1,
                z: origin.z,
            },
            state: below_trunk_state,
            kind: TreePlacementBlockKind::DirtBelowTrunk,
        },
    );
    for y in 0..tree_height {
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos {
                    x: origin.x,
                    y: origin.y + y,
                    z: origin.z,
                },
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
    }

    let foliage_origin = BlockPos {
        x: origin.x,
        y: origin.y + tree_height,
        z: origin.z,
    };
    if foliage.kind == FoliagePlacerKind::Acacia {
        let acacia_origin = BlockPos {
            x: foliage_origin.x,
            y: foliage_origin.y + foliage_offset,
            z: foliage_origin.z,
        };
        place_acacia_leaves_row(
            &mut blocks,
            acacia_origin,
            leaf_radius,
            -1 - foliage_height,
            foliage_state,
        );
        place_acacia_leaves_row(
            &mut blocks,
            acacia_origin,
            leaf_radius - 1,
            -foliage_height,
            foliage_state,
        );
        place_acacia_leaves_row(
            &mut blocks,
            acacia_origin,
            leaf_radius - 1,
            0,
            foliage_state,
        );
    } else if foliage.kind == FoliagePlacerKind::DarkOak {
        let dark_oak_origin = BlockPos {
            x: foliage_origin.x,
            y: foliage_origin.y + foliage_offset,
            z: foliage_origin.z,
        };
        place_dark_oak_single_trunk_leaves_row(
            &mut blocks,
            dark_oak_origin,
            leaf_radius + 2,
            -1,
            foliage_state,
        );
        place_dark_oak_single_trunk_leaves_row(
            &mut blocks,
            dark_oak_origin,
            leaf_radius + 1,
            0,
            foliage_state,
        );
    } else if matches!(foliage.kind, FoliagePlacerKind::Pine { .. }) {
        for (y_offset, current_radius) in
            pine_foliage_rows(foliage_offset, foliage_height, leaf_radius)
        {
            place_conifer_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
            );
        }
    } else if matches!(foliage.kind, FoliagePlacerKind::Spruce { .. }) {
        for (y_offset, current_radius) in spruce_foliage_rows(
            foliage_offset,
            foliage_height,
            leaf_radius,
            rand_b.rem_euclid(2),
        ) {
            place_conifer_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
            );
        }
    } else if matches!(foliage.kind, FoliagePlacerKind::MegaPine { .. }) {
        for (y_offset, current_radius) in mega_pine_foliage_rows(
            foliage_origin.y,
            foliage_offset,
            foliage_height,
            leaf_radius,
        ) {
            place_mega_pine_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
            );
        }
    } else if let FoliagePlacerKind::Cherry {
        wide_bottom_layer_hole_chance,
        corner_hole_chance,
        ..
    } = foliage.kind
    {
        let cherry_origin = BlockPos {
            x: foliage_origin.x,
            y: foliage_origin.y + foliage_offset,
            z: foliage_origin.z,
        };
        for (y_offset, current_radius) in cherry_foliage_rows(foliage_height, leaf_radius) {
            place_cherry_leaves_row(
                &mut blocks,
                cherry_origin,
                current_radius,
                y_offset,
                foliage_state,
                wide_bottom_layer_hole_chance,
                corner_hole_chance,
                rand_a,
                rand_b,
            );
        }
    } else if let FoliagePlacerKind::RandomSpread {
        leaf_placement_attempts,
        ..
    } = foliage.kind
    {
        let rolls = deterministic_random_spread_rolls(
            rand_a,
            rand_b,
            leaf_radius,
            foliage_height,
            leaf_placement_attempts,
        );
        for pos in random_spread_foliage_positions(
            foliage_origin,
            foliage_height,
            leaf_radius,
            leaf_placement_attempts,
            &rolls,
        ) {
            push_tree_block(
                &mut blocks,
                TreePlacementBlock {
                    pos,
                    state: foliage_state,
                    kind: TreePlacementBlockKind::Leaves,
                },
            );
        }
    } else if matches!(foliage.kind, FoliagePlacerKind::Jungle { .. }) {
        for (y_offset, current_radius) in
            mega_jungle_foliage_rows(foliage_offset, 1 + rand_b.rem_euclid(2), leaf_radius)
        {
            place_mega_pine_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
            );
        }
    } else if matches!(foliage.kind, FoliagePlacerKind::Fancy { .. }) {
        for (y_offset, current_radius) in
            fancy_foliage_rows(foliage_offset, foliage_height, leaf_radius)
        {
            place_fancy_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
            );
        }
    } else {
        for y_offset in ((foliage_offset - foliage_height)..=foliage_offset).rev() {
            let current_radius = if bush_shape {
                leaf_radius - 1 - y_offset
            } else {
                (leaf_radius - 1 - y_offset / 2).max(0)
            };
            if current_radius < 0 {
                continue;
            }
            place_simple_leaves_row(
                &mut blocks,
                foliage_origin,
                current_radius,
                y_offset,
                foliage_state,
                matches!(foliage.kind, FoliagePlacerKind::Blob { .. }),
                rand_a,
                rand_b,
            );
        }
    }

    Ok(TreePlacementPlan { blocks })
}

pub fn forking_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    lean_direction: HorizontalDirection,
    branch_direction: HorizontalDirection,
    lean_height_roll: i32,
    lean_steps_roll: i32,
    branch_pos_roll: i32,
    branch_steps_roll: i32,
) -> TrunkPlacementPlan {
    let mut blocks = vec![TreePlacementBlock {
        pos: BlockPos {
            x: origin.x,
            y: origin.y - 1,
            z: origin.z,
        },
        state: below_trunk_state,
        kind: TreePlacementBlockKind::DirtBelowTrunk,
    }];
    let mut attachments = Vec::new();
    let lean_height = tree_height - lean_height_roll.rem_euclid(4) - 1;
    let mut lean_steps = 3 - lean_steps_roll.rem_euclid(3);
    let mut tx = origin.x;
    let mut tz = origin.z;
    let mut last_top_y = None;

    for y_offset in 0..tree_height {
        let y = origin.y + y_offset;
        if y_offset >= lean_height && lean_steps > 0 {
            let moved = offset_horizontal(BlockPos { x: tx, y, z: tz }, lean_direction, 1);
            tx = moved.x;
            tz = moved.z;
            lean_steps -= 1;
        }
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos { x: tx, y, z: tz },
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
        last_top_y = Some(y + 1);
    }

    if let Some(y) = last_top_y {
        attachments.push(TreeFoliageAttachmentModel {
            pos: BlockPos { x: tx, y, z: tz },
            radius_offset: 1,
            double_trunk: false,
        });
    }

    if branch_direction != lean_direction {
        tx = origin.x;
        tz = origin.z;
        let branch_pos = lean_height - branch_pos_roll.rem_euclid(2) - 1;
        let mut branch_steps = 1 + branch_steps_roll.rem_euclid(3);
        last_top_y = None;
        let mut y_offset = branch_pos;
        while y_offset < tree_height && branch_steps > 0 {
            if y_offset >= 1 {
                let y = origin.y + y_offset;
                let moved = offset_horizontal(BlockPos { x: tx, y, z: tz }, branch_direction, 1);
                tx = moved.x;
                tz = moved.z;
                push_tree_block(
                    &mut blocks,
                    TreePlacementBlock {
                        pos: BlockPos { x: tx, y, z: tz },
                        state: trunk_state,
                        kind: TreePlacementBlockKind::Log,
                    },
                );
                last_top_y = Some(y + 1);
            }
            y_offset += 1;
            branch_steps -= 1;
        }

        if let Some(y) = last_top_y {
            attachments.push(TreeFoliageAttachmentModel {
                pos: BlockPos { x: tx, y, z: tz },
                radius_offset: 0,
                double_trunk: false,
            });
        }
    }

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

pub fn bending_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    direction: HorizontalDirection,
    min_height_for_leaves: i32,
    bend_length: i32,
    bend_start_roll: i32,
) -> TrunkPlacementPlan {
    let mut blocks = vec![TreePlacementBlock {
        pos: BlockPos {
            x: origin.x,
            y: origin.y - 1,
            z: origin.z,
        },
        state: below_trunk_state,
        kind: TreePlacementBlockKind::DirtBelowTrunk,
    }];
    let mut attachments = Vec::new();
    let log_height = tree_height - 1;
    let mut pos = origin;

    for i in 0..=log_height {
        if i + 1 >= log_height + bend_start_roll.rem_euclid(2) {
            pos = offset_horizontal(pos, direction, 1);
        }
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos,
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
        if i >= min_height_for_leaves {
            attachments.push(TreeFoliageAttachmentModel {
                pos,
                radius_offset: 0,
                double_trunk: false,
            });
        }
        pos.y += 1;
    }

    for _ in 0..=bend_length {
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos,
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
        attachments.push(TreeFoliageAttachmentModel {
            pos,
            radius_offset: 0,
            double_trunk: false,
        });
        pos = offset_horizontal(pos, direction, 1);
    }

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

pub fn giant_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
) -> TrunkPlacementPlan {
    let mut blocks = Vec::new();
    for (dx, dz) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos {
                    x: origin.x + dx,
                    y: origin.y - 1,
                    z: origin.z + dz,
                },
                state: below_trunk_state,
                kind: TreePlacementBlockKind::DirtBelowTrunk,
            },
        );
    }

    for y_offset in 0..tree_height {
        let full_2x2_layer = y_offset < tree_height - 1;
        for (dx, dz) in [(0, 0), (1, 0), (1, 1), (0, 1)] {
            if !full_2x2_layer && (dx != 0 || dz != 0) {
                continue;
            }
            push_tree_block(
                &mut blocks,
                TreePlacementBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + y_offset,
                        z: origin.z + dz,
                    },
                    state: trunk_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
        }
    }

    TrunkPlacementPlan {
        blocks,
        attachments: vec![TreeFoliageAttachmentModel {
            pos: BlockPos {
                x: origin.x,
                y: origin.y + tree_height,
                z: origin.z,
            },
            radius_offset: 0,
            double_trunk: true,
        }],
    }
}

pub fn mega_jungle_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    branches: &[MegaJungleBranchModel],
) -> TrunkPlacementPlan {
    let mut plan = giant_trunk_placement_plan(origin, tree_height, trunk_state, below_trunk_state);
    for branch in branches {
        let mut bx = 0;
        let mut bz = 0;
        for b in 0..5 {
            bx = (1.5 + branch.angle_radians.cos() * b as f32) as i32;
            bz = (1.5 + branch.angle_radians.sin() * b as f32) as i32;
            push_tree_block(
                &mut plan.blocks,
                TreePlacementBlock {
                    pos: BlockPos {
                        x: origin.x + bx,
                        y: origin.y + branch.branch_height - 3 + b / 2,
                        z: origin.z + bz,
                    },
                    state: trunk_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
        }
        plan.attachments.push(TreeFoliageAttachmentModel {
            pos: BlockPos {
                x: origin.x + bx,
                y: origin.y + branch.branch_height,
                z: origin.z + bz,
            },
            radius_offset: -2,
            double_trunk: false,
        });
    }
    plan
}

pub fn dark_oak_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    lean_direction: HorizontalDirection,
    lean_height_roll: i32,
    lean_steps_roll: i32,
    branch_rolls: &[i32],
) -> TrunkPlacementPlan {
    let mut blocks = Vec::new();
    for (dx, dz) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos {
                    x: origin.x + dx,
                    y: origin.y - 1,
                    z: origin.z + dz,
                },
                state: below_trunk_state,
                kind: TreePlacementBlockKind::DirtBelowTrunk,
            },
        );
    }

    let lean_height = tree_height - lean_height_roll.rem_euclid(4);
    let mut lean_steps = 2 - lean_steps_roll.rem_euclid(3);
    let mut tx = origin.x;
    let mut tz = origin.z;
    let ey = origin.y + tree_height - 1;
    for y_offset in 0..tree_height {
        if y_offset >= lean_height && lean_steps > 0 {
            let moved = offset_horizontal(
                BlockPos {
                    x: tx,
                    y: origin.y + y_offset,
                    z: tz,
                },
                lean_direction,
                1,
            );
            tx = moved.x;
            tz = moved.z;
            lean_steps -= 1;
        }
        for (dx, dz) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
            push_tree_block(
                &mut blocks,
                TreePlacementBlock {
                    pos: BlockPos {
                        x: tx + dx,
                        y: origin.y + y_offset,
                        z: tz + dz,
                    },
                    state: trunk_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
        }
    }

    let mut attachments = vec![TreeFoliageAttachmentModel {
        pos: BlockPos {
            x: tx,
            y: ey,
            z: tz,
        },
        radius_offset: 0,
        double_trunk: true,
    }];
    let mut roll_index = 0;
    for ox in -1..=2 {
        for oz in -1..=2 {
            if (0..=1).contains(&ox) && (0..=1).contains(&oz) {
                continue;
            }
            let gate_roll = branch_rolls.get(roll_index).copied().unwrap_or(1);
            roll_index += 1;
            if gate_roll.rem_euclid(3) > 0 {
                continue;
            }
            let length_roll = branch_rolls.get(roll_index).copied().unwrap_or(0);
            roll_index += 1;
            let length = length_roll.rem_euclid(3) + 2;
            for branch_y in 0..length {
                push_tree_block(
                    &mut blocks,
                    TreePlacementBlock {
                        pos: BlockPos {
                            x: origin.x + ox,
                            y: ey - branch_y - 1,
                            z: origin.z + oz,
                        },
                        state: trunk_state,
                        kind: TreePlacementBlockKind::Log,
                    },
                );
            }
            attachments.push(TreeFoliageAttachmentModel {
                pos: BlockPos {
                    x: origin.x + ox,
                    y: ey,
                    z: origin.z + oz,
                },
                radius_offset: 0,
                double_trunk: false,
            });
        }
    }

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

pub fn upwards_branching_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    branches: &[UpwardsBranchingBranchModel],
) -> TrunkPlacementPlan {
    let mut blocks = Vec::new();
    let mut attachments = Vec::new();

    for height_pos in 0..tree_height {
        let current_height = origin.y + height_pos;
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos {
                    x: origin.x,
                    y: current_height,
                    z: origin.z,
                },
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );

        for branch in branches
            .iter()
            .copied()
            .filter(|branch| branch.trunk_y_offset == height_pos && height_pos < tree_height - 1)
        {
            place_upwards_branching_branch(
                &mut blocks,
                &mut attachments,
                origin,
                tree_height,
                trunk_state,
                branch,
            );
        }

        if height_pos == tree_height - 1 {
            attachments.push(TreeFoliageAttachmentModel {
                pos: BlockPos {
                    x: origin.x,
                    y: current_height + 1,
                    z: origin.z,
                },
                radius_offset: 0,
                double_trunk: false,
            });
        }
    }

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

pub fn cherry_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    branch_count: i32,
    branches: &[CherryBranchModel],
) -> TrunkPlacementPlan {
    let mut blocks = vec![TreePlacementBlock {
        pos: BlockPos {
            x: origin.x,
            y: origin.y - 1,
            z: origin.z,
        },
        state: below_trunk_state,
        kind: TreePlacementBlockKind::DirtBelowTrunk,
    }];
    let has_middle_branch = branch_count == 3;
    let trunk_height = if has_middle_branch {
        tree_height
    } else {
        branches
            .iter()
            .take(branch_count.clamp(1, 2) as usize)
            .map(|branch| branch.start_offset_from_origin + 1)
            .max()
            .unwrap_or(tree_height)
    };
    for y_offset in 0..trunk_height {
        push_tree_block(
            &mut blocks,
            TreePlacementBlock {
                pos: BlockPos {
                    x: origin.x,
                    y: origin.y + y_offset,
                    z: origin.z,
                },
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
    }

    let mut attachments = Vec::new();
    if has_middle_branch {
        attachments.push(TreeFoliageAttachmentModel {
            pos: BlockPos {
                x: origin.x,
                y: origin.y + trunk_height,
                z: origin.z,
            },
            radius_offset: 0,
            double_trunk: false,
        });
    }
    for branch in branches.iter().take(branch_count.clamp(1, 3) as usize) {
        attachments.push(place_cherry_branch(
            &mut blocks,
            origin,
            tree_height,
            trunk_state,
            branch,
        ));
    }

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

pub fn fancy_trunk_placement_plan(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    cluster_rolls: &[FancyTrunkClusterRollModel],
) -> TrunkPlacementPlan {
    fancy_trunk_placement_plan_with_limb_validator(
        origin,
        tree_height,
        trunk_state,
        below_trunk_state,
        cluster_rolls,
        |_| true,
    )
}

fn live_fancy_trunk_placement_plan(
    block_context: &TreeDecorationBlockContext<'_>,
    previous_source_blocks: &TreeBlockOverlay,
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    cluster_rolls: &[FancyTrunkClusterRollModel],
) -> TrunkPlacementPlan {
    fancy_trunk_placement_plan_with_limb_validator(
        origin,
        tree_height,
        trunk_state,
        below_trunk_state,
        cluster_rolls,
        |pos| {
            let world_pos = local_tree_block_to_world(block_context.source_pos, pos);
            let state = live_tree_state_with_previous_overlay(
                block_context,
                previous_source_blocks,
                world_pos,
            );
            tree_trunk_free_pos(&state)
        },
    )
}

fn fancy_trunk_placement_plan_with_limb_validator<F>(
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    below_trunk_state: &'static str,
    cluster_rolls: &[FancyTrunkClusterRollModel],
    mut limb_is_free: F,
) -> TrunkPlacementPlan
where
    F: FnMut(BlockPos) -> bool,
{
    let height = tree_height + 2;
    let trunk_height = ((height as f64) * 0.618).floor() as i32;
    let trunk_top_y = origin.y + trunk_height;
    let clusters_per_y = 1.min((1.382 + ((height as f64) / 13.0).powi(2)).floor() as i32);
    let mut blocks = vec![TreePlacementBlock {
        pos: BlockPos {
            x: origin.x,
            y: origin.y - 1,
            z: origin.z,
        },
        state: below_trunk_state,
        kind: TreePlacementBlockKind::DirtBelowTrunk,
    }];
    let mut foliage_coords = vec![(
        TreeFoliageAttachmentModel {
            pos: BlockPos {
                x: origin.x,
                y: origin.y + height - 5,
                z: origin.z,
            },
            radius_offset: 0,
            double_trunk: false,
        },
        trunk_top_y,
    )];

    let mut roll_index = 0;
    for relative_y in (0..=(height - 5)).rev() {
        let tree_shape = fancy_trunk_tree_shape(height, relative_y);
        if tree_shape < 0.0 {
            continue;
        }
        for _ in 0..clusters_per_y {
            let roll =
                cluster_rolls
                    .get(roll_index)
                    .copied()
                    .unwrap_or(FancyTrunkClusterRollModel {
                        shape_float: 0.0,
                        angle_float: 0.0,
                    });
            roll_index += 1;
            let radius = f64::from(tree_shape) * f64::from(roll.shape_float + 0.328);
            let angle = f64::from(roll.angle_float) * 2.0 * std::f64::consts::PI;
            let x = radius * angle.sin() + 0.5;
            let z = radius * angle.cos() + 0.5;
            let check_start = BlockPos {
                x: origin.x + x.floor() as i32,
                y: origin.y + relative_y - 1,
                z: origin.z + z.floor() as i32,
            };
            let dx = origin.x - check_start.x;
            let dz = origin.z - check_start.z;
            let branch_height = check_start.y as f64 - f64::from(dx * dx + dz * dz).sqrt() * 0.381;
            let branch_top_y = if branch_height > f64::from(trunk_top_y) {
                trunk_top_y
            } else {
                branch_height as i32
            };
            let check_end = BlockPos {
                x: check_start.x,
                y: check_start.y + 5,
                z: check_start.z,
            };
            let branch_base = BlockPos {
                x: origin.x,
                y: branch_top_y,
                z: origin.z,
            };
            if fancy_trunk_limb_can_place(check_start, check_end, &mut limb_is_free)
                && fancy_trunk_limb_can_place(branch_base, check_start, &mut limb_is_free)
            {
                foliage_coords.push((
                    TreeFoliageAttachmentModel {
                        pos: check_start,
                        radius_offset: 0,
                        double_trunk: false,
                    },
                    branch_top_y,
                ));
            }
        }
    }

    fancy_trunk_place_limb(
        &mut blocks,
        origin,
        BlockPos {
            x: origin.x,
            y: origin.y + trunk_height,
            z: origin.z,
        },
        trunk_state,
    );
    for (attachment, branch_base_y) in &foliage_coords {
        let base_coord = BlockPos {
            x: origin.x,
            y: *branch_base_y,
            z: origin.z,
        };
        if base_coord != attachment.pos
            && fancy_trunk_should_trim_branch(height, branch_base_y - origin.y)
        {
            fancy_trunk_place_limb(&mut blocks, base_coord, attachment.pos, trunk_state);
        }
    }

    let attachments = foliage_coords
        .into_iter()
        .filter_map(|(attachment, branch_base_y)| {
            if fancy_trunk_should_trim_branch(height, branch_base_y - origin.y) {
                Some(attachment)
            } else {
                None
            }
        })
        .collect();

    TrunkPlacementPlan {
        blocks,
        attachments,
    }
}

fn fancy_trunk_limb_can_place<F>(start_pos: BlockPos, end_pos: BlockPos, is_free: &mut F) -> bool
where
    F: FnMut(BlockPos) -> bool,
{
    if start_pos == end_pos {
        return true;
    }
    fancy_trunk_limb_positions(start_pos, end_pos)
        .into_iter()
        .all(is_free)
}

fn fancy_trunk_limb_positions(start_pos: BlockPos, end_pos: BlockPos) -> Vec<BlockPos> {
    let delta = BlockPos {
        x: end_pos.x - start_pos.x,
        y: end_pos.y - start_pos.y,
        z: end_pos.z - start_pos.z,
    };
    let steps = delta.x.abs().max(delta.y.abs()).max(delta.z.abs());
    if steps == 0 {
        return vec![start_pos];
    }

    let dx = delta.x as f32 / steps as f32;
    let dy = delta.y as f32 / steps as f32;
    let dz = delta.z as f32 / steps as f32;
    (0..=steps)
        .map(|i| BlockPos {
            x: start_pos.x + (0.5 + i as f32 * dx).floor() as i32,
            y: start_pos.y + (0.5 + i as f32 * dy).floor() as i32,
            z: start_pos.z + (0.5 + i as f32 * dz).floor() as i32,
        })
        .collect()
}

fn place_cherry_branch(
    blocks: &mut Vec<TreePlacementBlock>,
    origin: BlockPos,
    _tree_height: i32,
    trunk_state: &'static str,
    branch: &CherryBranchModel,
) -> TreeFoliageAttachmentModel {
    let extend_branch_away_from_trunk = branch.middle_continues_upwards
        || branch.end_offset_from_origin < branch.start_offset_from_origin;
    let distance_to_trunk = branch.horizontal_length + i32::from(extend_branch_away_from_trunk);
    let branch_end_pos = offset_horizontal(
        BlockPos {
            x: origin.x,
            y: origin.y + branch.end_offset_from_origin,
            z: origin.z,
        },
        branch.direction,
        distance_to_trunk,
    );
    let mut log_pos = BlockPos {
        x: origin.x,
        y: origin.y + branch.start_offset_from_origin,
        z: origin.z,
    };
    let horizontal_state = rotated_log_state(trunk_state, branch.direction);
    for _ in 0..if extend_branch_away_from_trunk { 2 } else { 1 } {
        log_pos = offset_horizontal(log_pos, branch.direction, 1);
        push_tree_block(
            blocks,
            TreePlacementBlock {
                pos: log_pos,
                state: horizontal_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
    }

    let mut choice_index = 0;
    while log_pos != branch_end_pos {
        let vertical_delta = branch_end_pos.y - log_pos.y;
        let horizontal_delta = match branch.direction {
            HorizontalDirection::East => branch_end_pos.x - log_pos.x,
            HorizontalDirection::West => log_pos.x - branch_end_pos.x,
            HorizontalDirection::South => branch_end_pos.z - log_pos.z,
            HorizontalDirection::North => log_pos.z - branch_end_pos.z,
        };
        let grow_vertically = if horizontal_delta == 0 {
            true
        } else if vertical_delta == 0 {
            false
        } else {
            let choice = branch
                .grow_vertically
                .get(choice_index)
                .copied()
                .unwrap_or(true);
            choice_index += 1;
            choice
        };
        if grow_vertically {
            log_pos.y += vertical_delta.signum();
            push_tree_block(
                blocks,
                TreePlacementBlock {
                    pos: log_pos,
                    state: trunk_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
        } else {
            log_pos = offset_horizontal(log_pos, branch.direction, 1);
            push_tree_block(
                blocks,
                TreePlacementBlock {
                    pos: log_pos,
                    state: horizontal_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
        }
    }

    TreeFoliageAttachmentModel {
        pos: BlockPos {
            x: branch_end_pos.x,
            y: branch_end_pos.y + 1,
            z: branch_end_pos.z,
        },
        radius_offset: 0,
        double_trunk: false,
    }
}

pub fn fancy_trunk_tree_shape(height: i32, y: i32) -> f32 {
    if (y as f32) < height as f32 * 0.3 {
        return -1.0;
    }
    let radius = height as f32 / 2.0;
    let adjacent = radius - y as f32;
    if adjacent.abs() >= radius {
        return 0.0;
    }
    let distance = if adjacent == 0.0 {
        radius
    } else {
        (radius * radius - adjacent * adjacent).sqrt()
    };
    distance * 0.5
}

fn fancy_trunk_should_trim_branch(height: i32, local_y: i32) -> bool {
    (local_y as f64) >= (height as f64) * 0.2
}

fn fancy_trunk_cluster_roll_count(tree_height: i32) -> i32 {
    let height = tree_height + 2;
    let clusters_per_y = 1.min((1.382 + ((height as f64) / 13.0).powi(2)).floor() as i32);
    (0..=(height - 5))
        .rev()
        .filter(|&relative_y| fancy_trunk_tree_shape(height, relative_y) >= 0.0)
        .count() as i32
        * clusters_per_y
}

fn fancy_trunk_place_limb(
    blocks: &mut Vec<TreePlacementBlock>,
    start_pos: BlockPos,
    end_pos: BlockPos,
    trunk_state: &'static str,
) {
    let delta = BlockPos {
        x: end_pos.x - start_pos.x,
        y: end_pos.y - start_pos.y,
        z: end_pos.z - start_pos.z,
    };
    let steps = delta.x.abs().max(delta.y.abs()).max(delta.z.abs());
    if steps == 0 {
        push_tree_block(
            blocks,
            TreePlacementBlock {
                pos: start_pos,
                state: trunk_state,
                kind: TreePlacementBlockKind::Log,
            },
        );
        return;
    }

    let dx = delta.x as f32 / steps as f32;
    let dy = delta.y as f32 / steps as f32;
    let dz = delta.z as f32 / steps as f32;
    for i in 0..=steps {
        let pos = BlockPos {
            x: start_pos.x + (0.5 + i as f32 * dx).floor() as i32,
            y: start_pos.y + (0.5 + i as f32 * dy).floor() as i32,
            z: start_pos.z + (0.5 + i as f32 * dz).floor() as i32,
        };
        push_tree_block(
            blocks,
            TreePlacementBlock {
                pos,
                state: fancy_trunk_log_state(trunk_state, start_pos, pos),
                kind: TreePlacementBlockKind::Log,
            },
        );
    }
}

fn fancy_trunk_log_state(
    trunk_state: &'static str,
    start_pos: BlockPos,
    block_pos: BlockPos,
) -> &'static str {
    let xdiff = (block_pos.x - start_pos.x).abs();
    let zdiff = (block_pos.z - start_pos.z).abs();
    let maxdiff = xdiff.max(zdiff);
    if maxdiff == 0 {
        trunk_state
    } else if xdiff == maxdiff {
        rotated_log_state(trunk_state, HorizontalDirection::East)
    } else {
        rotated_log_state(trunk_state, HorizontalDirection::South)
    }
}

fn place_upwards_branching_branch(
    blocks: &mut Vec<TreePlacementBlock>,
    attachments: &mut Vec<TreeFoliageAttachmentModel>,
    origin: BlockPos,
    tree_height: i32,
    trunk_state: &'static str,
    branch: UpwardsBranchingBranchModel,
) {
    let current_height = origin.y + branch.trunk_y_offset;
    let mut height_along_branch = current_height + branch.branch_pos;
    let mut log_x = origin.x;
    let mut log_z = origin.z;
    let mut branch_placement_index = branch.branch_pos;
    let mut branch_steps = branch.branch_steps;

    while branch_placement_index < tree_height && branch_steps > 0 {
        if branch_placement_index >= 1 {
            let placement_height = current_height + branch_placement_index;
            let moved = offset_horizontal(
                BlockPos {
                    x: log_x,
                    y: placement_height,
                    z: log_z,
                },
                branch.direction,
                1,
            );
            log_x = moved.x;
            log_z = moved.z;
            height_along_branch = placement_height + 1;
            let log_pos = BlockPos {
                x: log_x,
                y: placement_height,
                z: log_z,
            };
            push_tree_block(
                blocks,
                TreePlacementBlock {
                    pos: log_pos,
                    state: trunk_state,
                    kind: TreePlacementBlockKind::Log,
                },
            );
            attachments.push(TreeFoliageAttachmentModel {
                pos: log_pos,
                radius_offset: 0,
                double_trunk: false,
            });
        }

        branch_placement_index += 1;
        branch_steps -= 1;
    }

    if height_along_branch - current_height > 1 {
        let foliage_pos = BlockPos {
            x: log_x,
            y: height_along_branch,
            z: log_z,
        };
        attachments.push(TreeFoliageAttachmentModel {
            pos: foliage_pos,
            radius_offset: 0,
            double_trunk: false,
        });
        attachments.push(TreeFoliageAttachmentModel {
            pos: BlockPos {
                x: foliage_pos.x,
                y: foliage_pos.y - 2,
                z: foliage_pos.z,
            },
            radius_offset: 0,
            double_trunk: false,
        });
    }
}

pub fn fallen_tree_log_length(min_length: i32, max_length: i32, sample_roll: i32) -> i32 {
    let span = (max_length - min_length + 1).max(1);
    min_length + sample_roll.rem_euclid(span) - 2
}

pub fn fallen_tree_start_pos(
    origin: BlockPos,
    direction: HorizontalDirection,
    distance_roll: i32,
    ground_probe: &[bool],
) -> Option<BlockPos> {
    let mut pos = offset_horizontal(origin, direction, 2 + distance_roll.rem_euclid(2));
    pos.y += 1;
    for can_place in ground_probe.iter().copied().take(6) {
        if can_place {
            return Some(pos);
        }
        pos.y -= 1;
    }
    None
}

pub fn fallen_tree_can_place_log(
    valid_tree_positions: &[bool],
    over_solid_ground: &[bool],
) -> bool {
    let mut ground_gap = 0;
    for (index, valid) in valid_tree_positions.iter().copied().enumerate() {
        if !valid {
            return false;
        }
        if !over_solid_ground.get(index).copied().unwrap_or(false) {
            ground_gap += 1;
            if ground_gap > 2 {
                return false;
            }
        } else {
            ground_gap = 0;
        }
    }
    true
}

pub fn fallen_tree_placement_plan(
    origin: BlockPos,
    config: &FallenTreeConfigurationModel,
    direction: HorizontalDirection,
    log_length_roll: i32,
    distance_roll: i32,
    ground_probe: &[bool],
    valid_tree_positions: &[bool],
    over_solid_ground: &[bool],
) -> Option<FallenTreePlacementPlan> {
    let trunk_state = block_state_provider_sample(&config.trunk_provider, 0)?;
    let log_length = fallen_tree_log_length(
        config.min_log_length,
        config.max_log_length,
        log_length_roll,
    );
    let start = fallen_tree_start_pos(origin, direction, distance_roll, ground_probe)?;
    let valid_len = log_length.max(0) as usize;
    if valid_tree_positions.len() < valid_len || over_solid_ground.len() < valid_len {
        return None;
    }
    if !fallen_tree_can_place_log(
        &valid_tree_positions[..valid_len],
        &over_solid_ground[..valid_len],
    ) {
        return None;
    }
    let mut blocks = vec![FallenTreeBlock {
        pos: origin,
        state: trunk_state,
        mark_above_for_post_processing: true,
    }];
    for i in 0..log_length.max(0) {
        blocks.push(FallenTreeBlock {
            pos: offset_horizontal(start, direction, i),
            state: rotated_log_state(trunk_state, direction),
            mark_above_for_post_processing: true,
        });
    }
    Some(FallenTreePlacementPlan {
        blocks,
        stump_decorators: config.stump_decorators.len(),
        log_decorators: config.log_decorators.len(),
    })
}

fn rotated_log_state(state: &'static str, direction: HorizontalDirection) -> &'static str {
    match (state, direction) {
        ("minecraft:oak_log", HorizontalDirection::East | HorizontalDirection::West) => {
            "minecraft:oak_log[axis=x]"
        }
        ("minecraft:oak_log", HorizontalDirection::North | HorizontalDirection::South) => {
            "minecraft:oak_log[axis=z]"
        }
        ("minecraft:birch_log", HorizontalDirection::East | HorizontalDirection::West) => {
            "minecraft:birch_log[axis=x]"
        }
        ("minecraft:birch_log", HorizontalDirection::North | HorizontalDirection::South) => {
            "minecraft:birch_log[axis=z]"
        }
        ("minecraft:spruce_log", HorizontalDirection::East | HorizontalDirection::West) => {
            "minecraft:spruce_log[axis=x]"
        }
        ("minecraft:spruce_log", HorizontalDirection::North | HorizontalDirection::South) => {
            "minecraft:spruce_log[axis=z]"
        }
        ("minecraft:jungle_log", HorizontalDirection::East | HorizontalDirection::West) => {
            "minecraft:jungle_log[axis=x]"
        }
        ("minecraft:jungle_log", HorizontalDirection::North | HorizontalDirection::South) => {
            "minecraft:jungle_log[axis=z]"
        }
        ("minecraft:cherry_log", HorizontalDirection::East | HorizontalDirection::West) => {
            "minecraft:cherry_log[axis=x]"
        }
        ("minecraft:cherry_log", HorizontalDirection::North | HorizontalDirection::South) => {
            "minecraft:cherry_log[axis=z]"
        }
        _ => state,
    }
}

fn place_simple_leaves_row(
    blocks: &mut Vec<TreePlacementBlock>,
    origin: BlockPos,
    radius: i32,
    y_offset: i32,
    state: &'static str,
    blob_shape: bool,
    rand_a: i32,
    rand_b: i32,
) {
    for dx in -radius..=radius {
        for dz in -radius..=radius {
            if simple_leaves_row_should_skip_corner(
                dx, y_offset, dz, radius, blob_shape, rand_a, rand_b,
            ) {
                continue;
            }
            push_tree_block(
                blocks,
                TreePlacementBlock {
                    pos: BlockPos {
                        x: origin.x + dx,
                        y: origin.y + y_offset,
                        z: origin.z + dz,
                    },
                    state,
                    kind: TreePlacementBlockKind::Leaves,
                },
            );
        }
    }
}

