    #[test]
    #[ignore = "diagnostic for live multiplayer terrain reports"]
    fn live_seed_chunk_surface_summary() {
        let seed = std::env::var("RUSTCRAFT_WORLDGEN_TEST_SEED")
            .ok()
            .and_then(|value| value.parse::<i64>().ok())
            .unwrap_or(0);
        let center_x = std::env::var("RUSTCRAFT_WORLDGEN_TEST_CHUNK_X")
            .ok()
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(0);
        let center_z = std::env::var("RUSTCRAFT_WORLDGEN_TEST_CHUNK_Z")
            .ok()
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(0);
        let radius = std::env::var("RUSTCRAFT_WORLDGEN_TEST_RADIUS")
            .ok()
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(0);

        for chunk_z in center_z - radius..=center_z + radius {
            for chunk_x in center_x - radius..=center_x + radius {
                let pos = ChunkPos {
                    x: chunk_x,
                    z: chunk_z,
                };
                let (chunk, _timings) =
                    super::generate_overworld_spawn_chunk_for_preset_with_mode_timed(
                        pos,
                        "normal",
                        super::LiveChunkGenerationMode::RealSurface,
                        seed,
                        true,
                    )
                    .expect("live seed diagnostic chunk should generate");

                let mut min_top = i32::MAX;
                let mut max_top = i32::MIN;
                let mut top_blocks = BTreeMap::<String, usize>::new();
                for local_z in 0..16 {
                    for local_x in 0..16 {
                        let world_x = chunk_x * 16 + local_x;
                        let world_z = chunk_z * 16 + local_z;
                        let mut top = -64;
                        let mut top_block = "minecraft:air".to_string();
                        for y in (-64..320).rev() {
                            let block = chunk
                                .get_block_state(world_x, y, world_z)
                                .unwrap_or_else(|| "minecraft:air".to_string());
                            if block != "minecraft:air" {
                                top = y;
                                top_block = block;
                                break;
                            }
                        }
                        min_top = min_top.min(top);
                        max_top = max_top.max(top);
                        *top_blocks.entry(top_block).or_insert(0) += 1;
                    }
                }
                eprintln!(
                    "[live-seed-surface-summary] seed={} chunk=({}, {}) top_y={}..{} top_blocks={:?}",
                    seed, chunk_x, chunk_z, min_top, max_top, top_blocks
                );
            }
        }
    }

    #[test]
    #[ignore = "wall-clock performance guard; run explicitly after worldgen optimization changes"]
    fn real_surface_spawn_area_generation_stays_under_debug_budget() {
        let default_chunk_ms = 4_u128;
        let chunk_count = 9_u128;
        let max_total_ms = std::env::var("RUSTCRAFT_WORLDGEN_SPAWN_AREA_MAX_MS")
            .ok()
            .and_then(|value| value.parse::<u128>().ok())
            .unwrap_or(default_chunk_ms * chunk_count);
        let max_chunk_ms = std::env::var("RUSTCRAFT_WORLDGEN_CHUNK_MAX_MS")
            .ok()
            .and_then(|value| value.parse::<u128>().ok())
            .unwrap_or(default_chunk_ms);
        let seed = std::env::var("RUSTCRAFT_WORLDGEN_TEST_SEED")
            .ok()
            .and_then(|value| value.parse::<i64>().ok())
            .unwrap_or(0);

        let started = std::time::Instant::now();
        let mut slowest_chunk = (ChunkPos { x: 0, z: 0 }, 0_u128);
        let mut generated = 0_usize;
        for chunk_z in -1..=1 {
            for chunk_x in -1..=1 {
                let pos = ChunkPos {
                    x: chunk_x,
                    z: chunk_z,
                };
                let chunk_started = std::time::Instant::now();
                let (chunk, timings) =
                    super::generate_overworld_spawn_chunk_for_preset_with_mode_timed(
                        pos,
                        "normal",
                        super::LiveChunkGenerationMode::RealSurface,
                        seed,
                        true,
                    )
                    .expect("real-surface spawn-area chunk generation should succeed");
                let chunk_elapsed_ms = chunk_started.elapsed().as_millis();
                generated += 1;
                if chunk_elapsed_ms > slowest_chunk.1 {
                    slowest_chunk = (pos, chunk_elapsed_ms);
                }

                assert_eq!(chunk.status, "minecraft:spawn");
                let local_x = if chunk_x == 0 { 0 } else { 8 };
                let local_z = if chunk_z == 0 { 0 } else { 8 };
                assert!(
                    (-64..320).any(|y| {
                        chunk
                            .get_block_state(local_x, y, local_z)
                            .is_some_and(|name| name != "minecraft:air")
                    }),
                    "generated chunk ({chunk_x}, {chunk_z}) should contain non-air blocks in its sampled column"
                );
                assert!(
                    chunk_elapsed_ms <= max_chunk_ms,
                    "real-surface spawn-area chunk ({chunk_x}, {chunk_z}) took {chunk_elapsed_ms}ms, above {max_chunk_ms}ms budget; timings={timings:?}"
                );
            }
        }
        let elapsed_ms = started.elapsed().as_millis();

        eprintln!(
            "[worldgen-spawn-area-perf-test] chunks={} elapsed={}ms threshold={}ms target=4ms/chunk slowest_chunk=({}, {}) slowest_ms={}",
            generated,
            elapsed_ms,
            max_total_ms,
            slowest_chunk.0.x,
            slowest_chunk.0.z,
            slowest_chunk.1
        );
        assert!(
            elapsed_ms <= max_total_ms,
            "real-surface 3x3 spawn-area generation took {elapsed_ms}ms, above {max_total_ms}ms budget (~4ms/chunk Java target); slowest_chunk={slowest_chunk:?}"
        );
    }

    #[test]
    #[ignore = "diagnostic; run explicitly when inspecting visible chunk-border terrain artifacts"]
    fn real_surface_adjacent_chunk_border_continuity_diagnostic() {
        #[derive(Debug)]
        struct EdgeSample {
            axis: &'static str,
            chunk_a: ChunkPos,
            chunk_b: ChunkPos,
            world_x_a: i32,
            world_z_a: i32,
            world_x_b: i32,
            world_z_b: i32,
            height_a: i32,
            height_b: i32,
            terrain_height_a: i32,
            terrain_height_b: i32,
            top_a: String,
            top_b: String,
        }

        fn top_block(chunk: &LevelChunk, world_x: i32, world_z: i32) -> (i32, i32, String) {
            let local_x = world_x.rem_euclid(16) as usize;
            let local_z = world_z.rem_euclid(16) as usize;
            let height = chunk
                .heightmap_value(HeightmapKind::WorldSurface, local_x, local_z)
                .or_else(|| chunk.heightmap_value(HeightmapKind::WorldSurfaceWg, local_x, local_z))
                .unwrap_or(0);
            let terrain_height = chunk
                .heightmap_value(HeightmapKind::MotionBlockingNoLeaves, local_x, local_z)
                .or_else(|| chunk.heightmap_value(HeightmapKind::OceanFloorWg, local_x, local_z))
                .unwrap_or(0);
            let top_y = height - 1;
            let top = chunk
                .get_block_state(world_x, top_y, world_z)
                .unwrap_or_else(|| "minecraft:air".to_string());
            (height, terrain_height, top)
        }

        let seed = std::env::var("RUSTCRAFT_WORLDGEN_TEST_SEED")
            .ok()
            .and_then(|value| value.parse::<i64>().ok())
            .unwrap_or(0);
        let radius = std::env::var("RUSTCRAFT_WORLDGEN_BORDER_RADIUS")
            .ok()
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(1);
        let mut chunks = BTreeMap::<(i32, i32), LevelChunk>::new();
        let mut total_generation_ms = 0_u128;

        for chunk_z in -radius..=radius {
            for chunk_x in -radius..=radius {
                let pos = ChunkPos {
                    x: chunk_x,
                    z: chunk_z,
                };
                let started = std::time::Instant::now();
                let chunk = super::generate_overworld_spawn_chunk_for_preset_with_mode(
                    pos,
                    "normal",
                    super::LiveChunkGenerationMode::RealSurface,
                    seed,
                    true,
                )
                .expect("real-surface diagnostic chunk generation should succeed");
                total_generation_ms += started.elapsed().as_millis();
                chunks.insert((chunk_x, chunk_z), chunk);
            }
        }

        let mut samples = Vec::<EdgeSample>::new();
        for chunk_z in -radius..=radius {
            for chunk_x in -radius..=radius {
                let Some(chunk) = chunks.get(&(chunk_x, chunk_z)) else {
                    continue;
                };
                if let Some(east) = chunks.get(&(chunk_x + 1, chunk_z)) {
                    for local_z in 0..16_i32 {
                        let world_z = chunk_z * 16 + local_z;
                        let world_x_a = chunk_x * 16 + 15;
                        let world_x_b = (chunk_x + 1) * 16;
                        let (height_a, terrain_height_a, top_a) =
                            top_block(chunk, world_x_a, world_z);
                        let (height_b, terrain_height_b, top_b) =
                            top_block(east, world_x_b, world_z);
                        samples.push(EdgeSample {
                            axis: "x",
                            chunk_a: ChunkPos {
                                x: chunk_x,
                                z: chunk_z,
                            },
                            chunk_b: ChunkPos {
                                x: chunk_x + 1,
                                z: chunk_z,
                            },
                            world_x_a,
                            world_z_a: world_z,
                            world_x_b,
                            world_z_b: world_z,
                            height_a,
                            height_b,
                            terrain_height_a,
                            terrain_height_b,
                            top_a,
                            top_b,
                        });
                    }
                }
                if let Some(south) = chunks.get(&(chunk_x, chunk_z + 1)) {
                    for local_x in 0..16_i32 {
                        let world_x = chunk_x * 16 + local_x;
                        let world_z_a = chunk_z * 16 + 15;
                        let world_z_b = (chunk_z + 1) * 16;
                        let (height_a, terrain_height_a, top_a) =
                            top_block(chunk, world_x, world_z_a);
                        let (height_b, terrain_height_b, top_b) =
                            top_block(south, world_x, world_z_b);
                        samples.push(EdgeSample {
                            axis: "z",
                            chunk_a: ChunkPos {
                                x: chunk_x,
                                z: chunk_z,
                            },
                            chunk_b: ChunkPos {
                                x: chunk_x,
                                z: chunk_z + 1,
                            },
                            world_x_a: world_x,
                            world_z_a,
                            world_x_b: world_x,
                            world_z_b,
                            height_a,
                            height_b,
                            terrain_height_a,
                            terrain_height_b,
                            top_a,
                            top_b,
                        });
                    }
                }
            }
        }

        samples.sort_by_key(|sample| {
            std::cmp::Reverse(
                (sample.height_a - sample.height_b)
                    .abs()
                    .max((sample.terrain_height_a - sample.terrain_height_b).abs()),
            )
        });
        let total_delta: i32 = samples
            .iter()
            .map(|sample| (sample.height_a - sample.height_b).abs())
            .sum();
        let total_terrain_delta: i32 = samples
            .iter()
            .map(|sample| (sample.terrain_height_a - sample.terrain_height_b).abs())
            .sum();
        let max_delta = samples
            .first()
            .map(|sample| (sample.height_a - sample.height_b).abs())
            .unwrap_or(0);
        let max_terrain_delta = samples
            .iter()
            .map(|sample| (sample.terrain_height_a - sample.terrain_height_b).abs())
            .max()
            .unwrap_or(0);
        let high_delta_count = samples
            .iter()
            .filter(|sample| (sample.height_a - sample.height_b).abs() >= 8)
            .count();
        let high_terrain_delta_count = samples
            .iter()
            .filter(|sample| (sample.terrain_height_a - sample.terrain_height_b).abs() >= 8)
            .count();
        let material_mismatch_count = samples
            .iter()
            .filter(|sample| sample.top_a != sample.top_b)
            .count();

        eprintln!(
            "[worldgen-border-diagnostic] seed={} radius={} chunks={} generation_total={}ms samples={} max_height_delta={} avg_height_delta={:.3} high_delta_ge_8={} max_no_leaves_delta={} avg_no_leaves_delta={:.3} high_no_leaves_delta_ge_8={} top_block_mismatches={}",
            seed,
            radius,
            chunks.len(),
            total_generation_ms,
            samples.len(),
            max_delta,
            if samples.is_empty() {
                0.0
            } else {
                f64::from(total_delta) / samples.len() as f64
            },
            high_delta_count,
            max_terrain_delta,
            if samples.is_empty() {
                0.0
            } else {
                f64::from(total_terrain_delta) / samples.len() as f64
            },
            high_terrain_delta_count,
            material_mismatch_count
        );

        for sample in samples.iter().take(16) {
            eprintln!(
                "[worldgen-border-diagnostic-sample] axis={} chunks=({},{})->({},{}) a=({}, {}) h={} no_leaves_h={} top={} b=({}, {}) h={} no_leaves_h={} top={} delta={} no_leaves_delta={}",
                sample.axis,
                sample.chunk_a.x,
                sample.chunk_a.z,
                sample.chunk_b.x,
                sample.chunk_b.z,
                sample.world_x_a,
                sample.world_z_a,
                sample.height_a,
                sample.terrain_height_a,
                sample.top_a,
                sample.world_x_b,
                sample.world_z_b,
                sample.height_b,
                sample.terrain_height_b,
                sample.top_b,
                (sample.height_a - sample.height_b).abs(),
                (sample.terrain_height_a - sample.terrain_height_b).abs()
            );
        }
    }

    #[test]
    fn lightweight_tree_context_exposes_dry_surface_as_vegetation_support() {
        let mut heights = super::TreeDecorationHeights {
            ocean_floor: [64; 16 * 16],
            world_surface: [64; 16 * 16],
            motion_blocking: [64; 16 * 16],
            motion_blocking_no_leaves: [64; 16 * 16],
        };
        let wet_column_index = 16;
        heights.ocean_floor[wet_column_index] = 62;
        heights.world_surface[wet_column_index] = 64;
        heights.motion_blocking[wet_column_index] = 64;
        heights.motion_blocking_no_leaves[wet_column_index] = 62;

        let chunk = super::LightweightTreeContextChunk {
            terrain_heights: heights,
            min_y: -64,
            max_y: 320,
        };

        assert_eq!(
            chunk.synthetic_block_state(0, 63, 0),
            "minecraft:grass_block"
        );
        assert_eq!(chunk.synthetic_block_state(0, 62, 0), "minecraft:stone");
        assert_eq!(chunk.synthetic_block_state(0, 63, 1), "minecraft:water");
        assert_eq!(chunk.synthetic_block_state(0, 61, 1), "minecraft:stone");
    }

    #[test]
    #[ignore = "diagnostic parity stocktake; run explicitly while aligning worldgen stages"]
    fn normal_overworld_stage_parity_stocktake() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("vanilla fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };

        let mut base_chunks = Vec::new();
        let mut carver_chunks = Vec::new();
        let mut structure_chunks = Vec::new();
        let mut ore_chunks = Vec::new();
        let mut full_chunks = Vec::new();
        for chunk in chunks {
            let pos = ChunkPos {
                x: chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX") as i32,
                z: chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ") as i32,
            };
            let (base, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let mut carver = base.clone();
            super::apply_configured_carvers_for_biome_source(
                &mut carver,
                biome_source_model,
                noise_settings,
                seed,
            );
            let mut structure = carver.clone();
            super::apply_mineshaft_underground_structures_to_chunk(&mut structure, seed);
            let mut ore = structure.clone();
            super::apply_underground_ore_decoration_to_chunk(
                &mut ore,
                biome_source_model,
                noise_settings,
                seed,
                None,
            );
            let mut full = ore.clone();
            super::apply_initial_tree_decoration_to_chunk(
                &mut full,
                biome_source_model,
                noise_settings,
                seed,
                None,
                None,
                None,
            );
            base_chunks.push(base);
            carver_chunks.push(carver);
            structure_chunks.push(structure);
            ore_chunks.push(ore);
            full_chunks.push(full);
        }

        for (label, chunks) in [
            ("noise_surface", &base_chunks),
            ("carvers", &carver_chunks),
            ("structures", &structure_chunks),
            ("ores", &ore_chunks),
            ("trees", &full_chunks),
        ] {
            let block = crate::worldgen_comparison::vanilla_worldgen_block_array_parity_score(
                fixture_json,
                chunks,
            )
            .expect("block parity score should compute");
            let heightmap = crate::worldgen_comparison::vanilla_worldgen_heightmap_parity_score(
                fixture_json,
                chunks,
            )
            .expect("heightmap parity score should compute");
            let column = crate::worldgen_comparison::vanilla_worldgen_column_profile_parity_score(
                fixture_json,
                chunks,
            )
            .expect("column-profile parity score should compute");
            eprintln!(
                "[worldgen-stage-parity] stage={} block={:.6} ({}/{}) heightmap={:.6} ({}/{}) column={:.6} ({}/{})",
                label,
                block.score,
                block.matching_blocks,
                block.total_blocks,
                heightmap.score,
                heightmap.matching_columns,
                heightmap.total_columns,
                column.score,
                column.matching_columns,
                column.total_columns
            );
            for mismatch in block.mismatches.iter().take(8) {
                eprintln!(
                    "[worldgen-stage-parity-mismatch] stage={} count={} expected={} actual={}",
                    label, mismatch.count, mismatch.expected, mismatch.actual
                );
            }
        }
    }

    #[test]
    #[ignore = "diagnostic for source-chunk decoration biome sets and scheduled features"]
    fn normal_overworld_decoration_source_feature_schedule_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };
        let router =
            super::builtin_noise_router(super::noise_router_id_for_settings(**noise_settings))
                .expect("normal overworld should have a built-in noise router")
                .router;
        let climate_sampler =
            super::ClimateSampler::from_noise_router(&router, seed, **noise_settings);
        let global_biome_steps = super::possible_biome_feature_steps_for_source(biome_source_model);
        let features_per_step = super::build_features_per_step(&global_biome_steps, true)
            .expect("global features should sort");
        let min_section_y = noise_settings.noise.min_y.div_euclid(16);
        let sample_quart_y = ((noise_settings.sea_level + 1).clamp(
            noise_settings.noise.min_y,
            noise_settings.noise.min_y + noise_settings.noise.height - 1,
        )) >> 2;

        for fixture_chunk in chunks.iter().take(4) {
            let target_pos = ChunkPos {
                x: fixture_chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX") as i32,
                z: fixture_chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ") as i32,
            };
            for source_z in target_pos.z - 1..=target_pos.z + 1 {
                for source_x in target_pos.x - 1..=target_pos.x + 1 {
                    let source_pos = ChunkPos {
                        x: source_x,
                        z: source_z,
                    };
                    let mut biomes = std::collections::BTreeSet::new();
                    for chunk_z in source_pos.z - 1..=source_pos.z + 1 {
                        for chunk_x in source_pos.x - 1..=source_pos.x + 1 {
                            let chunk_quart_x = chunk_x * 4;
                            let chunk_quart_z = chunk_z * 4;
                            for local_z in 0..4 {
                                for local_x in 0..4 {
                                    if let Some(biome) = super::get_biome(
                                        biome_source_model,
                                        chunk_quart_x + local_x,
                                        sample_quart_y,
                                        chunk_quart_z + local_z,
                                        &climate_sampler,
                                    ) {
                                        biomes.insert(biome);
                                    }
                                }
                            }
                        }
                    }
                    let possible_steps = super::possible_biome_feature_steps_for_decoration_region(
                        source_pos,
                        biome_source_model,
                        noise_settings,
                        &climate_sampler,
                    );
                    let plan = super::biome_decoration_feature_plan(
                        seed,
                        source_pos.x,
                        source_pos.z,
                        min_section_y,
                        &features_per_step,
                        &possible_steps,
                    );
                    let ore_features = plan
                        .feature_calls
                        .iter()
                        .filter(|call| {
                            call.step_index == GenerationDecorationStep::UndergroundOres as usize
                        })
                        .map(|call| call.feature)
                        .collect::<Vec<_>>();
                    let vegetal_features = plan
                        .feature_calls
                        .iter()
                        .filter(|call| {
                            call.step_index == GenerationDecorationStep::VegetalDecoration as usize
                        })
                        .map(|call| call.feature)
                        .collect::<Vec<_>>();
                    eprintln!(
                        "[decoration-source-schedule] target=({}, {}) source=({}, {}) biomes=[{}] ores=[{}] vegetal=[{}]",
                        target_pos.x,
                        target_pos.z,
                        source_pos.x,
                        source_pos.z,
                        biomes.into_iter().collect::<Vec<_>>().join(","),
                        ore_features.join(","),
                        vegetal_features.join(","),
                    );
                }
            }
        }
    }

