    #[test]
    #[ignore = "diagnostic for final tree-stage leaf/log placement drift"]
    fn normal_overworld_tree_mismatch_shape_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };

        let mut generated_chunks = Vec::new();
        for chunk in chunks {
            let pos = ChunkPos {
                x: chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX") as i32,
                z: chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ") as i32,
            };
            let (base, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let mut chunk = base;
            super::apply_configured_carvers_for_biome_source(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
            );
            super::apply_mineshaft_underground_structures_to_chunk(&mut chunk, seed);
            super::apply_underground_ore_decoration_to_chunk(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
                None,
            );
            super::apply_initial_tree_decoration_to_chunk(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
                None,
                None,
                None,
            );
            generated_chunks.push(chunk);
        }

        let tracked = [
            "minecraft:oak_leaves",
            "minecraft:birch_leaves",
            "minecraft:oak_log",
            "minecraft:birch_log",
            "minecraft:leaf_litter",
            "minecraft:air",
        ];
        let mut counts: BTreeMap<(String, String), usize> = BTreeMap::new();
        let mut y_ranges: BTreeMap<(String, String), (i32, i32)> = BTreeMap::new();
        let mut examples: BTreeMap<(String, String), Vec<BlockPos>> = BTreeMap::new();

        for (chunk_index, fixture_chunk) in chunks.iter().enumerate() {
            let chunk_x = fixture_chunk
                .get("chunkX")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkX") as i32;
            let chunk_z = fixture_chunk
                .get("chunkZ")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkZ") as i32;
            let y_min = fixture_chunk
                .get("yMin")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include yMin") as i32;
            let blocks = fixture_chunk
                .get("blocks")
                .and_then(serde_json::Value::as_array)
                .expect("fixture chunk should include blocks");
            let generated = &generated_chunks[chunk_index];

            for (local_x, y_column) in blocks.iter().enumerate() {
                let y_column = y_column.as_array().expect("x column should be an array");
                for (y_offset, z_column) in y_column.iter().enumerate() {
                    let world_y = y_min + y_offset as i32;
                    let z_column = z_column.as_array().expect("z column should be an array");
                    for (local_z, expected) in z_column.iter().enumerate() {
                        let expected = expected
                            .as_str()
                            .expect("fixture block should be a string")
                            .split_once('[')
                            .map_or_else(|| expected.as_str().unwrap(), |(id, _)| id);
                        let world_x = chunk_x * 16 + local_x as i32;
                        let world_z = chunk_z * 16 + local_z as i32;
                        let actual = generated
                            .get_block_state(world_x, world_y, world_z)
                            .unwrap_or_else(|| "minecraft:air".to_string());
                        if expected == actual {
                            continue;
                        }
                        if !tracked.contains(&expected) && !tracked.contains(&actual.as_str()) {
                            continue;
                        }
                        let key = (expected.to_string(), actual);
                        *counts.entry(key.clone()).or_insert(0) += 1;
                        y_ranges
                            .entry(key.clone())
                            .and_modify(|range| {
                                range.0 = range.0.min(world_y);
                                range.1 = range.1.max(world_y);
                            })
                            .or_insert((world_y, world_y));
                        let examples = examples.entry(key).or_default();
                        if examples.len() < 8 {
                            examples.push(BlockPos {
                                x: world_x,
                                y: world_y,
                                z: world_z,
                            });
                        }
                    }
                }
            }
        }

        let mut sorted = counts.into_iter().collect::<Vec<_>>();
        sorted.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
        for ((expected, actual), count) in sorted.into_iter().take(20) {
            let (min_y, max_y) = y_ranges[&(expected.clone(), actual.clone())];
            let examples = examples[&(expected.clone(), actual.clone())]
                .iter()
                .map(|pos| format!("({}, {}, {})", pos.x, pos.y, pos.z))
                .collect::<Vec<_>>()
                .join(", ");
            eprintln!(
                "[tree-shape-diagnostic] count={} expected={} actual={} y={}..{} examples={}",
                count, expected, actual, min_y, max_y, examples
            );
        }
    }

    #[test]
    #[ignore = "diagnostic for tree trunks with missing or unsupported bottom logs"]
    fn normal_overworld_tree_root_support_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let fixture_chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };

        let mut generated_chunks = Vec::new();
        for fixture_chunk in fixture_chunks {
            let pos = ChunkPos {
                x: fixture_chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX") as i32,
                z: fixture_chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ") as i32,
            };
            let (base, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let mut chunk = base;
            super::apply_configured_carvers_for_biome_source(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
            );
            super::apply_mineshaft_underground_structures_to_chunk(&mut chunk, seed);
            super::apply_underground_ore_decoration_to_chunk(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
                None,
            );
            super::apply_initial_tree_decoration_to_chunk(
                &mut chunk,
                biome_source_model,
                noise_settings,
                seed,
                None,
                None,
                None,
            );
            generated_chunks.push(chunk);
        }

        let mut unsupported_generated_logs = Vec::new();
        let mut missing_expected_base_logs = Vec::new();
        for (chunk_index, fixture_chunk) in fixture_chunks.iter().enumerate() {
            let chunk_x = fixture_chunk
                .get("chunkX")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkX") as i32;
            let chunk_z = fixture_chunk
                .get("chunkZ")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkZ") as i32;
            let y_min = fixture_chunk
                .get("yMin")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include yMin") as i32;
            let blocks = fixture_chunk
                .get("blocks")
                .and_then(serde_json::Value::as_array)
                .expect("fixture chunk should include blocks");
            let generated = &generated_chunks[chunk_index];

            for (local_x, y_column) in blocks.iter().enumerate() {
                let y_column = y_column.as_array().expect("x column should be an array");
                for (y_offset, z_column) in y_column.iter().enumerate() {
                    let world_y = y_min + y_offset as i32;
                    let z_column = z_column.as_array().expect("z column should be an array");
                    for (local_z, expected) in z_column.iter().enumerate() {
                        let world_x = chunk_x * 16 + local_x as i32;
                        let world_z = chunk_z * 16 + local_z as i32;
                        let expected = expected
                            .as_str()
                            .expect("fixture block should be a string")
                            .split_once('[')
                            .map_or_else(|| expected.as_str().unwrap(), |(id, _)| id);
                        let actual = generated
                            .get_block_state(world_x, world_y, world_z)
                            .unwrap_or_else(|| "minecraft:air".to_string());
                        if super::block_matches_tag(&actual, "minecraft:logs") {
                            let below = generated
                                .get_block_state(world_x, world_y - 1, world_z)
                                .unwrap_or_else(|| "minecraft:air".to_string());
                            let vertical_below = generated
                                .get_block_state(world_x, world_y - 1, world_z)
                                .is_some_and(|below| {
                                    super::block_matches_tag(&below, "minecraft:logs")
                                });
                            if !vertical_below
                                && !super::block_blocks_motion(&below)
                                && unsupported_generated_logs.len() < 16
                            {
                                unsupported_generated_logs.push((world_x, world_y, world_z, below));
                            }
                        }
                        if super::block_matches_tag(expected, "minecraft:logs")
                            && actual == "minecraft:air"
                        {
                            let above = generated
                                .get_block_state(world_x, world_y + 1, world_z)
                                .unwrap_or_else(|| "minecraft:air".to_string());
                            if super::block_matches_tag(&above, "minecraft:logs")
                                && missing_expected_base_logs.len() < 16
                            {
                                missing_expected_base_logs.push((
                                    world_x,
                                    world_y,
                                    world_z,
                                    expected.to_string(),
                                    above,
                                ));
                            }
                        }
                    }
                }
            }
        }

        eprintln!(
            "[tree-root-support] unsupported_generated_logs={} examples={:?}",
            unsupported_generated_logs.len(),
            unsupported_generated_logs
        );
        eprintln!(
            "[tree-root-support] missing_expected_base_logs={} examples={:?}",
            missing_expected_base_logs.len(),
            missing_expected_base_logs
        );
    }

    #[test]
    #[ignore = "diagnostic for unsupported tree logs in region-generated chunks"]
    fn normal_overworld_region_tree_root_support_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");

        let center = ChunkPos {
            x: std::env::var("RUSTCRAFT_TREE_ROOT_DIAG_CENTER_X")
                .ok()
                .and_then(|value| value.parse::<i32>().ok())
                .unwrap_or(0),
            z: std::env::var("RUSTCRAFT_TREE_ROOT_DIAG_CENTER_Z")
                .ok()
                .and_then(|value| value.parse::<i32>().ok())
                .unwrap_or(0),
        };
        let radius = std::env::var("RUSTCRAFT_TREE_ROOT_DIAG_RADIUS")
            .ok()
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(2);
        let chunks = super::generate_overworld_spawn_chunk_region_for_preset_with_mode(
            center,
            radius,
            "normal",
            super::LiveChunkGenerationMode::RealSurface,
            seed,
            false,
        )
        .expect("region generation should succeed");

        let mut unsupported_logs = Vec::new();
        let mut floating_trunks = Vec::new();
        for (chunk_pos, chunk) in &chunks {
            let min_y = chunk.min_section_y * 16;
            let max_y = min_y + chunk.sections.len() as i32 * 16;
            for local_z in 0..16 {
                for local_x in 0..16 {
                    let world_x = chunk_pos.x * 16 + local_x;
                    let world_z = chunk_pos.z * 16 + local_z;
                    for world_y in min_y..max_y {
                        let Some(state) = chunk.get_block_state(world_x, world_y, world_z) else {
                            continue;
                        };
                        if !super::block_matches_tag(&state, "minecraft:logs") {
                            continue;
                        }
                        let below = chunks
                            .get(&ChunkPos {
                                x: world_x.div_euclid(16),
                                z: world_z.div_euclid(16),
                            })
                            .and_then(|below_chunk| {
                                below_chunk.get_block_state(world_x, world_y - 1, world_z)
                            })
                            .unwrap_or_else(|| "minecraft:air".to_string());
                        let below_is_log = super::block_matches_tag(&below, "minecraft:logs");
                        if !below_is_log && !super::block_blocks_motion(&below) {
                            if unsupported_logs.len() < 24 {
                                unsupported_logs.push((world_x, world_y, world_z, state, below));
                            }
                            let above = chunk
                                .get_block_state(world_x, world_y + 1, world_z)
                                .unwrap_or_else(|| "minecraft:air".to_string());
                            if super::block_matches_tag(&above, "minecraft:logs")
                                && floating_trunks.len() < 24
                            {
                                floating_trunks.push((world_x, world_y, world_z, above));
                            }
                        }
                    }
                }
            }
        }

        eprintln!(
            "[region-tree-root-support] center=({}, {}) radius={} chunks={} unsupported_logs={} examples={:?}",
            center.x,
            center.z,
            radius,
            chunks.len(),
            unsupported_logs.len(),
            unsupported_logs
        );
        eprintln!(
            "[region-tree-root-support] floating_trunks={} examples={:?}",
            floating_trunks.len(),
            floating_trunks
        );
    }

    #[test]
    #[ignore = "diagnostic for surface/water column mismatches against the vanilla fixture"]
    fn normal_overworld_surface_water_column_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let fixture_chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };
        let router_id = super::noise_router_id_for_settings(**noise_settings);
        let noise_router = super::builtin_noise_router(router_id)
            .map(|entry| entry.router)
            .expect("normal overworld should have a built-in noise router");
        let climate_sampler =
            super::ClimateSampler::from_noise_router(&noise_router, seed, **noise_settings);
        let algorithm = if noise_settings.legacy_random_source {
            crate::random_source::RandomAlgorithm::Legacy
        } else {
            crate::random_source::RandomAlgorithm::Xoroshiro
        };
        let biome_zoom_seed = super::biome_manager_obfuscate_seed(seed);
        let surface_noise =
            super::random_state_normal_noise_snapshot(seed, **noise_settings, "minecraft:surface");
        let base_rng = crate::random_source::random_state_seed_factories(seed, algorithm).base;

        fn fixture_block_type(block: &serde_json::Value) -> &str {
            block
                .as_str()
                .and_then(|raw| raw.split_once('[').map(|(name, _)| name).or(Some(raw)))
                .expect("fixture block should be a string")
        }

        fn is_surface_water_material(block: &str) -> bool {
            matches!(
                block,
                "minecraft:water"
                    | "minecraft:sand"
                    | "minecraft:dirt"
                    | "minecraft:grass_block"
                    | "minecraft:stone"
                    | "minecraft:deepslate"
                    | "minecraft:gravel"
                    | "minecraft:air"
            )
        }

        fn column_stack_from_fixture(
            y_column: &[serde_json::Value],
            y_min: i32,
            local_z: usize,
            y0: i32,
            y1: i32,
        ) -> String {
            (y0..=y1)
                .map(|y| {
                    let block = y_column
                        .get((y - y_min) as usize)
                        .and_then(serde_json::Value::as_array)
                        .and_then(|z_column| z_column.get(local_z))
                        .map(fixture_block_type)
                        .unwrap_or("minecraft:air");
                    format!("{y}:{block}")
                })
                .collect::<Vec<_>>()
                .join(",")
        }

        fn column_stack_from_chunk(
            chunk: &LevelChunk,
            world_x: i32,
            world_z: i32,
            y0: i32,
            y1: i32,
        ) -> String {
            (y0..=y1)
                .map(|y| {
                    let block = chunk
                        .get_block_state(world_x, y, world_z)
                        .unwrap_or_else(|| "minecraft:air".to_string());
                    format!("{y}:{block}")
                })
                .collect::<Vec<_>>()
                .join(",")
        }

        fn density_and_aquifer_at(
            chunk_pos: ChunkPos,
            x: i32,
            y: i32,
            z: i32,
            seed: i64,
            settings: &super::NoiseGeneratorSettings,
            noise_router: super::NoiseRouter,
        ) -> (
            f64,
            f64,
            f64,
            f64,
            f64,
            f64,
            f64,
            f64,
            f64,
            Option<&'static str>,
        ) {
            let chunk_min_x = chunk_pos.x * 16;
            let chunk_min_z = chunk_pos.z * 16;
            let mut noise_chunk =
                super::NoiseChunk::new(chunk_min_x, chunk_min_z, *settings, seed, noise_router);
            let algorithm = if settings.legacy_random_source {
                crate::random_source::RandomAlgorithm::Legacy
            } else {
                crate::random_source::RandomAlgorithm::Xoroshiro
            };
            let factories = crate::random_source::random_state_seed_factories(seed, algorithm);
            let mut aquifer = settings.aquifers_enabled.then(|| {
                super::NoiseBasedAquifer::new(
                    &mut noise_chunk,
                    chunk_min_x,
                    chunk_min_x + 15,
                    chunk_min_z,
                    chunk_min_z + 15,
                    settings.noise.min_y,
                    settings.noise.height,
                    seed,
                    *settings,
                    noise_router,
                    factories.aquifer,
                )
            });

            let cell_width = settings.noise.cell_width();
            let cell_height = settings.noise.cell_height();
            let cell_x_index = (x - chunk_min_x).div_euclid(cell_width);
            let cell_z_index = (z - chunk_min_z).div_euclid(cell_width);
            let cell_y_index = y.div_euclid(cell_height) - noise_chunk.cell_noise_min_y;
            noise_chunk.advance_cell_x(cell_x_index);
            noise_chunk.select_cell_yz(cell_y_index, cell_z_index);
            noise_chunk.update_for_y(
                y,
                f64::from(y.rem_euclid(cell_height)) / f64::from(cell_height),
            );
            noise_chunk.update_for_x(
                x,
                f64::from((x - chunk_min_x).rem_euclid(cell_width)) / f64::from(cell_width),
            );
            noise_chunk.update_for_z(
                z,
                f64::from((z - chunk_min_z).rem_euclid(cell_width)) / f64::from(cell_width),
            );
            let interpolated_density = noise_chunk.interpolated_density(x, y, z);
            let direct_density = noise_router
                .final_density
                .compute_with_noise(seed, *settings, x, y, z);
            let direct_depth = noise_router
                .depth
                .compute_with_noise(seed, *settings, x, y, z);
            let direct_base3d =
                super::BASE_3D_NOISE_OVERWORLD_DENSITY.compute_with_noise(seed, *settings, x, y, z);
            let direct_sloped =
                super::OVERWORLD_SLOPED_CHEESE_DENSITY.compute_with_noise(seed, *settings, x, y, z);
            let direct_continents = noise_router
                .continents
                .compute_with_noise(seed, *settings, x, y, z);
            let direct_erosion = noise_router
                .erosion
                .compute_with_noise(seed, *settings, x, y, z);
            let direct_ridges = noise_router
                .ridges
                .compute_with_noise(seed, *settings, x, y, z);
            let direct_prelim = noise_router
                .preliminary_surface_level
                .compute_with_noise(seed, *settings, x, y, z);
            let aquifer_state = aquifer.as_mut().and_then(|aquifer| {
                aquifer.compute_substance(&noise_chunk, x, y, z, interpolated_density)
            });
            (
                interpolated_density,
                direct_density,
                direct_base3d,
                direct_sloped,
                direct_depth,
                direct_continents,
                direct_erosion,
                direct_ridges,
                direct_prelim,
                aquifer_state,
            )
        }

        let mut pair_counts = BTreeMap::<(String, String), usize>::new();
        let mut printed = 0_usize;
        for fixture_chunk in fixture_chunks {
            let chunk_x = fixture_chunk
                .get("chunkX")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkX") as i32;
            let chunk_z = fixture_chunk
                .get("chunkZ")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkZ") as i32;
            let y_min = fixture_chunk
                .get("yMin")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include yMin") as i32;
            let y_max = y_min
                + fixture_chunk
                    .get("blocks")
                    .and_then(serde_json::Value::as_array)
                    .and_then(|x_columns| x_columns.first())
                    .and_then(serde_json::Value::as_array)
                    .expect("fixture chunk should include x/y block arrays")
                    .len() as i32;
            let x_columns = fixture_chunk
                .get("blocks")
                .and_then(serde_json::Value::as_array)
                .expect("fixture chunk should include blocks");
            let pos = ChunkPos {
                x: chunk_x,
                z: chunk_z,
            };
            let (base, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let mut carver = base.clone();
            super::apply_configured_carvers_for_biome_source(
                &mut carver,
                biome_source_model,
                noise_settings,
                seed,
            );
            let mut ore = carver.clone();
            super::apply_mineshaft_underground_structures_to_chunk(&mut ore, seed);
            super::apply_underground_ore_decoration_to_chunk(
                &mut ore,
                biome_source_model,
                noise_settings,
                seed,
                None,
            );

            for (local_x, y_column_value) in x_columns.iter().enumerate() {
                let y_column = y_column_value
                    .as_array()
                    .expect("fixture x column should include y array");
                for (y_offset, z_column_value) in y_column.iter().enumerate() {
                    let world_y = y_min + y_offset as i32;
                    if !(48..=80).contains(&world_y) {
                        continue;
                    }
                    let z_column = z_column_value
                        .as_array()
                        .expect("fixture y column should include z array");
                    for (local_z, expected_value) in z_column.iter().enumerate() {
                        let expected = fixture_block_type(expected_value);
                        let world_x = chunk_x * 16 + local_x as i32;
                        let world_z = chunk_z * 16 + local_z as i32;
                        let actual = ore
                            .get_block_state(world_x, world_y, world_z)
                            .unwrap_or_else(|| "minecraft:air".to_string());
                        if expected == actual {
                            continue;
                        }
                        if !is_surface_water_material(expected)
                            && !is_surface_water_material(actual.as_str())
                        {
                            continue;
                        }
                        *pair_counts
                            .entry((expected.to_string(), actual.clone()))
                            .or_default() += 1;
                        if printed >= 16 {
                            continue;
                        }

                        let local_x_i32 = local_x as i32;
                        let local_z_i32 = local_z as i32;
                        let start_height =
                            super::read_world_surface_wg(&base, local_x, local_z) + 1;
                        let biome_y = if noise_settings.legacy_random_source {
                            0
                        } else {
                            start_height
                        };
                        let biome = super::biome_manager_get_biome(
                            biome_source_model,
                            biome_zoom_seed,
                            world_x,
                            biome_y,
                            world_z,
                            &climate_sampler,
                        )
                        .unwrap_or("minecraft:plains");
                        let rule_biome_y = if noise_settings.legacy_random_source {
                            0
                        } else {
                            world_y
                        };
                        let rule_biome = super::biome_manager_get_biome(
                            biome_source_model,
                            biome_zoom_seed,
                            world_x,
                            rule_biome_y,
                            world_z,
                            &climate_sampler,
                        )
                        .unwrap_or("minecraft:plains");
                        let surface_noise_value = surface_noise
                            .as_ref()
                            .map(|snap| {
                                super::normal_noise_sample(
                                    snap,
                                    world_x as f64,
                                    0.0,
                                    world_z as f64,
                                )
                            })
                            .unwrap_or(0.0);
                        let surface_depth = {
                            let mut at_rng = base_rng.at(world_x, 0, world_z);
                            let jitter = super::random_next_f64(&mut at_rng) * 0.25;
                            (surface_noise_value * 2.75 + 3.0 + jitter) as i32
                        };
                        let (
                            density,
                            direct_density,
                            direct_base3d,
                            direct_sloped,
                            direct_depth,
                            direct_continents,
                            direct_erosion,
                            direct_ridges,
                            direct_prelim,
                            aquifer_state,
                        ) = density_and_aquifer_at(
                            pos,
                            world_x,
                            world_y,
                            world_z,
                            seed,
                            noise_settings,
                            noise_router,
                        );
                        let actual_top = (y_min..y_max)
                            .rev()
                            .find(|y| {
                                ore.get_block_state(world_x, *y, world_z)
                                    .is_some_and(|block| block != "minecraft:air")
                            })
                            .map(|y| y + 1)
                            .unwrap_or(y_min);
                        let expected_top = (0..y_column.len())
                            .rev()
                            .find(|offset| {
                                y_column[*offset]
                                    .as_array()
                                    .and_then(|z_column| z_column.get(local_z))
                                    .map(fixture_block_type)
                                    .is_some_and(|block| block != "minecraft:air")
                            })
                            .map(|offset| y_min + offset as i32 + 1)
                            .unwrap_or(y_min);

                        eprintln!(
                            "[worldgen-surface-water-sample] chunk=({chunk_x},{chunk_z}) local=({local_x_i32},{local_z_i32}) world=({world_x},{world_z}) y={world_y} expected={expected} actual={actual} expected_top={expected_top} actual_top={actual_top} base_world_surface_wg={start_height} surface_biome={biome}@{biome_y} rule_biome={rule_biome}@{rule_biome_y} surface_noise={surface_noise_value:.6} surface_depth={surface_depth} density={density:.6} direct_density={direct_density:.6} base3d={direct_base3d:.6} sloped={direct_sloped:.6} depth={direct_depth:.6} continents={direct_continents:.6} erosion={direct_erosion:.6} ridges={direct_ridges:.6} prelim={direct_prelim:.6} aquifer={aquifer_state:?}"
                        );
                        eprintln!(
                            "[worldgen-surface-water-column] expected {}",
                            column_stack_from_fixture(
                                y_column,
                                y_min,
                                local_z,
                                world_y - 6,
                                world_y + 8
                            )
                        );
                        eprintln!(
                            "[worldgen-surface-water-column] actual   {}",
                            column_stack_from_chunk(
                                &ore,
                                world_x,
                                world_z,
                                world_y - 6,
                                world_y + 8
                            )
                        );
                        printed += 1;
                    }
                }
            }
        }

        eprintln!("[worldgen-surface-water-summary] top expected->actual mismatches in y=48..80");
        let mut sorted_pairs = pair_counts.into_iter().collect::<Vec<_>>();
        sorted_pairs.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
        for ((expected, actual), count) in sorted_pairs.into_iter().take(20) {
            eprintln!(
                "[worldgen-surface-water-pair] count={count} expected={expected} actual={actual}"
            );
        }
    }

    #[test]
    #[ignore = "diagnostic for lightweight tree context heightmap drift after surface building"]
    fn normal_overworld_tree_context_height_delta_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let fixture_chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };
        let router =
            super::builtin_noise_router(super::noise_router_id_for_settings(**noise_settings))
                .expect("normal overworld should have a built-in noise router")
                .router;

        let mut total_world_surface_delta = 0_usize;
        let mut total_ocean_floor_delta = 0_usize;
        let mut total_motion_blocking_delta = 0_usize;
        let mut total_columns = 0_usize;
        for fixture_chunk in fixture_chunks {
            let chunk_x = fixture_chunk
                .get("chunkX")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkX") as i32;
            let chunk_z = fixture_chunk
                .get("chunkZ")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkZ") as i32;
            let pos = ChunkPos {
                x: chunk_x,
                z: chunk_z,
            };
            let (surface_chunk, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let live_heights =
                super::tree_decoration_terrain_heights(&surface_chunk, noise_settings);
            let lightweight_heights =
                super::noise_tree_context_heights(pos, noise_settings, seed, router);

            let mut chunk_world_surface_delta = 0_usize;
            let mut chunk_ocean_floor_delta = 0_usize;
            let mut chunk_motion_blocking_delta = 0_usize;
            let mut examples = Vec::new();
            for local_z in 0..16_usize {
                for local_x in 0..16_usize {
                    let index = local_z * 16 + local_x;
                    let live_world_surface = live_heights.world_surface[index];
                    let lightweight_world_surface = lightweight_heights.world_surface[index];
                    let live_ocean_floor = live_heights.ocean_floor[index];
                    let lightweight_ocean_floor = lightweight_heights.ocean_floor[index];
                    let live_motion_blocking = live_heights.motion_blocking[index];
                    let lightweight_motion_blocking = lightweight_heights.motion_blocking[index];
                    let differs = live_world_surface != lightweight_world_surface
                        || live_ocean_floor != lightweight_ocean_floor
                        || live_motion_blocking != lightweight_motion_blocking;
                    if !differs {
                        continue;
                    }
                    if live_world_surface != lightweight_world_surface {
                        chunk_world_surface_delta += 1;
                    }
                    if live_ocean_floor != lightweight_ocean_floor {
                        chunk_ocean_floor_delta += 1;
                    }
                    if live_motion_blocking != lightweight_motion_blocking {
                        chunk_motion_blocking_delta += 1;
                    }
                    if examples.len() < 8 {
                        examples.push(format!(
                            "local=({local_x},{local_z}) world=({},{}) live_ws={} light_ws={} live_of={} light_of={} live_mb={} light_mb={}",
                            chunk_x * 16 + local_x as i32,
                            chunk_z * 16 + local_z as i32,
                            live_world_surface,
                            lightweight_world_surface,
                            live_ocean_floor,
                            lightweight_ocean_floor,
                            live_motion_blocking,
                            lightweight_motion_blocking
                        ));
                    }
                }
            }
            total_world_surface_delta += chunk_world_surface_delta;
            total_ocean_floor_delta += chunk_ocean_floor_delta;
            total_motion_blocking_delta += chunk_motion_blocking_delta;
            total_columns += 16 * 16;
            eprintln!(
                "[tree-context-height-delta] chunk=({chunk_x},{chunk_z}) world_surface={} ocean_floor={} motion_blocking={} examples={}",
                chunk_world_surface_delta,
                chunk_ocean_floor_delta,
                chunk_motion_blocking_delta,
                examples.join(" | ")
            );
        }
        eprintln!(
            "[tree-context-height-delta-summary] chunks={} columns={} world_surface={} ocean_floor={} motion_blocking={}",
            fixture_chunks.len(),
            total_columns,
            total_world_surface_delta,
            total_ocean_floor_delta,
            total_motion_blocking_delta
        );
    }

    #[test]
    #[ignore = "diagnostic for lightweight tree context synthetic block drift"]
    fn normal_overworld_tree_context_block_delta_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let fixture_chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };
        let router =
            super::builtin_noise_router(super::noise_router_id_for_settings(**noise_settings))
                .expect("normal overworld should have a built-in noise router")
                .router;

        let mut total_counts = BTreeMap::<(String, String), usize>::new();
        for fixture_chunk in fixture_chunks {
            let chunk_x = fixture_chunk
                .get("chunkX")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkX") as i32;
            let chunk_z = fixture_chunk
                .get("chunkZ")
                .and_then(serde_json::Value::as_i64)
                .expect("fixture chunk should include chunkZ") as i32;
            let pos = ChunkPos {
                x: chunk_x,
                z: chunk_z,
            };
            let (surface_chunk, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let lightweight = super::LightweightTreeContextChunk {
                terrain_heights: super::noise_tree_context_heights(
                    pos,
                    noise_settings,
                    seed,
                    router,
                ),
                min_y: noise_settings.noise.min_y,
                max_y: noise_settings.noise.min_y + noise_settings.noise.height,
            };

            let mut chunk_counts = BTreeMap::<(String, String), usize>::new();
            let mut examples = Vec::new();
            for local_z in 0..16_usize {
                for local_x in 0..16_usize {
                    let index = local_z * 16 + local_x;
                    let ocean_floor = lightweight.terrain_heights.ocean_floor[index];
                    let world_surface = lightweight.terrain_heights.world_surface[index];
                    let min_y =
                        (ocean_floor.min(world_surface) - 6).max(noise_settings.noise.min_y);
                    let max_y = (world_surface + 8)
                        .min(noise_settings.noise.min_y + noise_settings.noise.height - 1);
                    let world_x = chunk_x * 16 + local_x as i32;
                    let world_z = chunk_z * 16 + local_z as i32;
                    for y in min_y..=max_y {
                        let live = surface_chunk
                            .get_block_state_name(world_x, y, world_z)
                            .unwrap_or("minecraft:air");
                        let synthetic = lightweight.synthetic_block_state(world_x, y, world_z);
                        if live == synthetic {
                            continue;
                        }
                        *chunk_counts
                            .entry((live.to_string(), synthetic.to_string()))
                            .or_default() += 1;
                        *total_counts
                            .entry((live.to_string(), synthetic.to_string()))
                            .or_default() += 1;
                        if examples.len() < 8 {
                            examples.push(format!(
                                "world=({world_x},{y},{world_z}) live={live} synthetic={synthetic} of={ocean_floor} ws={world_surface}"
                            ));
                        }
                    }
                }
            }

            let mut sorted = chunk_counts.into_iter().collect::<Vec<_>>();
            sorted.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
            let summary = sorted
                .into_iter()
                .take(8)
                .map(|((live, synthetic), count)| format!("{count}:{live}->{synthetic}"))
                .collect::<Vec<_>>()
                .join(", ");
            eprintln!(
                "[tree-context-block-delta] chunk=({chunk_x},{chunk_z}) top_pairs=[{}] examples={}",
                summary,
                examples.join(" | ")
            );
        }

        eprintln!("[tree-context-block-delta-summary] top live->synthetic mismatches");
        let mut sorted = total_counts.into_iter().collect::<Vec<_>>();
        sorted.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
        for ((live, synthetic), count) in sorted.into_iter().take(20) {
            eprintln!(
                "[tree-context-block-delta-pair] count={count} live={live} synthetic={synthetic}"
            );
        }
    }

    #[test]
    #[ignore = "diagnostic for tree placement feature seed/index drift"]
    fn normal_overworld_tree_feature_seed_candidate_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };
        let router_id = super::noise_router_id_for_settings(**noise_settings);
        let noise_router = super::builtin_noise_router(router_id)
            .map(|entry| entry.router)
            .expect("normal overworld should have a built-in noise router");
        let climate_sampler =
            super::ClimateSampler::from_noise_router(&noise_router, seed, **noise_settings);
        let global_biome_steps = super::possible_biome_feature_steps_for_source(biome_source_model);
        let global_features_per_step =
            super::build_features_per_step(&global_biome_steps, true).unwrap();
        let region_biome_steps = super::possible_biome_feature_steps_for_decoration_region(
            ChunkPos { x: -1, z: -1 },
            biome_source_model,
            noise_settings,
            &climate_sampler,
        );
        let plan = super::biome_decoration_feature_plan(
            seed,
            -1,
            -1,
            noise_settings.noise.min_y.div_euclid(16),
            &global_features_per_step,
            &region_biome_steps,
        );
        let tree_call = plan
            .feature_calls
            .iter()
            .find(|call| call.feature == "minecraft:trees_birch_and_oak_leaf_litter")
            .expect("forest fixture chunk should schedule birch/oak leaf-litter trees");
        eprintln!(
            "[tree-seed-diagnostic] planned feature={} step={} global_index={} seed={} decoration_seed={}",
            tree_call.feature,
            tree_call.step_index,
            tree_call.global_feature_index,
            tree_call.seed,
            plan.decoration_seed,
        );

        fn locals_for_seed(seed: i64) -> Vec<(usize, usize)> {
            let mut random = crate::random_source::RandomSourceKind::new(
                seed,
                crate::random_source::RandomAlgorithm::Xoroshiro,
            );
            let count = super::live_tree_count(
                super::NoisePreviewTreeCountKind::CountExtra {
                    count: 10,
                    inverse_chance_weight: 10,
                    extra: 1,
                },
                &mut random,
            );
            (0..count)
                .map(|_| {
                    (
                        super::feature_random_next_i32_bound(&mut random, 16) as usize,
                        super::feature_random_next_i32_bound(&mut random, 16) as usize,
                    )
                })
                .collect()
        }

        eprintln!(
            "[tree-seed-diagnostic] planned_locals={:?}",
            locals_for_seed(tree_call.seed)
        );
        for candidate_index in 0..128_i32 {
            let candidate_seed = crate::random_source::feature_seed(
                plan.decoration_seed,
                candidate_index,
                GenerationDecorationStep::VegetalDecoration as i32,
            );
            let locals = locals_for_seed(candidate_seed);
            if locals.contains(&(12, 4)) || locals.contains(&(15, 10)) {
                eprintln!(
                    "[tree-seed-diagnostic] candidate_index={} seed={} locals={:?}",
                    candidate_index, candidate_seed, locals
                );
            }
        }
        let vegetation_features = global_features_per_step
            .get(GenerationDecorationStep::VegetalDecoration as usize)
            .expect("vegetation step should exist");
        for (index, feature) in vegetation_features.features.iter().enumerate() {
            if feature.feature.contains("tree") || feature.feature.contains("birch") {
                eprintln!(
                    "[tree-seed-diagnostic] vegetation_index={} feature={}",
                    index, feature.feature
                );
            }
        }
    }

    #[test]
    #[ignore = "diagnostic parity buckets for base-stone and cave material mismatches"]
    fn normal_overworld_base_stone_mismatch_diagnostic() {
        let fixture_json =
            include_str!("../harness/mineflayer/fixtures/vanilla_worldgen_block_array_target.json");
        let fixture: serde_json::Value =
            serde_json::from_str(fixture_json).expect("vanilla fixture should parse");
        let seed = fixture
            .get("seed")
            .and_then(serde_json::Value::as_str)
            .expect("vanilla fixture should include a seed")
            .parse::<i64>()
            .expect("vanilla fixture seed should parse");
        let fixture_chunks = fixture
            .get("chunks")
            .and_then(serde_json::Value::as_array)
            .expect("fixture should include chunks");

        let preset = super::resolve_world_preset("normal").expect("normal preset should resolve");
        let super::ResolvedChunkGenerator::Noise {
            biome_source_model,
            noise_settings,
            ..
        } = &preset.overworld.generator
        else {
            panic!("normal overworld should use a noise generator");
        };

        let mut stage_chunks: Vec<(&'static str, Vec<LevelChunk>)> = vec![
            ("noise_surface", Vec::new()),
            ("carvers", Vec::new()),
            ("structures", Vec::new()),
            ("ores", Vec::new()),
            ("trees", Vec::new()),
        ];

        for fixture_chunk in fixture_chunks {
            let pos = ChunkPos {
                x: fixture_chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX") as i32,
                z: fixture_chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ") as i32,
            };

            let (base, _, _) = super::generate_real_surface_base_chunk(
                pos,
                biome_source_model,
                noise_settings,
                seed,
            )
            .expect("real-surface base generation should succeed");
            let mut carver = base.clone();
            super::apply_configured_carvers_for_biome_source(
                &mut carver,
                biome_source_model,
                noise_settings,
                seed,
            );
            let mut ore = carver.clone();
            super::apply_mineshaft_underground_structures_to_chunk(&mut ore, seed);
            let structure = ore.clone();
            super::apply_underground_ore_decoration_to_chunk(
                &mut ore,
                biome_source_model,
                noise_settings,
                seed,
                None,
            );
            let mut full = ore.clone();
            super::apply_initial_tree_decoration_to_chunk(
                &mut full,
                biome_source_model,
                noise_settings,
                seed,
                None,
                None,
                None,
            );

            stage_chunks[0].1.push(base);
            stage_chunks[1].1.push(carver);
            stage_chunks[2].1.push(structure);
            stage_chunks[3].1.push(ore);
            stage_chunks[4].1.push(full);
        }

        let tracked_pairs = [
            ("minecraft:tuff", "minecraft:deepslate"),
            ("minecraft:deepslate", "minecraft:tuff"),
            ("minecraft:granite", "minecraft:stone"),
            ("minecraft:stone", "minecraft:granite"),
            ("minecraft:cave_air", "minecraft:deepslate"),
            ("minecraft:deepslate", "minecraft:cave_air"),
            ("minecraft:cave_air", "minecraft:stone"),
            ("minecraft:stone", "minecraft:cave_air"),
        ];

        for (stage_name, chunks) in &stage_chunks {
            let mut counts: BTreeMap<(String, String), usize> = BTreeMap::new();
            let mut y_ranges: BTreeMap<(String, String), (i32, i32)> = BTreeMap::new();
            let mut examples: BTreeMap<(String, String), Vec<BlockPos>> = BTreeMap::new();

            for (chunk_index, fixture_chunk) in fixture_chunks.iter().enumerate() {
                let chunk_x = fixture_chunk
                    .get("chunkX")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkX")
                    as i32;
                let chunk_z = fixture_chunk
                    .get("chunkZ")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include chunkZ")
                    as i32;
                let y_min = fixture_chunk
                    .get("yMin")
                    .and_then(serde_json::Value::as_i64)
                    .expect("fixture chunk should include yMin") as i32;
                let blocks = fixture_chunk
                    .get("blocks")
                    .and_then(serde_json::Value::as_array)
                    .expect("fixture chunk should include blocks");
                let generated = &chunks[chunk_index];

                for (local_x, y_column) in blocks.iter().enumerate() {
                    let y_column = y_column.as_array().expect("x column should be an array");
                    for (y_offset, z_column) in y_column.iter().enumerate() {
                        let world_y = y_min + y_offset as i32;
                        let z_column = z_column.as_array().expect("z column should be an array");
                        for (local_z, expected) in z_column.iter().enumerate() {
                            let expected = expected
                                .as_str()
                                .expect("fixture block should be a string")
                                .split_once('[')
                                .map_or_else(|| expected.as_str().unwrap(), |(id, _)| id);
                            let world_x = chunk_x * 16 + local_x as i32;
                            let world_z = chunk_z * 16 + local_z as i32;
                            let actual = generated
                                .get_block_state(world_x, world_y, world_z)
                                .unwrap_or_else(|| "minecraft:air".to_string());
                            if !tracked_pairs.contains(&(expected, actual.as_str())) {
                                continue;
                            }
                            let key = (expected.to_string(), actual);

                            *counts.entry(key.clone()).or_insert(0) += 1;
                            y_ranges
                                .entry(key.clone())
                                .and_modify(|range| {
                                    range.0 = range.0.min(world_y);
                                    range.1 = range.1.max(world_y);
                                })
                                .or_insert((world_y, world_y));
                            let examples = examples.entry(key).or_default();
                            if examples.len() < 5 {
                                examples.push(BlockPos {
                                    x: world_x,
                                    y: world_y,
                                    z: world_z,
                                });
                            }
                        }
                    }
                }
            }

            eprintln!("[base-stone-diagnostic] stage={stage_name}");
            for &(expected, actual) in &tracked_pairs {
                let key = (expected.to_string(), actual.to_string());
                let count = counts.get(&key).copied().unwrap_or(0);
                if count == 0 {
                    continue;
                }
                let (min_y, max_y) = y_ranges[&key];
                let examples = examples
                    .get(&key)
                    .map(|positions| {
                        positions
                            .iter()
                            .map(|pos| format!("({}, {}, {})", pos.x, pos.y, pos.z))
                            .collect::<Vec<_>>()
                            .join(", ")
                    })
                    .unwrap_or_default();
                eprintln!(
                    "[base-stone-diagnostic] stage={} expected={} actual={} count={} y={}..{} examples={}",
                    stage_name, expected, actual, count, min_y, max_y, examples
                );
            }
        }
    }

